window.__LEX={"G800":"<h1>asumphonos</h1>\n<p>Strong n° 800 <i>Prononciation [as-oom'-fo-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>désaccord de sons, dissonance, non harmonieux, discordant, désuni</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀ·σύμφωνος</b>, <i>anc. att</i>. <b>ἀξύμφωνος, ος, ον :<br>      1</b> dont le son n’est pas d’accord, discordant, PLAT. <i>Rsp. 402</i> d ; DH. <i>Comp. 11 ; fig</i>. qui ne s’accorde pas, en désaccord : τινι, PLAT. <i>Gorg. 482</i> c, avec qqn ; πρὸς ἀλλήλους, NT. <i>Ap. 28, 25,</i> les uns avec les autres ;<br><b>      2</b> qui ne parle pas la même langue, PLAT. <i>Pol. 262</i> d, <i>etc. ;</i> DS. <i>17, 53</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-συμφωνος - ἀσύμφωνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G801":"<h1>asunetos</h1>\n<p>Strong n° 801 <i>Prononciation [as-oon'-ay-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>inintelligent, sans compréhension, stupide, sans intelligence</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀ·σύνετος, ος, ον :<br>      1</b> inintelligent, sot, HDT. <i>3, 81 ;</i> THC. <i>1, 142 ; en parl. de choses,</i> EUR. <i>Hel. 352 ; avec un gén</i>. ἀ. τινος, PLUT. <i>M. 713</i> b, qui ne comprend pas qqe ch. ;<br><b>      2</b> inintelligible, EUR. <i>Ph. 1731</i>.<br><span>•<i> Cp</i>. -ώτερος, EUR. <i>Or. 493</i>. <i>• Sup</i>. ἀξυνετώτατος, HPC. <i>384, 19 ;</i> THC. <i>6, 40</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Anc. att. et ion</i>. ἀξύνετος, AR. <i>Av. 456 ;</i> THC. <i>ll. cc. ;</i> HPC. <i>l. c. etc. mais</i> ἀσύν- <i>345, 22, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-συνετος - ἀσύνετος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Romains (3)</li>\n</ul>\n</td></tr>\n</table>","G802":"<h1>asunthetos</h1>\n<p>Strong n° 802 <i>Prononciation [as-oon'-thet-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>non composé, simple</li>\n<li>briseur de pacte, infidèle, déloyal, inconstant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀ·σύνθετος</b>, <i>anc. att</i>. <b>ἀξύνθετος, ος, ον :<br>      1</b> non composé, simple, PLAT. <i>Phæd. 78</i> c, <i>etc. ;</i> ARSTT. <i>Pol. 1, 1, 3, etc. ;</i><br><b>      2</b> non ajusté, non ordonné, confus, DÉM. <i>383, 6 (au</i> <i>• Sup</i>. -ώτατος).<br><span><b>Étym</b>. ἀ, συντίθημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-συνθετος - ἀσύνθετος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G803":"<h1>asphaleia</h1>\n<p>Strong n° 803 <i>Prononciation [as-fal'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fermeté, stabilité</li>\n<li>certitude, vérité indubitable</li>\n<li>sûreté envers les ennemis et les dangers, sécurité</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀσφάλεια, ας (ἡ)</b> <span>[φᾰ]</span><br><b>   I</b> le fait de ne pas glisser, allure ferme, THC. <i>3, 22 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> stabilité, SOPH. <i>O.R. 51 ;</i> ARSTT. <i>Pol. 6, 5, 2 ;</i><br><b>      2</b> sûreté, sécurité, ESCHL. <i>Suppl. 495 ;</i> SOPH. THC. XÉN. <i>etc. ;</i> ἐν ἀσφαλείᾳ, XÉN. <i>Hier. 2, 10 ;</i> δι' ἀσφαλείας, THC. <i>1, 17 ;</i> μετ' ἀσφαλείας, THC. <i>1, 120,</i> en sûreté ; τινὶ ἀσφάλειαν παρέχεσθαι, PLAT. <i>Crit. 45</i> d ; παρέχειν, XÉN. <i>Cyr. 4, 5, 28 ;</i> διδόναι, XÉN. <i>Hell. 2, 2, 2,</i> pourvoir à la sécurité de qqn (lui procurer un refuge, un sauf-conduit, <i>etc</i>.) ; ἀσφάλεια ἀπὸ τῶν πολεμίων, POL. <i>3, 97,</i> refuge à l’abri de l’ennemi ; <i>au plur</i>. ἀσφάλειαι, période de sécurité, ISOCR. <i>163</i> c, <i>ou</i> places de sûreté, POL. <i>1, 57 ; 3, 69 ;</i><br><b>      3</b> assurance, certitude, THC. <i>2, 11 ;</i> XÉN. <i>Cyr. 7, 4, 5 ;</i> ἀ. λόγου, XÉN. <i>Mem. 4, 6, 15,</i> certitude, <i>d’où</i> évidence d’un raisonnement.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἀσφαλίη, HDT. <i>4, 33 ;</i> HPC. <i>948</i> f ; <i>1253</i> g.<br><span><b>Étym</b>. ἀσφαλής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ασφαλεια - ἀσφάλεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G804":"<h1>asphales</h1>\n<p>Strong n° 804 <i>Prononciation [as-fal-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ferme (ce sur quoi on peut compter)</li>\n<li>certain, vrai, motif exact, cause certaine</li>\n<li>suivi de confirmation</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀ·σφαλής, ής, ές</b> <span>[φᾰ]</span><br><b>   I</b> qui ne glisse pas <i>ou</i> ne tombe pas, <i>d’où :</i><br><b>      1</b> ferme, solide, <i>en parl. de choses</i> (fondements, char, <i>etc</i>.) OD. <i>6, 42 ;</i> PD. HDT. ATT. ; <i>fig</i>. (résolution, volonté, <i>etc</i>. PD. HDT. ATT. ;<br><b>      2</b> <i>en parl. de pers</i>. sûr, qui inspire confiance, sur qui l’on peut compter, SOPH. <i>O.R. 617 ;</i> EUR. <i>Ph. 599 ;</i> THC. <i>1, 69 ;</i> PLAT. <i>Soph. 231</i> a, <i>etc. ; part</i>. prudent, sage, EUR. <i>I.T. 1062 ; en parl. d’un orateur,</i> persuasif, XÉN. <i>Mem. 4, 6, 15 (cf</i>. ἀσφάλεια) ;<br><b>   II</b> qui est en sûreté, <i>en parl. de pers. ou de choses,</i> ATT. ; ὁδὸς ἀ. XÉN. <i>Hell. 5, 4, 51,</i> route sûre ; ἀσφαλές (ἐστι) <i>avec l’inf</i>. AR. <i>Av. 1489 ;</i> EUR. PLAT. <i>etc</i>. c’est une sûreté de, il est prudent de ; φεύγειν αὐτοῖς ἀσφαλέστερον, XÉN. <i>An. 3, 2, 19,</i> il est plus sûr pour eux de fuir ; ἐν ἀσφαλεῖ, THC. <i>8, 39,</i> en sûreté ; μένειν ἐν τῷ ἀσφαλεῖ, XÉN. <i>An. 7, 4, 8,</i> rester en sûreté ; τὸ ἀσφαλές, la sécurité, HDT. <i>1, 109 ;</i> THC. <i>6, 55, etc. ; neutre adv</i>. ἀσφαλὲς αἰεί, OD. <i>6, 42, ou</i> ἔμπεδον ἀσφαλὲς αἰεί, IL. <i>15, 683,</i> solidement et sûrement pour toujours ;<br><b>   III</b> qui met en sûreté : τὸ ἀσφαλές, place de sûreté, place forte, HDT. XÉN.<br><span>•<i> Cp</i>. -έστερος, HPC. <i>406, 48 ;</i> XÉN. <i>An. 3, 2, 19 ; Cyr. 7, 1, 21 etc.</i> <i>• Sup</i>. -έστατος, HPC. <i>98</i> g, <i>etc. ;</i> SOPH. <i>Aj. 1251 ;</i> EUR. <i>I.T. 1062 ;</i> THC. <i>1, 39 ;</i> XÉN. <i>An. 1, 8, 22, etc</i>.<br><span><b>Étym</b>. ἀ, σφάλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-σφαλης - ἀσφαλής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (3)</li>\n<li>Philippiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G805":"<h1>asphalizo</h1>\n<p>Strong n° 805 <i>Prononciation [as-fal-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre ferme, mettre en sécurité (contre le mal), surveiller de près, tenir sous bonne garde</li>\n<li>être rendu sûr</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀσφαλίζω</b> (<i>seul. prés. et impf</i>. ἠσφάλιζον ; <i>au pass., prés., impf., ao</i>. ἠσφαλίσθην <i>et pf</i>. ἠσφάλισμαι) <span>[φᾰ]</span> assurer, fortifier (un lieu, un pays, <i>etc.) acc</i>. POL. <i>18, 13, etc. ; au pass</i>. être fortifié, POL. <i>1, 42, etc. ;</i><br><b><i>Moy.</i></b> (<i>fut</i>. ἀσφαλίσομαι <i>ou</i> ἀσφαλιοῦμαι, <i>ao</i>. ἠσφαλισάμην) ;<br><b>   I <i>tr</i>.<br>      1</b> mettre en sûreté, fortifier, garantir, <i>acc</i>. POL. <i>1, 22, etc. ;</i><br><b>      2</b> mettre en lieu sûr, enfermer, emprisonner, NT. <i>Ap. 16, 24 ;</i><br><b>   II <i>intr.</i></b> se mettre en garde, prendre ses sûretés : τι, POL. <i>6, 23, etc</i>. contre qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. pass</i>. ἠσφάλισμαι, <i>au sens pass</i>. POL. <i>1, 42, etc. ;</i> DH. <i>7, 44 ; au sens moy</i>. POL. <i>5, 43</i>.<br><span><b>Étym</b>. ἀσφαλής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ασφαλιζω - ἀσφαλίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G806":"<h1>asphalos</h1>\n<p>Strong n° 806 <i>Prononciation [as-fal-oce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sûreté (pour prévenir une évasion), assurément, avec certitude</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀσφαλῶς</b> <span>[φᾰ]</span> <i>adv. :</i><br><b>      1</b> sans glisser, solidement, fermement, sûrement, HDT. <i>1, 86 ;</i> AND. <i>28, 1 ;</i> SOPH. <i>etc. ; dans</i> HOM. <i>avec</i> ἔμπεδον : ἔμπεδον ἀσφαλέως (<i>ion</i>.) IL. <i>13, 141 ;</i> OD. <i>13, 86,</i> solidement et sûrement (<i>cf</i>. ἔ. ἀσφαλές ; <i>v</i>. ἀσφαλής) ;<br><b>      2</b> en sûreté, avec sécurité, XÉN. PLAT.<br><span>•<i> Cp</i>. ἀσφαλεστέρως, HPC. <i>Prorrh. 100 ;</i> THC. <i>4, 71, ou</i> ἀσφαλέστερον, HDT. <i>2, 161 ;</i> PLAT. <i>Phæd. 85</i> d, <i>etc.</i> <i>• Sup</i>. ἀσφαλέστατα, HPC. <i>Prorrh. 105 ;</i> PLAT. <i>Rsp. 467</i> b.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἀσφαλέως, IL. <i>13, 141, etc. ;</i> OD. <i>13, 86, etc. ;</i> HÉS. <i>Th. 86 ;</i> HDT. <i>1, 86, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ασφαλως - ἀσφαλῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G807":"<h1>aschemoneo</h1>\n<p>Strong n° 807 <i>Prononciation [as-kay-mon-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>agir d'une manière malséante, être peu convenable, manquer aux convenances</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀσχημονέω-ῶ</b>, avoir une mauvaise tenue, se tenir avec inconvenance, manquer aux bienséances, EUR. <i>Hec. 407 ;</i> PLAT. <i>Rsp. 506</i> d, <i>etc. ;</i> εἴς τινα, DH. <i>2, 26,</i> envers qqn.<br><span><b>Étym</b>. ἀσχήμων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ασχηονεω - ἀσχημονέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G808":"<h1>aschemosune</h1>\n<p>Strong n° 808 <i>Prononciation [as-kay-mos-oo'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>choses honteuses, une action malséante\n<ol type=\"a\">\n<li>organes génitaux</li>\n<li>nudité, honte</li>\n</ol>\n</li>\n<li>manque de forme</li>\n<li>difformité, laideur</li>\n<li>inconvenance, indécence</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀσχημοσύνη, ης (ἡ)</b> <span>[ῠ]</span><br><b>      1</b> manque de forme, ARSTT. <i>Phys. 1, 7, 8 ;</i><br><b>      2</b> difformité, laideur, PLAT. <i>Conv. 196</i> a ; ARSTT. <i>Pol. 8, 6, 14 ;</i><br><b>      3</b> <i>fig</i>. inconvenance, indécence, PLAT. <i>Rsp. 401</i> a.<br><span><b>Étym</b>. ἀσχήμων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ασχημοσυνη - ἀσχημοσύνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G809":"<h1>askemon</h1>\n<p>Strong n° 809 <i>Prononciation [as-kay'-mone]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>déformé, disgracieux, mal conformé, difforme</li>\n<li>indécent, malséant, inconvenant, honteux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀ·σχήμων, ων, ον</b>, <i>gén</i>. <b>ονος :<br>      1</b> mal conformé, difforme, HPC. <i>Art. 796 ;</i><br><b>      2</b> <i>fig</i>. inconvenant, indécent, honteux, HDT. <i>7, 160,</i> PLAT. <i>Phil. 46</i> a ; ARSTT.<br><span>•<i> Cp</i>. -ονέστερος, HPC. <i>824</i> g ; PLAT. <i>Leg. 918</i> b ; ARSTT. <i>Nic. 4, 7, 11, etc</i>.<br><span><b>Étym</b>. ἀ, σχῆμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-σχημων - ἀσχήμων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G810":"<h1>asotia</h1>\n<p>Strong n° 810 <i>Prononciation [as-o-tee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>abandonné, vie dissolue, débauche d'ou perdition</li>\n<li>libertinage, prodigalité</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀσωτία, ας (ἡ)</b> vie de prodigue, débauche, PLAT. <i>Rsp. 560</i> e ; ARSTT. <i>Nic. 4, 1, 3</i>.<br><span><b>Étym</b>. ἄσωτος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ασωτια - ἀσωτία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Tite (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G811":"<h1>asotos</h1>\n<p>Strong n° 811 <i>Prononciation [as-o'-toce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>manières dissolues, d'une façon libertine, dans la perdition, qui ne peut être sauvé (de α privatif et de σωτηρια salut)</li>\n<li>en prodigue, en libertin</li>\n<li>dans un état désespéré, misérable, détestable</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀσώτως</b>, <i>adv</i>., en prodigue, en libertin, DÉM. <i>1025, 19</i>.<br><span>•<i> Cp</i>. -ότερον, DC. <i>62, 27</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ασωτος - ἀσώτως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G812":"<h1>atakteo</h1>\n<p>Strong n° 812 <i>Prononciation [at-ak-teh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être désordonné\n<ol type=\"a\">\n<li>soldats non alignés ou quittant les rangs</li>\n<li>celui qui néglige le devoir, sans loi</li>\n<li>mener une vie désordonnée, vivre dans le désordre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀτακτέω-ῶ</b>, <i>f</i>. ήσω :<br><b>      1</b> ne pas garder son poste, être indiscipliné, XÉN. <i>Cyr. 7, 2, 6 ;</i> DÉM. <i>31, 17 ; fig</i>. ἀ. τῆς πατρίου ἀγωγῆς, PLUT. <i>M. 235</i> b, déserter le genre de vie de ses pères ;<br><b>      2</b> <i>abs</i>. se livrer au désordre, LYS. <i>141, 19 ;</i> XÉN. <i>Œc. 7, 31</i>.<br><span><b>Étym</b>. ἄτακτος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ατακτεω - ἀτακτέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G813":"<h1>ataktos</h1>\n<p>Strong n° 813 <i>Prononciation [at'-ak-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>désordonné, hors des rangs (souvent pour des soldats)</li>\n<li>irrégulier, démesuré, plaisirs immodérés</li>\n<li>déviant de l'ordre prescrit ou des règlements, indiscipliné</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄ·τακτος, ος, ον :<br>      1</b> qui n’est pas en ordre de bataille, HDT. <i>6, 93 ;</i> THC. <i>8, 105, etc. ;</i><br><b>      2</b> qui n’est pas à son poste, qui ne prend pas part au combat, LYCURG. <i>152, 42 ;</i><br><b>      3</b> qui ne reste pas à son poste, <i>d’où</i> indiscipliné, THC. <i>8, 10 ;</i> XÉN. ARSTT. ; <i>en gén</i>. désordonné, irrégulier, HPC. ARSTT. ; <i>en parl. de l’abus des plaisirs,</i> PLAT. <i>Leg. 660</i> b ; <i>840</i> e.<br><span>•<i> Cp</i>. -ότερος, THC. <i>8, 105 ;</i> ARSTT. <i>Pol. 6, 4 ; etc</i>.<br><span><b>Étym</b>. ἀ, τάσσω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-τακτος - ἄτακτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G814":"<h1>ataktos</h1>\n<p>Strong n° 814 <i>Prononciation [at-ak'-toce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>désordonné, hors des rangs (souvent pour des soldats)</li>\n<li>irrégulier, excessif, démesuré, plaisirs immodérés</li>\n<li>déviant de l'ordre prescrit ou des règles</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀτάκτως</b>, <i>adv. :</i><br><b>      1</b> en désordre, <i>en parl. de troupes,</i> THC. <i>2, 91 ; 3, 108, etc. ;</i><br><b>      2</b> d’une façon irrégulière, HPC. <i>945</i> e.<br><span>•<i> Cp</i>. -ότερον, THC. <i>6, 97 ;</i> ISOCR. <i>9</i> a, <i>etc. ; ou</i> -οτέρως, D. PHAL. <i>c. 53</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ατακτως - ἀτάκτως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Thessaloniciens (2)</li>\n</ul>\n</td></tr>\n</table>","G815":"<h1>ateknos</h1>\n<p>Strong n° 815 <i>Prononciation [at'-ek-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans descendant, sans progéniture, sans enfant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄ·τεκνος, ος, ον</b>, qui n’a pas d’enfants, HÉS. <i>O. 600 ;</i> ESCHL. SOPH. ; <i>en parl. d’animaux,</i> qui n’a pas de petits, ARSTT. <i>G.A. 3, 1 ; avec un gén</i>. ἄ. ἀρσένων παίδων, EUR. <i>Bacch. 1306,</i> sans enfants mâles.<br><span><b><span class=\"arrow\"></span></b> <span>[ᾰε̆]</span> ESCHL. <i>Sept. 828 ;</i> <span>[ᾰε̄]</span> SOPH. <i>El. 164</i>.<br><span><b>Étym</b>. ἀ, τέκνον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-τεκνος - ἄτεκνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G816":"<h1>atenizo</h1>\n<p>Strong n° 816 <i>Prononciation [at-en-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fixer les yeux sur, regarder fixement à</li>\n<li>regarder en toute chose</li>\n<li>métaph : fixer son esprit sur quelqu'un comme exemple</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀτενίζω</b> (<i>seul. prés. et ao</i>.) être tendu fortement, <i>d’où :</i><br><b>      1</b> avoir les yeux tendus : εἴς τινα, NT. <i>Ap. 6, 15 ;</i> SEXT. <i>etc. ;</i> εἴς τι, ARSTT. <i>Meteor. 1, 6, 12 ;</i> POL. <i>6, 11 ; etc. ;</i> πρός τι, ARSTT. <i>Probl. 39, 19, 1 ;</i> LUC. <i>Char. 11 ;</i> THÉM. <i>etc. ; ou avec le dat</i>. τινί, PLUT. <i>M. 881</i> a ; NT. <i>Luc. 22, 56 ; Ap. 3, 12,</i> avoir les yeux fixés sur qqn <i>ou</i> qqe ch. ; <i>en parl. des yeux eux-mêmes :</i> ὀφθαλμοὶ ἀτενίζοντές τινι, NT. <i>Luc. 4, 20,</i> regards fixés sur qqn ; <i>fig. en parl. de l’esprit,</i> ARSTT. <i>Phys. 1, 9, 3 ;</i><br><b>      2</b> demeurer tendu, fixe, inflexible, <i>d’où</i> s’obstiner, ATH. <i>313</i> f ;<br><b><i>Moy.</i></b> regarder fixement, SIM. (ATH. <i>591</i> a).<br><span><b><span class=\"arrow\"></span></b> <i>Ao. seul. sbj. 2 sg</i>. ἀτενίσῃς, LUC. <i>Char. 16 ; opt</i>. ἀτενίσαιμι, POL. <i>6, 11 ; inf</i>. ἀτενίσαι, NT. <i>2Cor. 3, 7 ; part</i>. ἀτενίσας, HPC. <i>1212</i> d ; <i>etc</i>.<br><span><b>Étym</b>. ἀτενής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ατενιζω - ἀτενίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 14 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Actes (10)</li>\n<li>2 Corinthiens (3)</li>\n</ul>\n</td></tr>\n</table>","G817":"<h1>ater</h1>\n<p>Strong n° 817 <i>Prononciation [at'-er]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans, en dehors de, à l'insu</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄτερ</b> <span>[ᾰ]</span> <i>prép. :</i><br><b>      1</b> à l’écart de : ἄτερ ἥμενος ἄλλων, IL. <i>1, 498,</i> assis à l’écart des autres ; <i>joint à</i> νόσφιν : νόσφιν ἄ. HÉS. <i>O. 91,</i> séparément, à l’écart ;<br><b>      2</b> <i>p. suite,</i> à l’exclusion de, sans : ἄ. Ζηνός, IL. <i>15, 292,</i> sans l’aveu de Zeus ; <i>souv. après son rég</i>. SIM. (ATH. <i>512</i> d) ; PD. <i>P. 2, 8 ; 5, 76 ;</i> TRAG. <i>etc. ; rare en prose,</i> DH. <i>3, 10 ;</i> PLUT. <i>Cato mi. 5 ;</i> SPT. <i>etc. ; en prose ion</i>. HPC. <i>87</i> d, <i>88</i> b ; <i>etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ατερ - ἄτερ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G818":"<h1>atimazo</h1>\n<p>Strong n° 818 <i>Prononciation [at-im-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>déshonorer, insulter, traiter avec mépris, traiter indignement\n<ol type=\"a\">\n<li>que ce soit en parole, pensée ou action</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀτιμάζω</b> <span>(<i>f</i>. άσω, <i>ao</i>. ἠτίμασα, <i>pf</i>. ἠτίμακα <span>[μᾱ]</span> ; <i>pass. f</i>. ἀτιμασθήσομαι, <i>ao</i>. ἠτιμάσθην, <i>pf</i>. ἠτίμασμαι)</span> <span>[ῑ]</span><br><b>   I. 1</b> déshonorer : τινά, IL. <i>9, 450 ;</i> OD. <i>6, 283,</i> qqn ; οἶκον, OD. <i>21, 332,</i> une maison ; <i>au pass</i>. être déshonoré, outragé : πρός τινος, PD. (ATH. <i>601</i> d) ; HDT. <i>1, 61,</i> par qqn ; <i>abs</i>. SOPH. <i>O.R. 1081 ;</i><br><b>      2</b> frapper d’une peine infamante, THC. <i>3, 42 ;</i> XÉN. <i>Cyr. 1, 6, 20 ; en parl. des censeurs à Rome,</i> DC. <i>38, 13 ;</i><br><b>   II</b> mépriser, traiter avec dédain : τινά, OD. <i>8, 309, etc. ;</i> ESCHL. <i>Sept. 1018, etc. ;</i> τι, PLAT. <i>Phæd. 107</i> a, qqe ch. ; <i>avec double acc</i>. ἔπη ἃ ἀτιμάζεις πόλιν, SOPH. <i>O.R. 340,</i> les paroles méprisantes que tu prononces sur la cité ;<br><b>   III</b> juger indigne : τινά τινος, ESCHL. <i>Pr. 783 ;</i> SOPH. <i>O.C. 49,</i> juger qqn indigne de qqe ch. ; <i>avec un inf</i>. οὐκ ἀτιμάσω θεοὺς προσειπεῖν, EUR. <i>H.f. 608,</i> je ne dédaignerai pas d’invoquer les dieux ; μή μ' ἀτιμάσῃς τὸ μὴ οὐ θανεῖν σύν σοι, SOPH. <i>Ant. 544,</i> ne me juge pas indigne de mourir avec toi.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. itér. 3 sg</i>. ἀτιμάζεσκε, IL. <i>9, 450</i>.<br><span><b>Étym</b>. ἄτιμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ατιμαζω - ἀτιμάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Romains (2)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G819":"<h1>atimia</h1>\n<p>Strong n° 819 <i>Prononciation [at-ee-mee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>déshonneur, ignominie, disgrâce, vil, méprisable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀτιμία, ας (ἡ)</b> <span>[τῑ]</span><br><b>      1</b> mépris, OD. <i>13, 142 ;</i> PD. <i>O. 4, 23 ;</i> TRAG. HDT. ATT. ; ἐν ἀτιμίῃ (<i>ion</i>.) τινὰ ἔχειν, HDT. <i>3, 3,</i> ne faire aucun cas de qqn ; ἀτιμίην προστιθέναι τινί, HDT. <i>7, 11,</i> marquer son mépris à qqn ; ἀτιμίης κυρεῖν πρός τινος, HDT. <i>7, 158,</i> rencontrer le mépris de qqn ; τινὰ ἐν πολλῇ ἀτιμίᾳ ἔχειν, XÉN. <i>Cyr. 2, 2, 13,</i> avoir un grand mépris pour qqn ; ἐν ἀτιμίᾳ εἶναι, XÉN. <i>Mem. 1, 2, 51,</i> être méprisé <i>ou</i> dédaigné ; <i>au plur</i>. marques de mépris, PLAT. <i>Pol. 309</i> a, <i>etc. ;</i> DÉM. <i>296, 21, etc. ;</i><br><b>      2</b> <i>à Athènes,</i> privation (partielle <i>ou</i> totale) des droits de citoyen, ESCHL. <i>Eum. 395 ;</i> AND. <i>10, 13, etc. ;</i> ARSTT. <i>Pol. 7, 17 ;</i><br><b>      3</b> <i>en parl. de choses,</i> aspect sordide (des vêtements, de la chevelure, <i>etc</i>. en signe de deuil) ESCHL. <i>Pers. 847 ;</i> CRAT. (ATH. <i>410</i> d).<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἀτιμίη, HDT. <i>ll. cc</i>. <span>[ῑῑη]</span> OD. <i>l. c. ;</i> TYRT. (LYCURG. <i>162, 40</i>).<br><span><b>Étym</b>. ἄτιμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-τιμια - ἀτιμία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (2)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G820":"<h1>atimos</h1>\n<p>Strong n° 820 <i>Prononciation [at'-ee-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sans honneur, déshonoré</li>\n<li>bas, moindre estime, méprisé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄ·τιμος, ος, ον</b> <span>[ῑ]</span><br><b>A</b> (τιμή, prix, évaluation) :<br><b>   I</b> sans prix, de peu de prix, HPC. <i>236, 31 ;</i> DS. <i>17, 66 ; p. opp. à</i> τίμιος, XÉN. <i>Vect. 4, 10 ;</i><br><b>   II</b> sans paiement, <i>d’où :</i><br><b>      1</b> sans compensation : τοῦ οἶκον ἄτιμον ἔδεις, OD. <i>16, 431,</i> dont tu dévores gratuitement la maison ;<br><b>      2</b> impuni, PLAT. <i>Leg. 855</i> c ;<br><b>      3</b> non vengé, ESCHL. <i>Ag. 1279 ;</i> EUR. <i>Hipp. 1417 ;</i><br><b>      4</b> non taxé, DH. ;<br><b>B</b> (τιμή, honneur) :<br><b>   I</b> <i>en parl. de pers. :</i><br><b>      1</b> non honoré, déshonoré, méprisé, IL. <i>1, 171, etc. ;</i> τινι, SOPH. <i>Aj. 440 ou</i> ἔκ τινος, SOPH. <i>O.C. 51,</i> par qqn ;<br><b>      2</b> jugé indigne de, <i>gén</i>. ESCHL. <i>Ch. 408, etc. ;</i> SOPH. <i>O.R. 789 ;</i> πόνων, ESCHL. <i>Ag. 354,</i> récompense digne de la peine qu’on a prise ; ἄ. τοῦ τεθνηκότος, SOPH. <i>El. 1214,</i> indigne du mort ;<br><b>      3</b> noté d’infamie, HDT. <i>1, 173 ; part. à Athènes,</i> privé (en partie <i>ou</i> en totalité) des droits de citoyen (<i>cf</i>. ἀτιμία), DÉM. <i>122, 12 ; 524 fin ;</i> AND. <i>10, 13, etc. ; p. opp. à</i> ἐπίτιμος, AR. <i>Av. 766, etc. ;</i> AND. <i>19, 13 ; avec un gén</i>. ἄ. τῆς πόλεως, LYS. <i>122, 9,</i> privé des droits de citoyen ; ἄ. γερῶν, THC. <i>3, 58,</i> dépouillé de ses privilèges ; ἄ. τοῦ συμϐουλεύειν, DÉM. <i>200, 15,</i> privé du droit de participer aux délibérations ;<br><b>   II</b> <i>en parl. de choses :</i><br><b>      1</b> non honorable, HDT. <i>5, 6 ;</i> ἄ. μόρος, ESCHL. <i>Sept. 589,</i> sort déshonorant ; ἄτιμον ποιεῖσθαί τι, SOPH. <i>Ant. 78,</i> traiter qqe ch. avec mépris <i>ou</i> dédain ; τὸ τιμιώτερον καὶ τὸ ἀτιμότερον, ARSTT. <i>P.A. 3, 10, 3, etc</i>. les parties nobles et les parties honteuses, <i>en parl. du corps ;</i><br><b>      2</b> peu honorable : ἕδρα ἀτιμότερα, XÉN. <i>Cyr. 8, 4, 5,</i> siège <i>ou</i> place moins honorable.<br><span>•<i> Cp</i>. -ότερος, IL. <i>16, 90 ;</i> PD. <i>O. 8, 69 ;</i> HPC. <i>236, 31 ;</i> XÉN. <i>An. 7, 7, 50 ; Œc. 7, 42, etc. ;</i> ISOCR. <i>234</i> e ; <i>etc. (v. ci-dessus)</i>. <i>• Sup</i>. -ότατος, IL. <i>1, 516 ;</i> CALL. <i>Del. 131 ;</i> THCR. <i>Idyl. 14, 49 ; etc</i>.<br><span><b>Étym</b>. ἀ, τιμή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-τιμος - ἄτιμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G821":"<h1>atimoo</h1>\n<p>Strong n° 821 <i>Prononciation [at-ee-mo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>déshonorer, marquer de disgrâce</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀτιμόω-ῶ</b> <span>(<i>f</i>. ώσω, <i>ao</i>. ἠτίμωσα, <i>pf</i>. ἠτίμωκα, <i>etc</i>.)</span><br><b>      1</b> dédaigner, ESCHL. <i>Suppl. 644 ; au pass</i>. être déshonoré <i>ou</i> méprisé, HDT. <i>4, 66 ; 7, 231 ;</i> ESCHL. EUR. ;<br><b>      2</b> <i>à Athènes,</i> priver des droits de citoyen (<i>v</i>. ἀτιμία), AR. <i>Pax 743 ;</i> AND. <i>5, 28, etc. ;</i> DÉM. <i>253, 3, etc. ; au pass</i>. PLAT. <i>Rsp. 553</i> b.<br><span><b>Étym</b>. ἄτιμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ατιμοω - ἀτιμόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>","G822":"<h1>atmis</h1>\n<p>Strong n° 822 <i>Prononciation [at-mece']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vapeur humide</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀτμίς, ίδος (ἡ)</b> <span>[ῑδ]</span> vapeur humide, <i>p. opp. à</i> καπνός, ARSTT. <i>Meteor. 2, 4, 1, etc. ; d’où</i> vapeur <i>en gén</i>. HDT. <i>4, 75 ;</i> PLAT. <i>Tim. 86</i> e.<br><span><b>Étym</b>. <i>cf</i>. ἀτμός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ατμις - ἀτμίς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G823":"<h1>atomos</h1>\n<p>Strong n° 823 <i>Prononciation [at'-om-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui ne peut être coupé en deux, ou divisé, indivisible\n<ol type=\"a\">\n<li>un moment de temps, un instant, temps si court qu'on ne peut le diviser métaphore : plus rapide que la fission de l'atome</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄ·τομος, ος, ον :<br>      1</b> non coupé, <i>en parl. d’une prairie non fauchée,</i> SOPH. <i>Tr. 200 ; de la barbe,</i> EPHIPP. (ATH. <i>509</i> d) ;<br><b>      2</b> qu’on ne peut couper, indivisible, PLAT. <i>Soph. 229</i> d ; ARSTT. <i>Phys. 3, 6, 2 ; etc. ;</i> ἄ. σῶμα, DÉMOCR. (ARSTT. <i>Cæl. 3, 4, 8, etc.) ou subst</i>. τὸ ἄτομον, STR. <i>298 ;</i> SEXT. <i>etc. ; ou</i> ἡ ἄτομος (<i>s.-e</i>. οὐσία), CIC. <i>Fin. 1, 6 ;</i> PLUT. <i>M. 1110</i> f, <i>etc</i>. corpuscule indivisible <i>ou</i> atome, <i>élément constitutif de la matière ; en parl. du temps,</i> si court qu’on ne le peut diviser, ARSTT. <i>Phys. 8, 8, 24, etc. ;</i> ἐν ἀτόμῳ, NT. <i>1Cor. 15, 52,</i> en un instant ;<br><b>      3</b> τὸ ἄτομον, <i>c</i>. ὑοσκύαμος, DIOSC. <i>4, 69</i>.<br><span><b>Étym</b>. ἀ, τέμνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-τομος - ἄτομος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G824":"<h1>atopos</h1>\n<p>Strong n° 824 <i>Prononciation [at'-op-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>non à sa place, non convenable, malséant, inconvenant</li>\n<li>impropre, méchant</li>\n<li>injuste</li>\n<li>incommode, nuisible</li>\n<li>de travers, mal, déraisonnable, fâcheux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄ·τοπος, ος, ον</b>, qui n’est pas en son lieu et place, <i>d’où :</i><br><b>      1</b> extraordinaire, étrange, insolite, HPC. <i>Aph. 1251 ;</i> EUR. <i>I.T. 842 ;</i> AR. <i>Eccl. 956 ; p. opp. à</i> εἰωθώς, THC. <i>3, 38 ;</i><br><b>      2</b> <i>p. suite,</i> extravagant, absurde, inconvenant, XÉN. <i>Cyr. 7, 2, 17 ; etc</i>. PLAT. <i>Pol. 298</i> e, <i>etc. ;</i> AND. DÉM. <i>etc. ;</i> ἄτοπόν ἐστι, <i>avec l’inf</i>. PHÉRÉCR. EUB. <i>ou avec</i> εἰ, PLAT. <i>Gorg. 521</i> d, il est étrange <i>ou</i> absurde de <i>ou</i> que ; <i>en parl. de pers</i>. étrange, absurde, insensé, PLAT. <i>Gorg. 494</i> d, <i>etc. ; joint à</i> δυσχερής, DÉM. <i>439, 27</i>.<br><span>•<i> Cp</i>. -ώτερος, PLAT. <i>1 Alc. 106</i> a. <i>• Sup</i>. -ώτατος, PLAT. <i>Phædr. 230</i> c, <i>Rsp. 475</i> b ; DÉM. <i>16, 23</i>.<br><span><b>Étym</b>. ἀ, τόπος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-τοπος - ἄτοπος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G825":"<h1>Attaleia</h1>\n<p>Strong n° 825 <i>Prononciation [at-tal'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Attalie (Angl. Attalia) = « appartenant à Attale »\n<ol><li>cité maritime de Pamphylie, côte orientale, bâtie et nommée par Attale Philadelphe, roi de Pergame, vers 150 av. J.-C. Paul s'y embarqua pour Antioche lors de son premier voyage missionnaire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀττάλεια, ας (ἡ)</b> <span>[τᾰ]</span> Attaleia, <i>v. de Pamphylie,</i> PLUT. NT.<br><span><b>Étym</b>. Ἄτταλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ατταλεια - Ἀττάλεια</font>\n<br><br>vient de Attale (un roi de Pergame)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G826":"<h1>augazo</h1>\n<p>Strong n° 826 <i>Prononciation [ow-gad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rayonner sur, irradier, resplendir</li>\n<li>être brillant, briller puissamment</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐγάζω</b> (<i>seul. prés. et ao. act. et pass</i>.) ;<br><b>   I <i>tr</i>.<br>      1</b> éclairer, illuminer, <i>acc</i>. EUR. <i>Hec. 637 ;</i><br><b>      2</b> fixer les yeux sur, <i>d’où</i> voir clairement, <i>acc</i>. SOPH. <i>Ph. 217 ;</i><br><b>   II <i>intr.</i></b> briller, SPT. <i>Lev. 13, 25, etc. ;</i><br><b><i>Moy.</i></b> (<i>seul. prés. fut. et ao</i>.) fixer les yeux : πρός τινα, HÉS. <i>O. 476,</i> sur qqn ; <i>d’où</i> voir distinctement, <i>acc</i>. IL. <i>23, 458 ;</i> EUR. <i>Bacch. 596 ; etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. impf. itér. 3 sg</i>. αὐγάζεσκε, NAZ. <i>2, 164. Ao. réc</i>. ηὔγασα, ANTH. <i>7, 726 ; partic</i>. αὐγάσας, PHIL. <i>1, 608 ; etc. — Pass. part. ao. fém</i>. αὐγασθεῖσα, SOPH. (EL. <i>N.A. 11, 18). — Moy. prés. impér. 2 sg. dor</i>. αὐγάσδεο, PLUT. <i>M. 238</i> b. <i>Fut. 2 sg. poét</i>. αὐγάσεαι, HÉS. <i>c. Ao. ind. 3 sg</i>. ηὐγάσατο, ANTH. <i>6, 291 ; sbj. 3 sg. poét</i>. αὐγάσσηται, CALL. <i>Dian. 129 ; 2 pl</i>. αὐγάσσησθε, CALL. <i>Cer. 4 ; inf. poét</i>. αὐγάσσασθαι, A. RH. <i>2, 682 ; part</i>. αὐγασάμενος, PHIL. <i>1, 425</i>.<br><span><b>Étym</b>. αὐγή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυγαζω - αὐγάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G827":"<h1>auge</h1>\n<p>Strong n° 827 <i>Prononciation [owg'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>éclat, lumière du jour, le point du jour, l'aube</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐγή, ῆς (ἡ)</b> lumière éclatante, <i>part. :</i><br><b>      1</b> éclat du soleil, IL. <i>17, 371 ;</i> OD. <i>6, 98, etc. ; au plur</i>. rayons du soleil : ἠελίου ἰδεῖν αὐγάς, IL. <i>16, 188,</i> voir les rayons du soleil, <i>càd</i>. naître <i>ou</i> être né ; αὐγὰς λεύσσειν, ESCHL. <i>Pers. 710 ;</i> βλέπειν <i>ou</i> ἐσιδεῖν, EUR. <i>Andr. 935 ; Alc. 667,</i> voir les rayons du soleil <i>ou</i> la lumière du jour, <i>càd</i>. être vivant ; ὑπ' αὐγὰς ἠελίοιο φοιτᾶν, OD. <i>2, 181 ou</i> ζώειν, OD. <i>15, 349,</i> aller et venir <i>ou</i> vivre à la lumière du jour ; πρὸς <i>ou</i> ὑπ' αὐγὰς θεωρεῖν, ἰδεῖν, <i>etc</i>. HPC. <i>Off. 740 ;</i> AR. PLAT. PLUT. <i>etc</i>. examiner, voir, <i>etc</i>. à la lumière du jour, <i>càd</i>. en pleine lumière, à fond ; δυσμαὶ αὐγᾶν (<i>dor. p</i>. αὐγῶν), PD. <i>I. 3, 83,</i> le coucher du soleil ; <i>fig</i>. βίου δύντος αὐγαί, ESCHL. <i>Ag. 1123,</i> les rayons du couchant de la vie ; αὐγαὶ ἠελίοιο, DP. <i>84, 231,</i> les rayons du soleil, <i>pour</i> l’Orient ; <i>ou abs</i>. αὐγή, NT. <i>Ap. 20, 11,</i> le point du jour ;<br><b>      2</b> lueur du feu, NIC. <i>Al. 61 ; d’ord. au plur</i>. IL. <i>2, 456 ;</i> OD. <i>6, 305 ;</i> lueur d’un feu servant de signal, IL. <i>18, 211 ;</i> ESCHL. <i>Ag. 9 ;</i> des éclairs, IL. <i>13, 244 ; etc. ;</i><br><b>      3</b> éclat des yeux, <i>d’ordin. au plur</i>. SOPH. <i>Aj. 70 ; d’où abs</i>. αὐγαί, yeux (<i>cf. lat</i>. lumina), EUR. <i>Andr. 1180 ; Rhes. 737 ;</i><br><b>      4</b> éclat <i>ou</i> reflet d’un objet brillant (métal, tissu, <i>etc</i>.) IL. <i>13, 341 ;</i> PD. <i>N. 4, 83 ;</i> EUR. <i>Med. 983, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. αὐγά, PD. <i>ll. cc. ;</i> EUR. <i>Med. l. c. ;</i> THCR. <i>Idyl. 6, 38, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυγη - αὐγή</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – le terme général pour la lumière : lumière d'un feu\n<br><br> – est un terme plus concret et plus accentué : la brillante lumière du soleil, le rayon de lumière\n<br><br> – est un terme encore plus fort, suggérant la nature ardente de la lumière ; la chaleur du jour.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G828":"<h1>Augoustos</h1>\n<p>Strong n° 828 <i>Prononciation [ow'-goos-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Auguste (Angl. Augustus) = « vénérable, qui impose le respect »\n<ol>\n<li>le premier empereur Romain</li>\n<li>titre conféré aux empereurs Romains</li>\n<li>appelé César Auguste dans le N.T.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Αὔγουστος, ου (ὁ) :<br>   I</b> <i>subst. transcr. du lat</i>. Augustus :<br><b>      1</b> Auguste, <i>titre des empereurs romains, part. d’Octave,</i> PAUS. DC. ;<br><b>      2</b> <i>autre n. du mois Sextilis (août</i>), PLUT. <i>Num. 19 ;</i> DC. <i>56, 30 ;</i><br><b>   II</b> <i>adj</i>. du mois d’août : ταῖς αὐγούστοις εἰδοῖς = <i>lat</i>. Augustis idibus, PLUT. <i>M. 287</i> e.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αυγουστος - Αὔγουστος</font>\n<br><br>vient du Latin (« augustus »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G829":"<h1>authades</h1>\n<p>Strong n° 829 <i>Prononciation [ow-thad'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>suffisant, arrogant, présomptueux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐθ·άδης, ης</b>, <i>neutre</i> <b>αὔθαδες</b> <span>[ᾱδ]</span><br><b>      1</b> qui se complaît en soi, suffisant, présomptueux, <i>d’où</i> arrogant, HDT. <i>6, 92 ;</i> ESCHL. <i>Pr. 908 ;</i> HPC. TH. <i>etc. ; en parl. d’un chien hargneux,</i> XÉN. <i>Cyn. 6, 25 ;</i><br><b>      2</b> <i>p. suite,</i> dur, cruel, ESCHL. <i>Pr. 64</i>.<br><span>•<i> Cp</i>. -έστερος, HDT. <i>l. c. ;</i> THC. <i>8, 84 ;</i> EUR. <i>Hipp. 304 ;</i> EUB. (ATH. <i>260</i> c), <i>etc.</i> <i>• Sup</i>. -έστατος, POL. <i>27, 8</i>.<br><span><b>Étym</b>. <i>p</i>. *αὐτο-ϝάδης ; <i>le deuxième terme de la compos. de</i> *swad-, <i>de la</i> R. <i>de</i> ἁδεῖν, <i>cf</i>. ἁνδάνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυθαδης - αὐθάδης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Tite (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G830":"<h1>authairetos</h1>\n<p>Strong n° 830 <i>Prononciation [ow-thah'-ee-ret-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>volontairement, choix délibéré, de son plein gré, spontané</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐθ·αίρετος, ος, ον :<br>      1</b> volontairement choisi, <i>d’où</i> volontaire, spontané (exil, servitude, mort, <i>etc</i>.) THC. <i>1, 144 ; 6, 40 ;</i> XÉN. <i>Hell. 6, 2, 36 ;</i> SOPH. <i>O.R. 1231 ; etc. ;</i><br><b>      2</b> qui choisit <i>ou</i> agit de son plein gré, libre, indépendant (avis, résolution) THC. <i>1, 78 ;</i><br><b>      3</b> qui se choisit <i>ou</i> se désigne de lui-même, <i>en parl. de généraux qui s’attribuent le commandement,</i> XÉN. <i>An. 5, 7, 29</i>.<br><span><b>Étym</b>. αὐτός, αἱρέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυθ-αιρετος - αὐθαίρετος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\t\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G831":"<h1>authenteo</h1>\n<p>Strong n° 831 <i>Prononciation [ow-then-teh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui tue de ses propres mains un autre ou lui-même</li>\n<li>celui qui agit de sa propre autorité, autocrate</li>\n<li>un maître absolu</li>\n<li>gouverner, exercer une domination, dominer sur, régner sur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐθεντέω-ῶ</b> (<i>seul. prés. ao. et pf</i>.) avoir pleine autorité sur, <i>gén</i>. NT. <i>1Tim. 2, 12</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. inf</i>. -ῆσαι, BAS. <i>p. 825 ; pf. part</i>. αὐθεντηκώς, SCH.-ESCHL. <i>Eum. 42</i>.<br><span><b>Étym</b>. αὐθέντης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυθεντεω - αὐθεντέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G832":"<h1>auleo</h1>\n<p>Strong n° 832 <i>Prononciation [ow-leh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>jouer de la flûte, flûte, pipeau</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐλέω-ῶ</b> <span>(<i>f</i>. αὐλήσω, <i>ao</i>. ηὔλησα, <i>pf. inus. ; pass. seul. prés. et impf</i>. ηὐλούμην)</span><br><b>   I</b> jouer de la flûte, HDT. <i>2, 60 ;</i> XÉN. <i>Conv. 1, 10 ;</i> PLAT. <i>Prot. 327</i> a, <i>etc. ; avec un acc</i>. jouer sur la flûte : τι, HDT. <i>6, 129 ;</i> AR. <i>Vesp. 582 ;</i> PLAT. ARSTT. <i>etc</i>. qqe ch. ; <i>avec un dat. de pers</i>. αὐλ. τινι, XÉN. <i>Conv. 2, 8 ;</i> PLAT. ARSTT. jouer de la flûte pour qqn ; — <i>d’où au pass. :</i><br><b>      1</b> être joué sur la flûte, XÉN. <i>Conv. 9, 3 ;</i><br><b>      2</b> retentir du son de la flûte, EUR. <i>I.T. 367 ;</i><br><b>   II</b> <i>p. ext</i>. souffler comme dans une flûte : αὐλεῖν κέρασι, XÉN. donner un signal en sonnant de la corne ; <i>en gén</i>. αὐλεῖν κέρατι, LUC. <i>D. deor. 12, 1,</i> sonner de la corne ;<br><b><i>Moy.</i></b> se faire jouer de la flûte, XÉN. <i>Cyr. 4, 5, 7 ;</i> AN. <i>6, 1, 11</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. 3 sg. dor. sans augm</i>. αὔλει, THCR. <i>Idyl. 6, 43. Fut. 3 pl. dor</i>. αὐλησεῦντι, THCR. <i>Idyl. 7, 71. Ao. 3 sg. dor. sans augm</i>. αὔλησε, ALCM. <i>82</i>.<br><span><b>Étym</b>. αὐλός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυλεω - αὐλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G833":"<h1>aule</h1>\n<p>Strong n° 833 <i>Prononciation [ow-lay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>chez les Grecs, du temps d'Homère, un espace découvert autour de la maison, fermé par un mur, tandis que chez les Orientaux il s'agissait d'un espace dans la campagne, entouré d'un mur, où les troupeaux passaient la nuit, une bergerie</li>\n<li>la partie non couverte d'une maison. Dans l'Ancien Testament, il s'agit particulièrement du « parvis » du tabernacle et du temple à Jérusalem. Les demeures des gens de la haute société possédaient généralement deux de ces « cours » : une entre la porte et la rue, l'autre entourée par l'immeuble lui-même. C'est ce qui est mentionné en <a class=\"ref\" data-r=\"MAT26.69\">Matthieu 26.69</a></li>\n<li>la maison elle-même, un palais</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐλή, ῆς (ἡ) :<br>   I</b> tout espace à l’air libre, ATH. <i>189</i> b ;<br><b>   II</b> cour d’une maison, <i>part. dans Homère,</i> cour devant la maison, <i>avec des constructions alentour pour les services de l’habitation, les écuries ou étables et les logements des serviteurs ; au milieu, l’autel de Zeus</i> ἑρκεῖος ; <i>cette cour avait deux portes, celle de la maison</i> (<i>v</i>. αὔλειος) <i>et celle qui conduisait par l’</i>αἴθουσα <i>dans le</i> πρόδομος. <i>Après Homère,</i> cour carrée, <i>entourée par les bâtiments, avec un corridor circulaire, sur lequel s’ouvraient les portes conduisant aux appartements des hommes ; en face de la porte de la maison était la</i> μέσαυλος <i>ou</i> μέταυλος <i>conduisant aux appartements des femmes ; — p. ext. dans Hom</i>. mur d’enceinte de la cour, IL. <i>5, 138 ;</i> OD. <i>9, 184 ; 14, 5 ;</i><br><b>   III</b> <i>p. ext. :</i><br><b>      1</b> résidence, demeure : Ζηνὸς αὐλή, OD. <i>4, 74 ;</i> Διὸς αὐ. ESCHL. <i>Pr. 122,</i> demeure de Zeus ; αὐλὴ νεκύων, EUR. <i>Alc. 259,</i> demeure des morts ; <i>en parl. d’un temple,</i> EUR. <i>I.T. 128 ; etc. ; en gén</i>. ἐν αὐλαῖς, SOPH. <i>Tr. 901,</i> dans la maison ; <i>en parl. d’animaux sauvages,</i> repaire, SOPH. <i>Ant. 785 ; postér</i>. demeure d’un prince, palais, <i>d’où</i> cour d’un souverain, POL. <i>5, 26 ;</i> οἱ περὶ τὴν αὐλήν, POL. <i>5, 36,</i> les courtisans ;<br><b>      2</b> <i>part</i>. maison des champs, DH. <i>6, 50</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. αὐλά, PD. <i>N. 4, 24, etc. ;</i> EUR. <i>Hipp. 68, etc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₂eus-leh₂-, <i>de la</i> R. *h₂eus-, gîter, <i>cf</i>. ἰαύω, ἄεσα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυλη - αὐλή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (3)</li>\n<li>Luc (2)</li>\n<li>Jean (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G834":"<h1>auletes</h1>\n<p>Strong n° 834 <i>Prononciation [ow-lay-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ménestrel, un joueur de flûte</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐλητής, οῦ (ὁ)</b> <i>c</i>. αὐλητήρ THGN. <i>941 ;</i> HDT. <i>1, 141, etc. ;</i> AR. <i>Vesp. 581, etc</i>.<br>\n<b>αὐλητήρ, </b><b>ῆρος (ὁ)</b> joueur de flûte, HÉS. <i>Sc. 283, 299 ;</i> THGN. <i>825 ;</i> AR. <i>fr. 478</i>.<br><span><b>Étym</b>. αὐλέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυλητης - αὐλητής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G835":"<h1>aulizomai</h1>\n<p>Strong n° 835 <i>Prononciation [ow-lid'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>loger dans un enclos, spécialement la nuit\n<ol type=\"a\">\n<li>troupeaux et bergers</li>\n</ol>\n</li>\n<li>passer la nuit en plein air</li>\n<li>passer la nuit, loger</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐλίζομαι</b> <span>(<i>impf</i>. ηὐλιζόμην, <i>f. inus., ao</i>. ηὐλισάμην <i>et</i> ηὐλίσθην, <i>pf</i>. ηὔλισμαι)</span><br><b>      1</b> vivre en plein air, <i>en parl. de bestiaux parqués (bœufs,</i> OD. <i>12, 265 ; porcs,</i> OD. <i>14, 412) ; d’où</i> camper en plein air, <i>en parl. de troupes bivouaquant pendant le jour,</i> HDT. <i>8, 9 ; 9, 37 ;</i> XÉN. <i>Cyr. 4, 6, 6 ; surt. pendant la nuit,</i> THC. <i>4, 45 ; 6, 7, etc. ;</i> POL. <i>10, 15 ; 18, 10 ; d’où, même en parl. d’une pers. seule,</i> passer la nuit en plein air, EUP. <i>322 Kock ; 463, 18 Bekker, Anecdota græca, vol. 1 ;</i><br><b>      2</b> <i>p. ext</i>. séjourner en plein air, <i>en parl. d’animaux <i>ou</i> d’oiseaux,</i> HDT. <i>3, 110 ;</i> ARSTT. <i>H.A. 9, 32 ;</i> A. RH. <i>3, 325 ;</i><br><b>      3</b> <i>p. suite,</i> se fixer qqe part, <i>en parl. du sang,</i> ARÉT. <i>13, 35</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. ion</i>. αὐλιζόμην, LUC. <i>Syr. 22. Fut. réc</i>. αὐλισθήσομαι, SPT. <i>Job 29, 19, etc. ;</i> SIB. <i>3, 789. Ao. dans</i> THC. <i>touj</i>. ηὐλισάμην, <i>4, 13 ; 6, 65 et 71, etc. ; dans</i> XÉN. <i>touj</i>. ηὐλίσθην, XÉN. <i>An. 3, 2, 5 ; 4, 1, 11, etc. Pf. réc</i>. ηὔλισμαι, ARR. <i>An. 3, 29,</i> JOS. <i>B.J. 1, 17, 5</i>.<br><span><b>Étym</b>. αὐλή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυλιζομαι - αὐλίζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G836":"<h1>aulos</h1>\n<p>Strong n° 836 <i>Prononciation [ow-los']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une flûte, un pipeau</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐλός, οῦ (ὁ) :<br>   I</b> tout instrument à vent, <i>part</i>. flûte, <i>primitiv. faite d’un roseau, postér. de bois, d’ivoire, de métal, etc. avec une languette</i> (<i>v</i>. γλωσσίς) <i>et analogue à notre hautbois ou clarinette,</i> IL. <i>10, 13 ; 18, 495 ;</i> HH. <i>Merc. 452 ;</i> PD. ATT. ; ὑπ' αὐλοῦ, HDT. <i>1, 17 ;</i> πρὸς αὐλόν, XÉN. <i>An. 6, 1, 5 ;</i> πρὸς τὸν αὐλόν, XÉN. <i>Conv. 3, 1 ; 6, 4 ;</i> ὑπὸ τὸν αὐλόν, XÉN. <i>Conv. 6, 3 ;</i> PLUT. <i>M. 41</i> c, au son de la flûte ; <i>plur</i>. δίδυμοι αὐλοί, double flûte, THCR. <i>Epigr. 5 ; p. ext</i>. αὐλὸς Ἐνυαλίου ANTH. <i>6, 151,</i> flûte d’Enyalios, <i>càd</i>. trompette ;<br><b>   II</b> <i>p. anal</i>. tout tuyau <i>ou</i> conduit creux et allongé, <i>part. :</i><br><b>      1</b> tube : <i>tube où l’on fixe le plumet d’un casque,</i> IL. <i>17, 297 ; tube d’un soufflet de forge,</i> HPC. <i>814</i> d ; <i>837</i> b ; <i>tube d’une clepsydre,</i> ARSTT. <i>Probl. 16, 8, 7, etc. ; p. anal. t. d’anat</i>. vaisseau reliant le cœur et l’aorte, ARSTT. <i>Respir. 16, 4, etc. ;</i> ouverture par laquelle les cétacés rejettent l’eau de mer, ARSTT. <i>H.A. 4, 10, 11 ;</i><br><b>      2</b> <i>au plur</i>. bandes allongées, au haut d’un manteau, et portant l’une le crochet d’une agrafe, l’autre la boucle où s’engage le crochet, OD. <i>19, 227 ;</i><br><b>      3</b> jet de sang, OD. <i>22, 18 ;</i><br><b>      4</b> espace allongé, <i>part</i>. le stade, LYC. <i>40 (cf</i>. δίαυλος) ;<br><b>   III</b> <i>c</i>. αὐλών, DH. <i>3, 43 ;</i><br><b>   IV</b> <i>sorte de poisson</i> (<i>v</i>. σωλήν).<br><span><b><span class=\"arrow\"></span></b> <i>Acc. pl. dor</i>. αὐλώς, THCR. <i>Idyl. 10, 34</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₂eu-l-, tube ; <i>cf</i>. ἔναυλος, <i>lat</i>. alvus <i>avec métath</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυλος - αὐλός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G837":"<h1>auxano</h1>\n<p>Strong n° 837 <i>Prononciation [owx-an'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>croître, augmenter</li>\n<li>s'accroître, devenir plus grand</li>\n<li>pousser, s'élever\n<ol type=\"a\">\n<li>de plantes</li>\n<li>d'enfants</li>\n<li>d'une foule</li>\n<li>de l'accroissement intérieur du Chrétien</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐξάνω</b> <span>(<i>impf</i>. ηὔξανον, <i>f</i>. αὐξήσω, <i>ao</i>. ηὔξησα, <i>pf</i>. ηὔξηκα ; <i>pass. impf</i>. ηὐξανόμην, <i>f</i>. αὐξηθήσομαι, <i>ao</i>. ηὐξήθην, <i>pf</i>. ηὔξημαι)</span><br><b>   I <i>tr</i>.<br>      1</b> augmenter, accroître (en taille, en force, en puissance, <i>etc.) d’où, au pass</i>. croître, grandir, <i>en parl. d’un enfant,</i> HDT. <i>5, 92 ; en parl. de taille,</i> HDT. <i>2, 14 ; de nombre,</i> HDT. <i>1, 58 ; de puissance,</i> HÉS. <i>Th. 493 ;</i> PD. HDT. <i>etc. ; de même, en parl. des forces de la nature</i> (vent, <i>etc</i>.) HDT. <i>7, 188, etc. ; avec un adj</i>. αὐξάνεσθαι μέγαν, EUR. <i>Bacch. 183 ;</i> PLAT. <i>etc</i>. devenir grand ; ἐλλόγιμος ηὐξήθη, PLAT. <i>Prot. 327</i> c, il grandit en honneur et en renom ;<br><b>      2</b> ajouter l’augment à un verbe ; <i>d’où, au pass.,</i> prendre l’augment, EM. <i>399, 47 ;</i><br><b>   II</b> <i>intr. depuis Aristote,</i> s’augmenter, croître, grandir, <i>en parl. d’enfants,</i> LUC. <i>Sol. 4 ; de plantes,</i> ARSTT. <i>Plant. 1, 1 et 4 ; etc. ; fig</i>. POL. <i>16, 21 ; etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. réc</i>. αὐξανῶ, SPT. <i>Gen. 17, 6 et 20 ; 48, 4 ; Lev. 26, 9. Impf. pass. ion</i>. αὐξανόμην, HDT. <i>5, 92. Fut. moy. au sens pass</i>. αὐξήσομαι, XÉN. <i>Cyr. 6, 1, 12 ;</i> PLAT. <i>Rsp. 497</i> a. — <i>Pour l’emploi de</i> αὐξάνω <i>et de</i> αὔξω, <i>v</i>. αὔξω <i>fin</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₂uegs-, croître ; <i>cf. lat</i>. augeō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυξανω - αὐξάνω</font>\n<br><br>forme d'un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n22 fois dans 22 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Jean (1)</li>\n<li>Actes (4)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (2)</li>\n<li>Ephésiens (2)</li>\n<li>Colossiens (2)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G838":"<h1>auxesis</h1>\n<p>Strong n° 838 <i>Prononciation [owx'-ay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>augmentation, croissance, accroissement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὔξησις, εως (ἡ) :<br>      1</b> croissance, accroissement, HPC. <i>238, 13, etc. ;</i> THC. <i>1, 69 ;</i> XÉN. PLAT. <i>etc. ; au plur</i>. PLAT. <i>Rsp. 546</i> b ;<br><b>      2</b> <i>t. de rhét</i>. amplification, ARSTT. <i>Rhet. 3, 12, 4 ; cf</i>. POL. <i>10, 24 ;</i> DH. <i>Thuc. 19, 2 ;</i><br><b>      3</b> <i>t. de gr</i>. augment, EM. <i>338, 48 ;</i> DRAC. <i>155, 16</i>.<br><span><b>Étym</b>. αὐξάνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυξησις - αὔξησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G839":"<h1>aurion</h1>\n<p>Strong n° 839 <i>Prononciation [ow'-ree-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>demain, lendemain, le jour suivant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὔριον</b>, <i>adv</i>., demain, IL. <i>9, 357 ;</i> OD. <i>1, 272 ; etc</i>. ATT. ; αὔ. τηνικάδε, PLAT. <i>Phæd. 76</i> b, demain à ce moment ; ἐς αὔριον, IL. <i>8, 538 (ou</i> αὔριον ἐς, OD. <i>7, 318</i>), vers le matin, <i>ou</i> jusqu’au matin, OD. <i>11, 351 ;</i> ἡ αὔριον ἡμέρα, XÉN. <i>Œc. 11, 6 ;</i> LYS. <i>175, 35, ou subst</i>. ἡ αὔριον (<i>s.-e</i>. ἡμέρα), SOPH. <i>Tr. 945 ;</i> EUR. <i>Alc. 784,</i> le lendemain ; εἰς τὴν αὔριον, PLAT. <i>Menex. 234</i> b ; POL. <i>1, 60,</i> pour le lendemain <i>ou</i> jusqu’au lendemain ; ἐν τῇ αὔριον, SPT. <i>Ex. 8, 23,</i> le lendemain ; <i>subst</i>. τὸ αὔριον, THCR. <i>Idyl. 13, 4,</i> le lendemain.<br><span><b>Étym</b>. <i>du locat</i>. *αυσρι, <i>d’où</i> *αὖρι, tôt le matin, <i>de la R. indo-europ</i>. *h₂eus-r-, aube ; <i>cf</i>. ἄγχαυρος, ἀήρ, ἕως.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυριον - αὔριον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 13 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (4)</li>\n<li>Actes (4)</li>\n<li>1 Corinthiens (1)</li>\n<li>Jacques (2)</li>\n</ul>\n</td></tr>\n</table>","G840":"<h1>austeros</h1>\n<p>Strong n° 840 <i>Prononciation [ow-stay-ros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>de l'esprit et des manières : rude, sévère, austère, rigoureux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐστηρός, ά, όν :<br>      1</b> sec, rude, âcre, <i>en parl. d’un liquide</i> (eau, vin, <i>etc</i>.) ; HPC. <i>360, 3, etc. ;</i> PLAT. <i>Phil. 61</i> c, <i>etc. ; en parl. d’une odeur,</i> ARSTT. <i>An. 2, 9, 5 ;</i><br><b>      2</b> <i>fig</i>. rigide, sévère, austère, PLAT. <i>Rsp. 398</i> a ; POL. <i>9, 12 ; etc</i>.<br><span>•<i> Cp</i>. -ότερος, HPC. <i>404, 6 ;</i> PLAT. <i>Rsp. 398</i> a ; DS. <i>3, 34</i>. <i>• Sup</i>. -ότατος, POL. <i>4, 20, 7</i>.<br><span><b>Étym</b>. αὖος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυστηρος - αὐστηρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G841":"<h1>autarkeia</h1>\n<p>Strong n° 841 <i>Prononciation [ow-tar'-ki-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>parfaite condition de vie, sans besoin d'aide ou de support</li>\n<li>suffisance en ce qui concerne les nécessités de la vie</li>\n<li>esprit content de son sort, contentement, modération des désirs</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐτάρκεια, ας (ἡ)</b> qualité de ce qui se suffit à soi-même <i>ou</i> état de celui qui se suffit à lui-même <i>ou</i> fait qqe ch. par lui-même, PLAT. <i>Phil. 67</i> a ; ARSTT. <i>Nic. 1, 7, 5, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. αὐταρκίη, ARÉT. <i>73, 61</i>.<br><span><b>Étym</b>. αὐτάρκης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυταρκεια - αὐτάρκεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G842":"<h1>autarkes</h1>\n<p>Strong n° 842 <i>Prononciation [ow-tar'-kace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avoir suffisamment pour soi-même, sans besoin d'aide ou de support</li>\n<li>indépendant des circonstances extérieures</li>\n<li>content de son sort, de ses moyens, même s'ils sont minces</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐτ·άρκης, ης</b>, <i>neutre</i> <b>αὔταρκες</b>, qui se suffit à soi-même, <i>càd. :</i><br><b>      1</b> qui existe <i>ou</i> subsiste par soi-même, HDT. <i>1, 32 ;</i> ATT. ; <i>p. opp. à</i> πολλῶν ἐνδεής, PLAT. <i>Rsp. 369</i> b ; χώρα <i>ou</i> πόλις αὐτ. THC. <i>1, 37 ; 2, 36 ;</i> ARSTT. <i>Pol. 1, 2, 8,</i> région <i>ou</i> ville qui se suffit à elle-même, qui n’a pas besoin d’importations ; αὐτ. εἴς τι, PLAT. <i>Pol. 271</i> d ; πρός τι, THC. <i>2, 51 ;</i> XÉN. <i>Mem. 4, 8, 11 ;</i> PLAT. <i>etc</i>. qui suffit par lui-même pour qqe ch. ; <i>avec l’inf</i>. XÉN. <i>Cyr. 4, 3, 4 ;</i> DÉM. <i>32, 12, etc</i>. suffisant par soi-même pour ;<br><b>      2</b> qui se contente de ce qu’il possède, ARSTT. <i>Pol. 1, 8 ;</i> DH. <i>5, 48 ;</i> ANTH. <i>6, 302, etc. ;</i><br><b>      3</b> adapté, proportionné, correspondant à, HÉRON ;<br><b>      4</b> <i>t. de balist</i>. qui se fait de soi-même à point : αὐτ. καταγωγή, HÉRON, refoulement à bout de course <i>ou</i> à point, <i>dans les machines de jet</i>.<br><span>•<i> Sup</i>. -έστατος, HPC. <i>351, 4 ;</i> THC. <i>2, 36 ;</i> STR. <i>127 ;</i> CLÉM. <i>Pæd. 314, 11</i>.<br><span><b>Étym</b>. αὐτός, ἀρκέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυταρκης - αὐτάρκης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G843":"<h1>autokatakritos</h1>\n<p>Strong n° 843 <i>Prononciation [ow-tok-at-ak'-ree-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>se condamner soi-même</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐτο·κατάκριτος, ος, ον</b> <span>[ῐ]</span> qui se condamne soi-même, NT. <i>Tit. 3, 11</i>.<br><span><b>Étym</b>. αὐ. κατακρίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυτο-κατακριτος - αὐτοκατάκριτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G844":"<h1>automatos</h1>\n<p>Strong n° 844 <i>Prononciation [ow-tom'-at-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>agir de soi-même, sous sa propre impulsion sans l'intervention de quiconque</li>\n<li>souvent utilisé pour la terre produisant des plantes par elle-même et des fruits poussant sans être cultivés</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐτό·ματος, η, ον</b> <span>[ᾰ]</span><br><b>      1</b> qui se meut de soi-même : πύλαι αὐτόμαται, IL. <i>5, 749,</i> portes (de l’Olympe) qui s’ouvrent d’elles-mêmes : αὐτόματοι τρίποδες, IL. <i>18, 376,</i> trépieds (d’Héphæstos) qui s’agitent d’eux-mêmes ; τὸ αὐτόματον, HÉRON <i>Aut. 263, etc</i>. automate ;<br><b>      2</b> <i>p. suite,</i> qui va, vient <i>ou</i> agit de son propre mouvement, IL. <i>2, 408 ;</i> HÉS. <i>O. 103 ;</i> THC. <i>6, 91 ; etc. ; en parl. d’un fleuve,</i> HDT. <i>2, 14 ; de plantes qui poussent d’elles-mêmes sans culture,</i> HDT. <i>2, 94 ; 3, 100 ; 8, 138, etc. ; en gén. en parl. d’événements qui se produisent d’eux-mêmes,</i> θάνατος αὐτ. DÉM. <i>296, 18,</i> mort naturelle : αἰτία αὐτόματη, PLAT. <i>Soph. 265</i> c, cause spontanée <i>ou</i> naturelle ; <i>subst</i>. τὸ αὐτόματον, <i>att</i>. ταὐτόματον, LYS. <i>105, 27 ;</i> ARSTT. <i>Phys. 2, 4, 1,</i> le hasard ; <i>p. opp. à</i> τέχνη, ARSTT. <i>Metaph. 11, 3, 2 ;</i> ἀπὸ τοῦ αὐτομάτου, <i>att</i>. ἀπὸ ταὐτομάτου, THC. <i>2, 77, 6, 36 ;</i> ἀπ' αὐτομάτου, XÉN. <i>Mem. 4, 2, 4 ; etc. ;</i> ἐκ τοῦ αὐτομάτου, <i>par crase</i> ἐκ ταὐτομάτου, POL. <i>9, 9, 3 ;</i> PLUT. <i>M. 420</i> b, <i>etc. ;</i> ἐξ αὐτομάτου, RHÉT. <i>1, 583, 16 W</i>. par l’effet du hasard, au hasard.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. αὐτόματος, HÉS. <i>O. 103 ;</i> ARSTT. <i>G.A. 3, 11, 14 ; H.A. 10, 6, 43</i>.<br><span><b>Étym</b>. αὐτός, <i>R. indo-europ</i>. *mn-to-, pensée ; <i>cf</i>. μέμονα, μέμαμεν, μένος, <i>lat</i>. commentus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυτοματος - αὐτόματος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G845":"<h1>autoptes</h1>\n<p>Strong n° 845 <i>Prononciation [ow-top'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>voir de ses propres yeux, un témoin oculaire\n<ol type=\"a\">\n<li>terme médical : autopsie, un examen détaillé</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐτ·όπτης, ου (ὁ)</b> qui voit de ses propres yeux, témoin oculaire, HDT. <i>2, 29, etc. ;</i> PLAT. <i>Leg. 900</i> a ; XÉN. <i>Cyr. 5, 4, 18, etc. ; avec le gén</i>. DÉM. <i>600, 11 ;</i> DIN. <i>110, 10 ;</i> ARSTT. <i>H.A. 9, 37</i>.<br><span><b>Étym</b>. αὐ. ὄψομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυτ-οπτης - αὐτόπτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G846":"<h1>autos</h1>\n<p>Strong n° 846 <i>Prononciation [ow-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>lui-même, elle-même, eux-mêmes</li>\n<li>il, elle</li>\n<li>le même</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐτός, ή, ό</b>, <i>gén</i>. <b>αὐτοῦ, ῆς, οῦ</b>, <i>etc. ; litt</i>. « d’autre part celui-ci » <i>p. opp. à un autre ; p. suite,</i> moi-même, toi-même, lui-même <i>(p. opp. à un autre) (v. la fin de l’article) ; d’où :</i><br><b>   I</b> même (<i>lat</i>. ipse) ; <i>en ce sens :</i><br><b>      1</b> <i>joint à un pronom personnel :</i> ἐγὼ αὐτός, IL. <i>1, 137 ou</i> αὐτὸς ἐγώ, OD. <i>24, 321,</i> moi-même ; ἐμεῦ αὐτῆς, OD. <i>19, 93,</i> de moi-même ; ἐμοὶ αὐτῷ, IL. <i>13, 73,</i> à moi-même ; <i>et avec les formes enclit. du pron. :</i> μοὶ αὐτῷ <i>ou</i> αὐτῇ, OD. <i>5, 179, 199,</i> à moi-même ; μ' αὐτόν, μ' αὐτήν, IL. <i>10, 242 ; 15, 723 ; 22, 82, etc. ;</i> μὶν αὐτόν, IL. <i>21, 245, etc. ;</i> μὶν αὐτήν, IL. <i>24, 729,</i> lui-même, elle-même ; <i>ou avec</i> αὐτός <i>avant l’enclit</i>. αὐτῷ μοι, τοι, IL. <i>5, 459 ;</i> OD. <i>22, 345, etc</i>. à moi-même, à toi-même ; αὐτόν μιν, OD. <i>4, 244,</i> lui-même ; <i>chez les Att. αὐτός se joint également à un pron. personn., mais touj. en un sens pléonastique ou emphatique, non réfléchi ; qqf. avec le pronom placé devant</i> αὐτός : σὺ αὐτός, PLAT. <i>Conv. 172</i> b ; σὲ αὐτόν, PLAT. <i>Gorg. 172</i> b, toi-même, toi en personne ; <i>mais d’ord</i>. αὐτός <i>précède le pronom :</i> αὐτῷ ἐμοί, PLAT. <i>Phæd. 91</i> a ; αὐτὸν ἐμέ, PLAT. <i>Euthyd. 273</i> b ; <i>ou avec le pron. enclit</i>. αὐτῷ μοι, PLAT. <i>Phæd. 60</i> c ; αὐτόν με, PLAT. <i>Conv. 198</i> c, à moi-même, moi-même ; <i>cf</i>. PLAT. <i>Crat. 384</i> a, <i>Rsp. 378</i> b, <i>etc. ;</i> XÉN. DÉM. <i>etc. Aux cas obliques αὐτός s’unit par crase au thème du pronom :</i> ἐμαυτοῦ, σεαυτοῦ, ἑαυτοῦ (<i>v. ces mots) ; il reste toujours distinct au plur</i>. ἡμεῖς αὐτοί, PLAT. <i>Menex. 243</i> d ; ἡμῖν αὐτοῖς, XÉN. <i>Cyr. 4, 5, 15 ;</i> ἡμᾶς αὐτούς, PLAT. <i>Leg. 923</i> a, <i>etc</i>. nous-mêmes, à nous-mêmes, nous-mêmes. <i>Le pron. pers. est qqf. s. entendu :</i> γιγνώσκεις δὲ καὶ αὐτός, XÉN. <i>Cyr. 1, 6, 2,</i> et tu le sais toi-même ; αὐτὸν ἐλέησον (<i>p</i>. ἐμὲ αὐτόν) IL. <i>24, 503,</i> aie pitié de moi ; αὐτῶν γὰρ ἀπωλόμεθ' ἀφραδίῃσιν (<i>p</i>. ἡμῶν αὐτῶν) OD. <i>10, 27,</i> car nous fûmes perdus par nos propres folies (<i>sel. d’autres,</i> par leurs folies, <i>cf</i>. OD. <i>1, 7</i>) ;<br><b>      2</b> <i>joint à un nom :</i> οὔτ' αὐτῆς Ἑκάϐης, IL. <i>6, 451,</i> pas même d’Hécube ; ὑπὸ λόφον αὐτόν, IL. <i>13, 615,</i> sous l’aigrette même, <i>càd</i>. justement sous l’aigrette ; <i>en prose att</i>. αὐτός <i>se construit avec le nom précédé de l’article, soit devant l’art. et le nom :</i> αὐτὸς ὁ βασιλεύς, le roi même ; <i>soit après l’art. et le nom :</i> ὁ βασιλεὺς αὐτός, <i>m. sign. ; qqf. cependant l’article est omis devant un nom propre ou un nom désignant une certaine personne :</i> αὐτὸς Μένων, XÉN. <i>An. 1, 2, 20,</i> Ménon lui-même ; <i>au dat. il se construit sans art. avec</i> σύν <i>pour marquer une idée d’union :</i> αὐτῇ σὺν φόρμιγγι, IL. <i>9, 194,</i> avec la lyre ; <i>cf</i>. IL. <i>12, 112 ; 15, 498 ;</i> OD. <i>13, 118 ; qqf. sans</i> σύν : δύω ἵππους αὐτοῖσιν ὄχεσφιν, IL. <i>8, 290,</i> deux chevaux avec les chars ; <i>cf</i>. IL. <i>11, 699 ; 23, 8, etc. ; avec la même construction en prose ion. :</i> αὐτοῖς ἀνδράσι, HDT. <i>6, 93,</i> avec les hommes, <i>càd</i>. les hommes avec le reste ; <i>chez les Att. d’ord. avec l’article devant le nom :</i> αὐτοῖς τοῖς ἵπποις, XÉN. <i>Cyr. 1, 4, 7,</i> avec les chevaux, les chevaux avec le reste ; <i>qqf. cependant les Att. expriment</i> σύν : σὺν αὐτῷ τῷ θώρακι, XÉN. <i>Cyr. 2, 2, 2,</i> avec la cuirasse elle-même ; <i>cf</i>. EUR. <i>Hipp. 1213, etc. ;</i><br><b>      3</b> <i>avec un pronom démonstratif :</i> αὐτὰ τάδε, THC. <i>1, 139,</i> ces choses mêmes ; αὐτὸ τοῦτο μόνον, PLAT. <i>Gorg. 600</i> b, cette chose même seule ; αὐτὸ τοῦτο τὸ ζητηθέν, PLAT. <i>Pol. 267</i> c, cet objet même de la recherche ; οὗτος αὐτός, PLAT. <i>Prot. 323</i> b, celui-là même ; <i>part. dans les loc. :</i> κατ' αὐτὸ τοῦτο, PLAT. <i>Prot. 337</i> d ; κατ' αὐτό γε τοῦτο, PLAT. <i>Phædr. 243</i> b, pour cela même ; <i>abs</i>. αὐτὸ τοῦτο, XÉN. <i>An. 1, 9, 12,</i> pour ce motif même ; αὐτὸ τοῦτό ἐστι χαλεπὸν ἀμαθία τὸ δοκεῖν, PLAT. <i>Conv. 204</i> a, l’ignorance est pénible pour cette raison même qu’elle semble, <i>etc. (càd</i>. ὅτι δοκεῖ) ; αὐτός <i>peut même avoir la même valeur que</i> οὗτος αὐτός : ἀδικεῖν αὐτὸ καλοῦσιν, PLAT. <i>Gorg. 483</i> c, c’est cela même qu’ils appellent être injuste ; αὐτὸ ἄν, ἔφη, τὸ δέον εἴη, XÉN. <i>An. 4, 7, 7,</i> voilà précisément, dit-il, ce qu’il faudrait ; αὐτὸ οὐκ εἴρηται ὃ μάλιστα ἔδει ῥηθῆναι, PLAT. <i>Rsp. 362</i> d, justement ce qu’il aurait fallu dire avant tout n’a pas été dit ;<br><b>      4</b> <i>avec un pronom possessif :</i> πατρὸς κλέος ἠδ' ἐμὸν αὐτοῦ, IL. <i>6, 446,</i> la gloire de mon père et la mienne propre ; αὐτῶν σφετέρῃσιν ἀτασθαλίῃσιν, OD. <i>1, 7,</i> par leurs propres folies ; τοῖς ἡμετέροις αὐτῶν φίλοις, XÉN. <i>An. 7, 1, 29,</i> à nos propres amis ; τὰ ὑμέτερα αὐτῶν χρήματα, PLAT. <i>Leg. 923</i> a, vos propres biens ;<br><b>      5</b> <i>avec un pronom réfléchi :</i> αὐτὸς καθ' αὑτοῦ, ESCHL. <i>Sept. 406,</i> lui-même contre lui-même ; αὐτοὶ ὑφ' αὑτῶν, ESCHL. <i>Sept. 194,</i> eux-mêmes par eux-mêmes ; <i>qqf. entre l’article et le pronom :</i> τοῖς αὐτὸς αὑτοῦ πήμασιν βαρύνεται, ESCHL. <i>Ag. 836,</i> il est accablé du poids de ses propres douleurs ; τούς γ' αὐτὸς αὑτοῦ πολεμίους, SOPH. <i>Aj. 1432,</i> mes propres ennemis ; τὴν αὐτὸς αὑτοῦ (μητέρα) ἀποκτεῖναι, PLAT. <i>2 Alc. 144</i> c, tuer sa propre mère ; <i>dans cette construction, en relation avec un compar. ou un superl</i>. αὐτὸς ἑωυτοῦ ῥέει πολλῷ ὑποδεέστερος, HDT. <i>2, 25,</i> il coule très inférieur à lui-même, <i>càd</i>. fort amoindri ; ἀνδρειότερος γίγνεται αὐτὸς αὑτοῦ, PLAT. <i>Rsp. 411</i> c, il en arrive à se surpasser lui-même en courage ;<br><b>      6</b> <i>avec un n. de nombre ordinal :</i> πέμπτος αὐτός, THC. <i>1, 46,</i> lui cinquième, <i>càd</i>. lui et quatre autres, αὐτός <i>désignant toujours la personne principale ;</i> δέκατος αὐτός, XÉN. <i>Hell. 2, 2, 11,</i> lui dixième, <i>càd</i>. lui et neuf autres ;<br><b>      7</b> <i>abs. en parl. de la 3<sup>e</sup> pers</i>. lui-même, <i>p. opp. à d’autres, en parl. d’un roi, p. opp. à ses sujets,</i> IL. <i>6, 18 ; 8, 4 ; de parents, p. opp. à leurs enfants,</i> IL. <i>2, 317 ; 3, 301 ;</i> HH. <i>Cer. 2 ; d’un guerrier sur son char, p. opp. à ses chevaux,</i> IL. <i>2, 466 ; des chevaux, p. opp. au char,</i> IL. <i>6, 40 ; de marins, p. opp. à leurs navires,</i> OD. <i>7, 338 ; d’un berger, p. opp. à son troupeau,</i> OD. <i>9, 167, etc. ; du corps, p. opp. à l’âme,</i> IL. <i>1, 4, ou de l’âme, p. opp. au corps,</i> OD. <i>11, 602 ; l’opposition est souvent marquée par</i> τε… καί : αὐτός τε… καί, XÉN. <i>Cyr. 1, 3, 4, etc</i>. lui-même… et, <i>en parl. d’un personnage, p. opp. à sa suite ;</i> αὐτός τε καὶ οἱ συμπόται τε καὶ ἑταῖροι, PLAT. <i>Rsp. 568</i> e, lui-même ainsi que ses convives et ses compagnons ; <i>ou par deux ou plusieurs</i> καί : καὶ αὐτὸν καὶ τὸν οἰκέτην, XÉN. <i>Ath. 1, 19,</i> et lui et son serviteur ; καὶ αὐτοὺς καὶ ὅπλα καὶ ἵππους καὶ τροχούς, XÉN. <i>Cyr. 7, 1, 16,</i> eux, leurs armes, leurs chevaux, leurs chariots ; <i>ou par un seul</i> καί : αὐτοὺς καὶ τὰ τέκνα, XÉN. <i>Cyn. 5, 24,</i> eux et leurs petits, <i>en parl. de lièvres ; en ce sens αὐτός employé absol. est l’équivalent de</i> μόνος : αὐτός περ ἐών, IL. <i>8, 99,</i> bien qu’étant seul ; αὐτοὶ κινδυνεύσομεν αὐτῷ βοηθεῖν, PLAT. <i>Theæt. 164</i> e, il y aura des chances pour que nous soyons seuls à le secourir ; αὐτοὶ ἄνευ τούτων, XÉN. <i>Cyr. 4, 3, 3,</i> seuls, sans le secours de ceux-ci ; <i>qqf. renforcé par</i> οἶος <i>ou</i> μόνος : αὐτὸς κτήσατο οἶος, OD. <i>14, 450,</i> il l’a acquis par lui-même, seul ; αὐτὸς μόνος <i>ou</i> μόνος αὐτός, PLAT. <i>Phædr. 267</i> b, <i>etc</i>. par lui-même, à lui seul ; αὐτὸ τοῦτο μόνον, PLAT. <i>Gorg. 500</i> b, <i>ou</i> τοῦτο αὐτὸ μόνον, PLAT. <i>Leg. 667</i> b ; αὐτὸ ἐκεῖνο μόνον, PLAT. <i>Theæt. 202</i> a, cela seul en soi ; <i>ou par</i> καθ' αὑτόν (<i>v</i>. ἑαυτοῦ), <i>part. dans les loc</i>. αὐτὸς καθ' αὑτόν, XÉN. <i>Mem. 3, 5, 4 ;</i> PLAT. <i>etc</i>. lui par lui-même, lui seul ; αὐτὸ καθ' αὑτό, PLAT. <i>Theæt. 201</i> e, cette chose en soi ; <i>de même avec</i> ἕκαστος : ἡμῶν ἕκαστον αὐτόν, PLAT. <i>Leg. 644</i> c, chacun de nous en particulier ; <i>cf</i>. PLAT. <i>Soph. 266</i> b, <i>Leg. 795</i> e ; <i>en ce sens</i> αὐτός <i>s’emploie souv. seul pour marquer l’idée abstraite</i> « en soi » : τὸ δίκαιον αὐτό, PLAT. <i>Phæd. 65</i> d, le juste en soi ; αὐτὸ τὸ ἕν, PLAT. <i>Parm. 143</i> a, l’unité en soi ; αὐτὴ κίνησις, PLAT. <i>Soph. 256</i> b, le mouvement en soi ; αὐτὴ δικαιοσύνη, PLAT. <i>Rsp. 612</i> a, la justice en soi ; <i>part. au neutre, même avec un subst. masc. ou fém</i>. αὐτὸ ἡ ἀρετή, PLAT. <i>Prot. 360</i> e ; αὐτὸ δικαιοσύνη, PLAT. <i>Rsp. 362</i> e, la vertu, la justice en soi ; <i>qqf., en ce sens, complété par</i> τοῦτο : αὐτὸ τοῦτο πατήρ, PLAT. <i>Conv. 199</i> d, l’idée <i>ou</i> la qualité de père en soi ; ἀδελφὸς αὐτὸ τοῦτο ὅπερ ἔστιν, PLAT. <i>Conv. 199</i> e, ce qu’est un frère en soi ; <i>qqf. redoublé :</i> ἐκ τῆς εἰκόνος μανθάνειν αὐτήν τε αὐτήν, εἰ καλῶς εἴκασται, PLAT. <i>Crat. 439</i> a, se rendre compte par l’image si elle a été bien représentée en soi ;<br><b>   II</b> de soi-même, spontanément : ἀλλά τις αὐτὸς ἴτω, IL. <i>17, 254,</i> que chacun aille de soi-même ; τί με σπεύδοντα καὶ αὐτὸν ὀτρύνεις ; IL. <i>8, 293,</i> pourquoi m’excites-tu lorsque de moi-même je suis plein d’ardeur ? αὐτός σοι πρόσεισι, PLAT. <i>Lys. 206</i> c ; αὐτὴ πρόσεισιν, PLAT. <i>Soph. 265</i> d, il s’avance de lui-même vers toi ; d’elle-même elle s’avance ; (ὡς) αὐτὸ δηλοῖ, PLAT. <i>Prot. 329</i> b, (comme) cela est évident de soi-même ;<br><b>   III</b> <i>p. ext</i>. lui, elle, cela (<i>lat</i>. is, ille, hic) ; <i>en ce sens seul. aux cas obliques, et non au commencement de la proposition (au commencement du vers,</i> IL. <i>14, 457 ;</i> OD. <i>16, 388</i>) :<br><b>      1</b> <i>par une sorte de pléonasme pour rappeler un nom déjà exprimé :</i> Γοργίαν ἐρωτώμενον… αἰσχυνθῆναι αὐτόν, PLAT. <i>Gorg. 482</i> d, Gorgias interrogé, Gorgias, dis-je, eut honte ; πειράσομαι τῷ πάππῳ… συμμαχεῖν αὐτῷ, XÉN. <i>Cyr. 1, 3, 15,</i> je tâcherai de rendre à mon grand-père, de lui rendre, dis-je, quelques services à la guerre ; <i>en ce sens αὐτός est qqf. répété pour marquer l’indignation :</i> αὐτὸς ἐπαγγειλάμενος σώσειν αὐτὸς ἀπώλεσεν, LYS. <i>126, 20,</i> et lui qui annonçait bien haut qu’il la sauverait, c’est lui qui l’a perdue ;<br><b>      2</b> <i>après une proposition commençant par un relatif, pour représenter l’antécédent :</i> ὅς κε θεοῖς ἐπιπείθηται… ἔκλυον αὐτοῦ, IL. <i>1, 218,</i> celui qui obéit aux dieux, les dieux en retour aiment à l’exaucer ; οὓς μὴ εὕρισκον, κενοτάφιον αὐτοῖς ἐποίησαν, XÉN. <i>Cyr. 6, 4, 9,</i> à ceux qu’ils ne trouvèrent point ils firent un cénotaphe ; οἳ ἂν ἐλεγχθῶσι ὡς προδότας αὐτοὺς ὄντας τιμωρηθῆναι, XÉN. <i>An. 2, 5, 27,</i> ceux qui auraient été convaincus, les punir comme traîtres ;<br><b>      3</b> <i>après un terme général exprimant l’idée d’un ensemble, pour marquer les parties ou subdivisions de cet ensemble :</i> ὅσοι… οἱ μὲν αὐτῶν, XÉN. <i>Cyr. 1, 1, 1,</i> de tous ceux qui… les uns ;<br><b>      4</b> <i>postér. p. app. à un pron. relat. :</i> ὧν ὁ μὲν αὐτῶν, CALL. <i>Ep. 44, litt</i>. desquels l’un d’eux ;<br><b>      5</b> <i>abs. au sens d’un pronom personnel :</i> τὴν φωνὴν γνοὺς αὐτοῦ, PLAT. <i>Prot. 309</i> b, ayant reconnu sa voix ; ὅ τι ἂν αὐτοῖς οἴωνται πράξαντες χαριεῖσθαι, PLAT. <i>Phædr. 231</i> b, ce qu’ayant fait ils pensent devoir leur être agréables ; <i>ou au sens d’un pronom démonstratif (v. ci-dessus</i> I, 3) ;<br><b>   IV</b> <i>Précédé de l’article</i> ὁ αὐτός, ἡ αὐτή, τὸ αὐτό (<i>par crase att</i>. αὑτός, αὑτή, ταὐτό <i>et</i> ταὐτόν, <i>v. ci-dessous, fin ; gén</i>. ταὐτοῦ ; <i>dat</i>. ταὐτῷ ; <i>plur. neutre</i> ταὐτά) le même (<i>lat</i>. idem) : ἐπὶ τὸ αὐτὸ αἱ γνῶμαι ἔφερον, THC. <i>1, 79,</i> les avis aboutissaient à la même conclusion ; οὐδεὶς αὐτὸς εὐτυχεῖ ποτε, EUR. <i>Tr. 1206,</i> nul ne reste toujours heureux ; <i>avec un dat</i>. τὸ αὐτὸ πρήσσειν <i>ou</i> πάσχειν τινί, HDT. <i>4, 119,</i> faire <i>ou</i> subir la même chose que qqn ; οὐ πεπαίδευνται τὸν αὐτὸν τρόπον ἡμῖν, XÉN. <i>Cyr. 2, 2, 1,</i> ils ne sont pas élevés de la même manière que nous ; <i>avec</i> τε… καί : οὐ ταὐτὰ παρά τε τῷ πάππῳ καὶ ἐν Πέρσαις, XÉN. <i>Cyr. 1, 3, 15,</i> ce n’est pas la même chose chez (ton) grand-père et chez les Perses (<i>cf</i>. XÉN. <i>Hell. 3, 2, 6 ; Mem. 3, 4, 6, etc.) ; avec</i> ὅσπερ : τοῦ αὐτοῦ ἕνεκα οὗπερ, XÉN. <i>Lac. 12, 4,</i> pour le même motif pour lequel (<i>cf</i>. XÉN. <i>Mem. 3, 1, 15) ; avec</i> ὥσπερ : εἰς τὸ αὐτὸ σχῆμα ὥσπερ τὸ πρῶτον, XÉN. <i>An. 1, 10, 7,</i> dans la même position que d’abord ; <i>adv</i>., ἐν τῷ αὐτῷ, dans le même lieu, ensemble : ἐπειδὰν ἐν τῷ αὐτῷ ὦσι ψυχὴ καὶ σῶμα, PLAT. <i>Phæd. 79</i> e, une fois que l’âme et le corps sont unis (<i>cf</i>. PLAT. <i>Prot. 336</i> a ; <i>Gorg. 490</i> b, <i>etc</i>.).<br><span>•<i> Cp</i>. αὐτότερος, EPICH. <i>fr. 2 Ahrens ;</i> <i>• Sup</i>. αὐτότατος, AR. <i>Pl. 83 (cf. lat</i>. ipsissimus), tout à fait lui, lui-même en personne.<br><span><b><span class=\"arrow\"></span></b> <i>Pour la crase att. de</i> αὑτός = ὁ αὐτός, αὑτή = ἡ αὐτή, <i>etc. v. ci-dessus ; au neutre</i> ταὐτό, SOPH. <i>O.R. 734 ; etc. ou</i> ταὐτόν, SOPH. <i>O.R. 325 ; O.C. 612 ; Ph. 546, etc. Cette crase de l’article et du pronom au sg. comme au plur. est facultative, mais elle est de règle dans les locut</i>. ἐκ ταὐτοῦ, ἐν ταὐτῷ, εἰς ταὐτόν. — <i>Formes dialect. Crase dor</i>. ωὑτός = ὁ αὐτός, IL. <i>5, 396 ;</i> THCR. <i>Idyl. 11, 34 (var</i>. οὗτος) ; <i>18, 22 ; 26, 23. Par crase, gén. fém. dor</i>. καὐτᾶς (<i>var</i>. καὔτας) = καὶ αὐτάς, THCR. <i>Idyl. 30, 32. Acc. pl. fém. dor</i>. αὐτάς <span>[ᾰς]</span> THCR. <i>Idyl. 3, 2. — Outre les formes ou emplois classiques ci-dessus mentionnés, on rencontre dans les inscript. att. :</i><br><b>      1</b> ἀτός = αὐτός, CIA. <i>2, 482, 63 (39-32 av. J.C</i>.) ; ;<br><b>      2</b> αὐτός <i>au sens de</i> οὗτος ; αὐτοῦ, αὐτῷ, αὐτόν, <i>etc. au sens de</i> τούτου, <i>etc</i>. CIA. <i>2 add. 841 b, 13 (396 av. J.C.) etc. ;</i><br><b>      3</b> <i>À l’époque impériale</i> αὐτοῦ <i>au sens de</i> ἑαυτοῦ : τοὺς ὑπ' αὐτῷ, CIA. <i>3, 1147, 4 (180/192 après J.C</i>.) ; τοὺς ἐπ' αὐτῶν, CIA. <i>3, 1143, 4 (179/180 après J.C.) à côté des formes correctes</i> τοὺς ὑφ' ἑαυτοῖς, <i>etc</i>.<br><span><b>Étym</b>. αὖ, <i>rad. pronom</i>. -το ; <i>cf</i>. αὖ-τε, αὐ-τίκα, αὐ-τάρ, <i>et voy. le commenc. de l’art</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυτος - αὐτός</font>\n<br><br>Voir définition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5483 fois dans 3663 versets de 27 livres bibliques (NT)\n<ul>\n<li>Matthieu (911)</li>\n<li>Marc (753)</li>\n<li>Luc (1054)</li>\n<li>Jean (764)</li>\n<li>Actes (691)</li>\n<li>Romains (153)</li>\n<li>1 Corinthiens (87)</li>\n<li>2 Corinthiens (59)</li>\n<li>Galates (24)</li>\n<li>Ephésiens (61)</li>\n<li>Philippiens (30)</li>\n<li>Colossiens (44)</li>\n<li>1 Thessaloniciens (23)</li>\n<li>2 Thessaloniciens (16)</li>\n<li>1 Timothée (7)</li>\n<li>2 Timothée (16)</li>\n<li>Tite (8)</li>\n<li>Philémon (3)</li>\n<li>Hébreux (139)</li>\n<li>Jacques (41)</li>\n<li>1 Pierre (34)</li>\n<li>2 Pierre (29)</li>\n<li>1 Jean (100)</li>\n<li>2 Jean (7)</li>\n<li>3 Jean (5)</li>\n<li>Jude (9)</li>\n<li>Apocalypse (415)</li>\n</ul>\n</td></tr>\n</table>","G847":"<h1>autou</h1>\n<p>Strong n° 847 <i>Prononciation [ow-too']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dans ce lieu, ici, là</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐτοῦ</b>, <i>adv. :</i><br><b>      1</b> (<i>avec idée de lieu</i>) là même, ici même, IL. <i>1, 428 ;</i> OD. <i>15, 199 ;</i> HDT. ATT. ; <i>souv. suivi du n. de lieu ;</i> αὐτοῦ ἐνὶ Τροίῃ, IL. <i>2, 237,</i> là même à Troie ; αὐτοῦ παρὰ κλισίῃσιν, IL. <i>15, 656,</i> là même près des tentes ; <i>cf</i>. IL. <i>8, 207 ;</i> OD. <i>10, 96, etc. ;</i> αὐτοῦ ὑπὲρ κεφαλῆς, OD. <i>8, 68,</i> là même au-dessus de la tête ; <i>rar. précédé de ce n. de lieu :</i> κεῖθι αὐτοῦ, HH. <i>Ap. 374 ;</i> ἐνθάδ' αὐτοῦ, SOL. <i>35, 11 ;</i> SOPH. <i>O.C. 78 ;</i> AR. <i>Pl. 1187,</i> là même ; που αὐτοῦ ἀγρῶν, OD. <i>4, 639,</i> quelque part là dans les champs ; <i>avec mouv</i>. αὐτοῦ ἐς, HDT. là vers ;<br><b>      2</b> (<i>avec idée de temps</i>) sur-le-champ, à l’instant même, aussitôt, IL. <i>15, 349 ; 21, 425 ;</i> OD. <i>4, 703 ; 18, 212</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. αὐτῶ, THCR. <i>Idyl. 11, 14</i>.<br><span><b>Étym</b>. αὐτός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυτου - αὐτοῦ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G848":"<h1>hautou</h1>\n<p>Strong n° 848 <i>Prononciation [how-too']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>de lui-même, elle-même</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὑτοῦ</b>, <i>v</i>. ἑαυτοῦ.<br>\n<b>ἑαυτοῦ, ῆς, οῦ</b> (<i>contr</i>. αὑτοῦ, ῆς, οῦ) ; <i>acc. neutre</i> ἑαυτό ; <i>gén. pl</i>. ἑαυτῶν, <i>etc. :</i><br><b>      1</b> de soi-même, à soi-même, soi-même : ἑαυτὸν σφάττειν, XÉN. <i>Cyr. 7, 3, 5 ;</i> ARSTT. <i>Nic. 5, 11,</i> s’égorger soi-même ; πλουσιώτεροι ἑαυτῶν γιγνόμενοι, THC. <i>1, 8,</i> devenant plus riches qu’ils n’étaient ; <i>qqf. renforcé par αὐτός construit avec le sujet de la prop. :</i> οὐχ οἷός τέ ἐστιν αὐτὸς αὑτῷ βοηθεῖν, PLAT. <i>Gorg. 483</i> b, il n’est pas en état de se défendre lui-même ; τὸ γιγνώσκειν αὐτὸν ἑαυτόν, PLAT. <i>Charm. 165</i> b, se connaître soi-même ; <i>abs. dans un grand nombre de loc. :</i> τὸ ἑαυτοῦ μόνον σκοπεῖν, THC. <i>6, 12,</i> ne regarder que soi-même, <i>càd</i>. que son propre intérêt ; ἐν τοῖς ἑαυτοῦ, ATH. <i>1</i> a, <i>ou</i> παρ' ἑαυτῷ, XÉN. <i>Mem. 3, 13, 3 ;</i> NT. <i>1Cor. 16, 2,</i> dans sa propre maison, chez soi ; <i>avec mouv</i>. πρὸς ἑαυτόν, NT. <i>Luc. 24, 12, ou, en parl. de plus. pers</i>. εἰς ἑαυτῶν, AR. <i>Lys. 1070 ;</i> πρὸς ἑαυτούς, NT. <i>Joh. 20, 10,</i> à sa maison, chez soi ; αὐτὸ καθ' αὑτό, PLAT. <i>Theæt. 157</i> a ; αὐτὸ ἐφ' ἑαυτό, <i>Theæt. 152</i> b ; αὐτὸ ἐφ' αὑτοῦ, <i>Theæt. 160</i> c, de soi-même, <i>càd</i>. absolument ; ἑαυτοῦ εἶναι, PLUT. <i>M. 233</i> d, être son maître, être indépendant ; ἐξ ἑαυτοῦ γίγνεσθαι, SPT. <i>3Reg. 10, 5,</i> être hors de soi, être frappé d’étonnement ; ἐν ἑαυτῷ γίγνεσθαι, XÉN. <i>An. 1, 5, 17,</i> revenir à soi, redevenir maître de soi ;<br><b>      2</b> <i>chez les Att., au plur. et qqf. au sg., pour les pronoms de la 1<sup>re</sup> et de la 2<sup>e</sup> pers. : p</i>. ἐμαυτοῦ, ESCHL. <i>Ch. 221, 1014 ;</i> SOPH. <i>O.R. 138 ;</i> POL. <i>2, 37, 2 ;</i> SPT. <i>Gen. 11, 4 ; 1 Macc. 5, 57 ; etc. ; p</i>. σεαυτοῦ, ESCHL. <i>Ag. 1142, 1297 ; etc. ;</i> POL. <i>3, 109, 9 ; 18, 6, 4 ;</i> SPT. <i>Sir. 51, 25 ; Jer. 4, 3, etc. ; au pl. p</i>. ἡμῶν αὐτῶν, ἡμᾶς αὐτούς, <i>etc. ;</i> ἴστε ἡμᾶς Φωκίδα ὑφ' ἑαυτοὺς πεποιημένους, DÉM. <i>238, 26,</i> vous savez que nous avons soumis la Phocide à notre propre domination ; <i>cf</i>. ESCHL. <i>Suppl. 806 ;</i> POL. <i>2, 37, 2, etc. ;</i><br><b>      3</b> <i>au pl. p</i>. ἀλλήλων, ἀλλήλοις, des uns aux autres, les uns aux autres : φθονοῦντες ἑαυτοῖς μισοῦσιν ἀλλήλους, XÉN. <i>Mem. 2, 6, 20,</i> se portant mutuellement envie, ils se haïssent les uns les autres ; περιϊόντες αὑτῶν πυνθάνονται, DÉM. <i>43, 7,</i> circulant (sur la place) ils s’informent les uns auprès des autres ; <i>cf</i>. HDT. <i>3, 49 ;</i> THC. <i>4, 25, etc. ;</i> SPT. <i>Sap. 5, 3, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἑωϋτοῦ <i>ou mieux</i> ἑωυτοῦ, ἑωυτῷ, ἑωυτόν, HPC. <i>1207</i> b, <i>1210</i> e, <i>1222 d, e, 1233</i> e, <i>etc. ; ou</i> ωὑτέου, ARÉT. <i>Caus. m. acut. 1, 7, p. 5 ; plur</i>. ωὑτέων, <i>Caus. m. acut. 1, 7, p. 34 ;</i> ωὑτέοισι, <i>Caus. m. acut. 2, 4, p. 17. — Dans les inscr. att. du 4<sup>e</sup> siècle av. J.C. la forme pleine au sg. et au plur</i>. (ἑαυτοῦ, ἑαυτῶν) <i>et la forme contracte</i> (αὑτοῦ, αὑτῶν) <i>sont à peu près aussi usitées (la forme pleine un peu plus, 31</i> ἑαυτ. <i>contre 23</i> αὑτ.) ; <i>de 300 à 30 av. J.C. la forme pleine devient dominante (100</i> ἑαυτ. <i>contre 7</i> αὑτ.), <i>p.-ê. parce que la prononciat. de l’esprit rude s’étant affaiblie,</i> αὑτοῦ <i>ne se distinguait plus assez nettement de</i> αὐτοῦ (<i>v. Meisterh. p. 121, 4). À partir de 74 av. J.C. environ,</i> ἑαυτοῦ, <i>etc. s’affaiblit qqf. dans les inscr. att. en</i> ἑατοῦ, ἑατῆς, ἑατῷ, ἑατόν, ἑατῶν, ἑατούς, <i>et même en</i> ἁτῶν (<i>v. Meisterh. p. 121, 5). Enfin, sous l’empire, αὑτοῦ, αὑτῶν est qqf. remplacé par le pron. pers</i>. αὐτοῦ, αὐτῶν (<i>v. Meisterh. p. 122</i>).<br><span><b>Étym</b>. ἕ, αὐτός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυτου - αὑτοῦ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Jean (2)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G849":"<h1>autocheir</h1>\n<p>Strong n° 849 <i>Prononciation [ow-tokh'-ire]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>faire une chose de ses propres mains (souvent utilisé par les auteurs de tragédies)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐτό·χειρ, -χειρος (ὁ, ἡ) :<br>   I</b> <i>act. :</i><br><b>      1</b> qui fait qqe ch. de sa propre main, ESCHL. <i>Suppl. 592 ;</i> SOPH. <i>Tr. 1194, etc. ;</i> AR. <i>Av. 1132, etc. ; avec un gén</i>. αὐτ. τάφου, SOPH. <i>Ant. 306,</i> celui qui dispose de sa main une sépulture ; αὐτ. ἔργου, ANT. le propre auteur d’une action ; αὐτ. οὔτε τῶν ἀγαθῶν, οὔτε τῶν κακῶν, ISOCR. <i>112</i> d, qui ne fait de sa main ni le bien ni le mal ; αὐτ. φόνου, SOPH. <i>O.R. 266 ;</i> PLAT. <i>Rsp. 615</i> c ; <i>Ep. 334</i> a ; <i>etc</i>. qui commet un meurtre de sa main ;<br><b>      2</b> <i>p. suite, abs</i>. qui commet un meurtre de sa main, meurtrier, SOPH. <i>O.R. 231 ;</i> DÉM. <i>552, 18, etc. ; avec un gén</i>. αὐτ. τινός, DÉM. <i>549, 5 ;</i> ANT. <i>134, 46 ; 136, 34 ;</i> POL. <i>2, 58, 8 ;</i> PLUT. <i>Rom. 23, etc</i>. meurtrier de qqn ;<br><b>   II</b> <i>pass</i>. accompli par la propre main de qqn ; <i>part. en parl. de mort violente, de meurtres commis par suicide ou entre parents :</i> αὐτ. θάνατος, σφαγή, EUR. <i>Ph. 880 ; Or. 947,</i> meurtre commis sur soi-même <i>ou</i> sur ses propres parents ; πληγέντες αὐτόχειρι σὺν μιάσματι, SOPH. <i>Ant. 172,</i> frappés par un meurtre dont ils ont souillé leurs mains, <i>en parl. de frères qui s’entr’égorgent ; postér. en gén</i>. αὐτόχειρα γράμματα, DC. <i>59, 4,</i> lettres écrites de la propre main de qqn, lettres autographes.<br><span><b>Étym</b>. αὐτός, χείρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυτοχειρ - αὐτόχειρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G850":"<h1>auchmeros</h1>\n<p>Strong n° 850 <i>Prononciation [owkh-may-ros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>misérable, sale\n<ol type=\"a\">\n<li>les choses sales étant dépourvues de brillance : sombre, obscur</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αὐχμηρός, ά, όν :<br>   I</b> desséché, <i>d’où</i> sec, <i>en parl. de saisons,</i> HPC. <i>Aph. 1247 ;</i> ARSTT. <i>H.A. 8, 27, etc. ; de pays,</i> PLAT. <i>Leg. 761</i> b ; TH. <i>H.P. 9, 11, 10, etc. ; de fruits,</i> DS. <i>2, 53 ;</i><br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> malpropre, sale, <i>en parl. de la chevelure,</i> SOPH. <i>fr. 422 ;</i> EUR. <i>Or. 387 ; d’une crinière,</i> THCR. <i>Idyl. 25, 225 ;</i><br><b>      2</b> pauvre, misérable, LUC. <i>Salt. 1 ;</i> MAN. <i>2, 454 ; 3, 57 ;</i><br><b>      3</b> malheureux, triste, MAN. <i>2, 169</i>.<br><span>•<i> Cp</i>. αὐχμηρότερος, HPC. <i>598, 4 ;</i> ARSTT. <i>H.A. 1, 17 ; 3, 20</i>. <i>• Sup</i>. αὐχμηρότατος, PLAT. <i>Leg. 761</i> a.<br><span><b>Étym</b>. αὐχμός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αυχμηρος - αὐχμηρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G851":"<h1>aphaireo</h1>\n<p>Strong n° 851 <i>Prononciation [af-ahee-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ôter, emporter, transporter, enlever</li>\n<li>couper, retrancher</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφαιρέω-ῶ</b> <span>(<i>f</i>. ἀφαιρήσω ; <i>ao.2</i> ἀφεῖλον, <i>postér. ao.1</i> ἀφῄρησα, <i>pf</i>. ἀφῄρηκα)</span><br><b>      1</b> enlever, ôter ; τι, HDT. <i>1, 80 ;</i> ATT. qqe ch. ; τί τινι, OD. <i>14, 455 ;</i> qqe ch. à qqn ; τί τινος, XÉN. <i>Lac. 4, 7 ;</i> AR. <i>Pax 561,</i> dépouiller qqn de qqe ch. ; τινά τι, ESCHL. <i>Eum. 360 ;</i> SOPH. <i>Ph. 933,</i> enlever qqe ch. à qqn ; <i>au pass</i>. être privé <i>ou</i> dépouillé : τι, HDT. <i>3, 137 ;</i> ESCHL. <i>Ch. 962,</i> de qqe ch. ; τι πρός τινος, <i>ou</i> ὑπό τινος, HDT. <i>4, 70 ; 3, 65 ; 7, 159,</i> être dépouillé de qqe ch. par qqn ; <i>abs</i>. ὁ ἀφαιρεθείς, PLAT. <i>Leg. 915</i> a, celui qui a été dépossédé, qui a souffert un dommage, le plaignant ;<br><b>      2</b> séparer, éloigner : τι ἀπό τινος ἀφ. χωρίς, PLAT. <i>Pol. 258</i> c ; <i>ou</i> τί τινος, PLAT. <i>Rsp. 360</i> e ; τι ἔκ τινος, ESCHL. <i>Eum. 444,</i> séparer une chose d’une autre ;<br><b>      3</b> <i>p. suite,</i> ôter une part de : τινος, XÉN. <i>Vect. 4, 4,</i> d’une chose, <i>càd</i>. diminuer qqe ch. ; <i>part. t. d’arithm</i>. faire une soustraction, soustraire, NICOM. <i>Theol. 86 ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. ἀφαιρήσομαι, <i>ao.2</i> ἀφειλόμην, <i>pf</i>. ἀφῄρημαι, <i>v. ci-dessous fin</i>)</span><br><b>      1</b> enlever, ôter <i>avec un seul rég. de chose à l’acc. :</i> τι, HOM. <i>etc</i>. enlever <i>ou</i> supprimer qqe ch. ; τὸ ἔργον, THC. <i>4, 134,</i> mettre fin à l’action, <i>en parl. de la nuit ;</i> ψήφισμα, AND. <i>22, 37,</i> annuler <i>ou</i> abroger un décret ; τὴν μνήμην τινός, DÉM. <i>597, 17,</i> ôter <i>ou</i> anéantir le souvenir de qqe ch. ; <i>avec double rég. de pers. et de chose :</i> ἀφ. τινί τι, IL. <i>1, 161 ;</i> τινά τι, IL. <i>1, 275 ;</i> HDT. <i>1, 171 ;</i> ATT. (EUR. <i>Andr. 613, etc</i>.) ; τινός τι, IL. <i>5, 673, 691, etc. ;</i> LYS. <i>168, 36 ; qqf</i>. τι ἀπό τινος, AR. <i>Vesp. 883, ou</i> τι ἔκ τινος, XÉN. <i>Cyn. 12, 9,</i> enlever qqe ch. à qqn, priver qqn de qqe ch. ; <i>avec double rég. de chose :</i> τεύχεα ὤμοιϊν, IL. <i>13, 511,</i> ôter une armure de dessus les épaules (d’un guerrier mort) ;<br><b>      2</b> écarter, éloigner : κύνας τοῦ εὑρεῖν, XÉN. <i>Cyn. 6, 4,</i> empêcher des chiens de trouver ; ψόγον πρὸς Ἑλλάδος, EUR. <i>Tr. 1034,</i> détourner le blâme qui viendrait de la Grèce ; <i>avec un acc. de pers. et un inf. précédé de</i> μή : ἀφ. τινα μὴ ποιεῖν τι, SOPH. <i>Ph. 1303 ;</i> EUR. <i>Tr. 1146 ;</i> PAUS. <i>8, 52, 2 ; 9, 1, 7 ;</i> APP. <i>Lib. 50,</i> empêcher qqn de faire qqe ch. : <i>avec un inf. seul :</i> ἀφαιρεῖσθαι εἰσορᾶν τι, EUR. <i>Hipp. 1207,</i> être empêché de regarder qqe ch. ; <i>p. suite,</i> entraîner, <i>dans les locut</i>. ἀφ. τινα εἰς ἐλευθερίαν, PLAT. <i>Leg. 914</i> e ; ISOCR. <i>252</i> e ; DÉM. <i>1327, 22 ; 1328, 8 ; 1358, 18 ; 1360, 4 ; etc. ou</i> πρὸς ἐλευθερίαν, LUC. <i>M. cond. 4,</i> affranchir qqn, <i>litt</i>. arracher qqn (à la servitude) et l’amener à la liberté ;<br><b>      3</b> <i>abs</i>. enlever par amputation, couper (la tête, les oreilles, <i>etc.) acc</i>. SPT. <i>1Macc. 7, 47 ;</i> NT. <i>Matth. 26, 51, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. ao.1</i> ἀφῄρησα, GAL. <i>1, 384. Pass. f</i>. ἀφαιρεθήσομαι, EUR. <i>Hel. 938 ;</i> THC. <i>6, 40 ;</i> JOS. <i>A.J. 6, 7, 4. Moy. f</i>. ἀφαιρήσομαι <i>au sens act</i>. SOPH. <i>Ph. 376 ;</i> AR. <i>Ach. 464 ; au sens pass</i>. EUR. <i>Tr. 1278 (conj</i>. ἀφῃρήσομαι) ; <i>fut. réc</i>. ἀφελοῦμαι, TIMOSTRATOS <i>fr. 4 ;</i> ANTH. <i>9, 108 ;</i> POL. <i>3, 29, 7. Ao.1 réc</i>. ἀφειλάμην, PHRYN. <i>183 ;</i> LEX. <i>469 Bekker, etc. — Conjug. ion</i>. ἀπαιρέω, <i>d’où impf. itér. 3 pl</i>. ἀπαιρέεσκον, HDT. <i>1, 186 ; pf. pass</i>. ἀπαραίρημαι, HDT. <i>3, 126 ; 7, 159 ; 9, 103. — Conjug. épq</i>. ἀποαιρέω, <i>d’où moy. prés. impér. 2 sg</i>. ἀποαίρεο, <i>par sync. de</i> ἀποαιρέεο <i>avec recul de l’accent,</i> IL. <i>1, 275 ; et inf</i>. ἀποαιρεῖσθαι, IL. <i>1, 230</i>.<br><span><b>Étym</b>. ἀπό, αἱρέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφ-αιρεω - ἀφαιρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 9 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Romains (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G852":"<h1>aphanes</h1>\n<p>Strong n° 852 <i>Prononciation [af-an-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>non manifesté, caché, invisible</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀ·φανής, ής, ές</b> <span>[ᾰᾰ]</span> non apparent, <i>d’où :</i><br><b>   I</b> qu’on ne voit pas, <i>càd. :</i><br><b>      1</b> invisible, <i>en parl. du Tartare,</i> PD. <i>fr. 223 ;</i> ἡ ἀφ. θεός, SOPH. <i>O.C. 1556,</i> la déesse invisible (Perséphonè) ; ὁ ἀφ. πόλος, ARSTT. <i>Cæl. 2, 2, 15,</i> le pôle invisible, <i>càd</i>. le pôle sud ;<br><b>      2</b> qui n’est pas en vue : ἀφ. χωρίον, THC. <i>4, 29,</i> place hors de portée de la vue ;<br><b>      3</b> caché, secret : ἀφ. ξιφίδιον, THC. <i>8, 69,</i> poignard caché ; ἀφ. νεῦμα, THC. <i>1, 134,</i> signe secret ; <i>avec un part</i>. μαντικῇ χρώμενος οὐκ ἀφανὴς ἦν, XÉN. <i>Mem. 1, 1, 2 ;</i> on savait bien qu’il s’occupait de divination ; <i>adv</i>., ἐν ἀφανεῖ, THC. <i>1, 42, etc. ;</i> PLAT. <i>Leg. 954</i> d, dans l’obscurité <i>ou</i> dans le secret ; ἐκ τοῦ ἀφανοῦς, THC. <i>1, 51, etc. ;</i> ἐξ ἀφανοῦς, ESCHL. <i>fr. 55,</i> en secret ;<br><b>      4</b> inconnu, obscur : ἀφ. νόσος, HDT. <i>2, 84,</i> maladie inconnue <i>ou</i> obscure ; ἀφ. ἐλπίς, THC. <i>5, 103,</i> espérance incertaine ; ἀ. λόγος, SOPH. <i>O.R. 656,</i> assertion sans preuves ; τὸ τῆς τύχης ἀφανές, EUR. <i>Alc. 785,</i> l’incertitude de la fortune ; <i>en parl. de pers</i>. EUR. <i>Tr. 1244, 1322 ;</i> THC. <i>3, 57 ;</i><br><b>   II</b> qu’on ne voit plus : ἀφανῆ γίγνεσθαι, HDT. <i>3, 104 ;</i> EUR. <i>I.T. 757 ;</i> PLAT. <i>Rsp. 359</i> e, devenir invisible, disparaître ; ἀφ. ἦν, HDT. <i>7, 37,</i> il était disparu ; οἱ ἀφανεῖς, THC. <i>2, 34,</i> les soldats disparus (dans une bataille) ;<br><b>   III</b> qui est <i>ou</i> qu’on peut rendre invisible : ἀφ. οὐσία, LYS. <i>fr. 47 ;</i> ἀφ. πλοῦτος, AR. <i>Eccl. 602,</i> fortune mobilière, <i>litt</i>. celle qu’on ne voit pas <i>ou</i> qui peut être dissimulée, <i>p. opp. aux biens-fonds</i> (οὐσία φανερά) ; ἀφανῆ καταστῆσαι τὴν οὐσίαν, LYS. <i>160, 8,</i> placer sa fortune en valeurs mobilières, en argent (<i>ttf. au sens propre de</i> « invisible, caché » πλοῦτος ἀφ. ὃν σὺ κατορύξας ἔχεις, MÉN. <i>dans</i> STOB. <i>Fl. 16, 13,</i> cette fortune invisible que tu gardes enfouie, <i>p. opp. à</i> φίλος ἐμφανής).<br><span>•<i> Cp</i>. ἀφανέστερος, PHIL. <i>V.M. 1</i>. <i>• Sup</i>. ἀφανέστατος, HPC. <i>295, 53 ;</i> THC. <i>1, 23 ;</i> XÉN. <i>Cyr. 3, 3, 28</i>.<br><span><b>Étym</b>. ἀ, φαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφανης - ἀφανής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G853":"<h1>aphanizo</h1>\n<p>Strong n° 853 <i>Prononciation [af-an-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre hors de vue, rendre invisible</li>\n<li>quelque chose qui s'évanouit, détruire, consumer, anéantir</li>\n<li>priver d'éclat, rendre laid\n<ol type=\"a\">\n<li>défigurer, enlaidir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφανίζω</b> <span>(<i>impf</i>. ἠφάνιζον, <i>f</i>. ἀφανίσω, <i>att</i>. ἀφανιῶ ; <i>ao</i>. ἠφάνισα, <i>pf</i>. ἠφάνικα ; <i>pass. f</i>. ἀφανισθήσομαι, <i>ao</i>. ἠφανίσθην, <i>pf</i>. ἠφάνισμαι)</span> <span>[ᾰᾰ]</span><br><b>   I</b> faire disparaître, <i>d’où :</i><br><b>      1</b> rendre invisible : ἥλιον, XÉN. <i>An. 3, 4, 8,</i> cacher le soleil, <i>en parl. d’un nuage ;</i> ἀφ. τὴν οὐσίαν, ESCHN. <i>14, 38 ;</i> DÉM. <i>827, 12, litt</i>. soustraire sa fortune aux regards, <i>càd</i>. la convertir en biens meubles, en argent ;<br><b>      2</b> supprimer, anéantir : τινά, HDT. <i>3, 126 ;</i> THC. <i>4, 80 ;</i> XÉN. <i>Mem. 1, 2, 52,</i> faire disparaître qqn (un criminel d’État, <i>etc.) ; au pass</i>. ἀφανίζεσθαι ἐξ ἀνθρώπων, HDT. <i>4, 95 ;</i> LYS. <i>191, 27 ;</i> ISOCR. <i>60</i> c, <i>104</i> b, <i>119</i> d, disparaître d’entre les hommes, <i>càd</i>. périr ; <i>en parl. de choses,</i> détruire de fond en comble (un édifice, un temple, <i>etc</i>.) DÉM. <i>562, 17 ;</i> effacer (des traces de pas, des traces de sang, <i>etc</i>.) XÉN. <i>Cyn. 5, 3, etc. ;</i> ANT. <i>134, 37 ; fig</i>. ἀγαθῷ κακόν, THC. <i>2, 42,</i> effacer le mal avec le bien ;<br><b>      3</b> perdre (de l’argent, des biens, <i>etc</i>.) ESCHN. <i>14, 24 ;</i> DÉM. <i>821,</i> fin, <i>etc. ;</i><br><b>      4</b> tenir caché <i>ou</i> secret, dissimuler : τὴν γνώμην, THC. <i>7, 8,</i> sa pensée ; <i>au propre,</i> τρίχα βαφῇ, EL. <i>V.H. 7, 20,</i> dissimuler la couleur de ses cheveux en les teignant ;<br><b>      5</b> éloigner, écarter : τινὰ πόλεος, EUR. <i>Ph. 1041,</i> emmener qqn hors de la ville ; παῖδας καὶ γυναῖκας, XÉN. <i>Cyr. 7, 2, 12,</i> emmener des enfants et des femmes en esclavage ; <i>fig</i>. ἄχος, SOPH. <i>O.C. 1712,</i> calmer (<i>litt</i>. écarter) une douleur ; <i>au pass</i>. se tenir à l’écart, vivre dans la retraite, XÉN. <i>Ages. 9, 1 ;</i><br><b>      6</b> emporter, dérober, soustraire, XÉN. <i>Œc. 14, 2 ;</i><br><b>   II</b> obscurcir, ternir : τὴν ἀξίωσιν, THC. <i>2, 61 ;</i> τὰς πατρικὰς ἀρετάς, THC. <i>7, 69,</i> la considération dont on jouit, les vertus de ses ancêtres.<br><span><b>Étym</b>. ἀφανής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-φανιζω - ἀφανίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Actes (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G854":"<h1>aphanismos</h1>\n<p>Strong n° 854 <i>Prononciation [af-an-is-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>disparition</li>\n<li>destruction, anéantissement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφανισμός, οῦ (ὁ)</b> <span>[ᾰᾰ]</span><br><b>   I</b> <i>tr. :</i><br><b>      1</b> destruction, dommage, POL. <i>5, 11, 5 ;</i> DS. <i>15, 48 ;</i> SPT. <i>Deut. 7, 2, etc. ;</i><br><b>      2</b> action de dissimuler (ses traits) CHRYS. ;<br><b>   II</b> <i>intr</i>. disparition (<i>de la lune, des astres</i>) TH. <i>fr. 6, 1, 2 ;</i> PLUT. <i>M. 670</i> b ; <i>en parl. de pers</i>. PLUT. <i>Rom. 27</i>.<br><span><b>Étym</b>. ἀφανίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφανισμος - ἀφανισμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G855":"<h1>aphantos</h1>\n<p>Strong n° 855 <i>Prononciation [af'-an-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>mettre hors de vue, rendre invisible</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄ·φαντος, ος, ον :<br>   I</b> qu’on ne voit pas, <i>càd. :</i><br><b>      1</b> invisible, caché, SOPH. <i>Ph. 297 ; d’où</i> secret, PD. <i>P. 11, 30 ;</i><br><b>      2</b> obscur, PD. <i>N. 8, 34 ;</i><br><b>   II</b> qu’on ne voit plus, disparu, anéanti, IL. <i>20, 303 ;</i> ESCHL. <i>Ag. 624 ;</i> ἄφαντον οἴχεσθαι <i>ou</i> ἔρρειν, ESCHL. <i>Ag. 657 ;</i> SOPH. <i>O.R. 560,</i> disparaître, s’anéantir ; <i>p. suite,</i> oublié, IL. <i>6, 60</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Poét. ; en prose, seul</i>. NT. <i>Luc. 24, 31</i>.<br><span><b>Étym</b>. ἀ, φαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-φαντος - ἄφαντος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G856":"<h1>aphedron</h1>\n<p>Strong n° 856 <i>Prononciation [af-ed-rone']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un lieu où les déchets humains sont déposés\n<ol type=\"a\">\n<li>les privés, égouts, toilettes, lieu d'aisance, latrines</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφ·εδρών, ῶνος (ὁ)</b> lieux d’aisances, NT. <i>Matth. 15, 17 ;</i> GRAMM. <i>469, 23 Bekker, Anecdota græca</i>.<br><span><b>Étym</b>. ἀπό, ἕδρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφεδρων - ἀφεδρών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G857":"<h1>apheidia</h1>\n<p>Strong n° 857 <i>Prononciation [af-i-dee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sévérité impitoyable, absence de ménagement, action de traiter durement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφειδία, ας (ἡ)</b> <span>[ᾰφ]</span> action de ne pas épargner, <i>d’où :</i><br><b>      1</b> prodigalité, profusion, PLAT. <i>Def. 412</i> c ; PLUT. <i>M. 762</i> d ;<br><b>      2</b> traitement rigoureux, NT. <i>Col. 2, 23</i>.<br><span><b>Étym</b>. ἀφειδής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-φειδια - ἀφειδία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G858":"<h1>aphelotes</h1>\n<p>Strong n° 858 <i>Prononciation [af-el-ot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>simplicité, souplesse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφελότης, ητος (ἡ)</b> <i>c</i>. ἀφέλεια, NT. <i>Ap. 2, 46</i>.<br><b>ἀφέλεια, ας (ἡ)</b> simplicité, naïveté, ANTIPH. (ATH. <i>446</i> c) ; <i>en parl. du genre de vie,</i> POL. <i>6, 48, 3 ; en parl. du style,</i> ATH. <i>693</i> f.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἀφελίη, HPC. <i>22, 43</i>.<br><span><b>Étym</b>. ἀφελής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφελοτης - ἀφελότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G859":"<h1>aphesis</h1>\n<p>Strong n° 859 <i>Prononciation [af'-es-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>libérer de l'esclavage ou de l'emprisonnement</li>\n<li>oubli ou pardon des péchés, (considérés comme n'ayant jamais été commis), rémission des peines, remise, pardon</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄφεσις, εως (ἡ)</b> <span>[ᾰ]</span> <i>litt</i>. action de laisser aller, <i>d’où :</i><br><b>   I</b> envoi (de vaisseaux), PHILIPP. (DÉM. <i>251, 3) ; part. :</i><br><b>      1</b> action de laisser partir les chars et les coureurs dans la carrière, DS. <i>4, 73 ; d’où</i> entrée de la carrière, PAUS. <i>5, 14, 4, etc. ;</i><br><b>      2</b> départ d’un essaim, <i>d’où</i> essaim, ARSTT. <i>H.A. 9, 40, 25 ;</i><br><b>      3</b> émission, éjaculation, ARSTT. <i>P.A. 4, 13, 26, etc. ;</i><br><b>   II</b> action de congédier, <i>d’où :</i><br><b>      1</b> renvoi, licenciement d’esclaves, de prisonniers, PLAT. <i>Pol. 273</i> c ;<br><b>      2</b> répudiation d’une femme, PLUT. <i>Pomp. 44 ;</i><br><b>      3</b> décharge du service militaire, PLUT. <i>Ages. 24 ;</i> remise d’une dette, ISOCR. <i>364</i> d ; DÉM. <i>893, 13 ; 1114, 8 ;</i> SPT. <i>Deut. 15, 3, etc. ;</i> remise <i>ou</i> absolution d’une faute, PLAT. <i>Leg. 869</i> d.<br><span><b>Étym</b>. ἀφε- <i>rad. verb. de</i> ἀφίημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφεσις - ἄφεσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n17 fois dans 16 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (5)</li>\n<li>Actes (5)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G860":"<h1>haphe</h1>\n<p>Strong n° 860 <i>Prononciation [haf-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lien, parenté, jointure, attache</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n① <b>ἁφή, ῆς (ἡ)</b> <span>[ᾰ]</span><br><b>   I</b> le sens du toucher, PLAT. <i>Rsp. 523</i> e ; ARSTT. <i>Nic. 3, 10, 9, etc</i>. LUC. <i>Salt. 72 ; etc. ;</i><br><b>   II</b> action de toucher, <i>d’où :</i><br><b>      1</b> toucher, tact, contact, <i>part</i>. action de saisir, <i>en parl. de lutteurs,</i> PLUT. <i>M. 86</i> f ; <i>fig. joint à</i> τόνος, DH. <i>Dem. 18 ; Lys. 13 ; p. ext</i>. poussière propre à faciliter le contact et dont les athlètes une fois oints se frottaient le corps, ARR. <i>Epict. 3, 15, 4 ;</i><br><b>      2</b> coup, blessure, SPT. <i>2Reg. 7, 14 ; 3, 8, 3, etc. ;</i><br><b>      3</b> action de toucher d’un instrument, PLUT. <i>Per. 15 ;</i> DAMOX. (ATH. <i>102</i> e) ;<br><b>   III</b> point de contact, jointure, articulation, ARSTT. <i>Gen. et corr. 1, 8, 24, etc</i>.<br><span><b>Étym</b>. ἅπτω.</span><br>\n② <b>ἁφή, ῆς (ἡ)</b> <span>[ᾰ]</span> action d’allumer : περὶ λύχνων ἁφάς, HDT. <i>7, 215,</i> vers le moment où l’on allume les lampes ; μεχρὶ λύχνων ἁφῶν, ATH. <i>526</i> c, jusqu’à l’heure où l’on allume les lampes ; <i>cf</i>. DH. <i>11, 33 ;</i> DS. <i>19, 31, etc</i>.<br><span><b>Étym</b>. ἅπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφη - ἁφή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G861":"<h1>aphtharsia</h1>\n<p>Strong n° 861 <i>Prononciation [af-thar-see'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>incorruptibilité, perpétuité</li>\n<li>pureté, sincérité, incorruptible</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφθαρσία, ας (ἡ) :<br>      1</b> incorruptibilité, intégrité, SPT. <i>Sap. 2, 23 ;</i><br><b>      2</b> immortalité, EPIC. (DL. <i>10, 76, 123</i>) ; CHRYSIPP. (PLUT. <i>M. 425</i> d) ; PLUT. <i>M. 881</i> b, <i>etc</i>.<br><span><b>Étym</b>. ἄφθαρτος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφθαρσια - ἀφθαρσία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 5 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (4)</li>\n<li>Ephésiens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G862":"<h1>aphthartos</h1>\n<p>Strong n° 862 <i>Prononciation [af'-thar-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>incorruptible, non soumis à corruption ou décadence, impérissable\n<ol type=\"a\">\n<li>choses</li>\n</ol>\n</li>\n<li>immortel\n<ol type=\"a\">\n<li>un mort ressuscité dans la vie éternelle</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄ·φθαρτος, ος, ον :<br>      1</b> non corrompu, non gâté, non endommagé, PHIL. BYZ. <i>Bel. 67</i> d ;<br><b>      2</b> incorruptible, ARSTT. <i>An. pr. 2, 22, 3 ; An. post. 1, 24, 5 ; etc. ; d’où</i> immortel, DH. <i>8, 62 ;</i> LUC. <i>J. tr. 20, etc</i>.<br><span><b>Étym</b>. ἀ, φθείρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-φθαρτος - ἄφθαρτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>1 Timothée (1)</li>\n<li>1 Pierre (3)</li>\n</ul>\n</td></tr>\n</table>","G863":"<h1>aphiemi</h1>\n<p>Strong n° 863 <i>Prononciation [af-ee'-ay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>envoyer au loin, renvoyer, répudier\n<ol type=\"a\">\n<li>s'en aller\n<ol>\n<li>un mari divorçant d'avec sa femme</li>\n</ol>\n</li>\n<li>céder, expirer</li>\n<li>laisser aller, laisser faire, laisser dire\n<ol>\n<li>ne tenir aucun compte de</li>\n<li>laisser, ne pas discuter maintenant\n<ol type=\"a\">\n<li>des enseignants, écrivains, orateurs</li>\n</ol>\n</li>\n<li>omettre, négliger</li>\n</ol>\n</li>\n<li>oublier, remettre une dette</li>\n<li>rendre, ne pas garder plus longtemps</li>\n</ol>\n</li>\n<li>permettre, accorder, donner une chose à quelqu'un</li>\n<li>quitter, laisser quelqu'un\n<ol type=\"a\">\n<li>dans le but d'aller dans un autre lieu</li>\n<li>partir de chez quelqu'un</li>\n<li>partir et laisser à l'abandon</li>\n<li>déserter</li>\n<li>partir en laissant quelqu'un derrière soi</li>\n<li>ne pas prendre quelqu'un comme compagnon</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφ·ίημι</b> <span>(<i>impf</i>. ἀφίην <i>ou</i> ἠφίην, <i>f</i>. ἀφήσω, <i>ao.1</i> ἀφῆκα, <i>ao.2</i> *ἀφῆν, <i>seul. au plur., pf</i>. ἀφεῖκα ; <i>pass</i>. ἀφίεμαι, <i>impf</i>. ἀφιέμην, <i>ou</i> ἠφιέμην, <i>f</i>. ἀφεθήσομαι, <i>ao</i>. ἀφείθην, <i>pf</i>. ἀφεῖμαι, <i>pl.q.pf</i>. ἀφείμην ; <i>v. fin de l’article</i>)</span> <span>[<i>Dans Hom. et les Épq. d’ord</i>. ῐ <i>prés.,</i> ῑ <i>temps à augment ; dans les Att. touj</i>. ῑ]</span><br><b>A <i>tr.</i></b> laisser aller, <i>d’où :</i><br><b>   I</b> lancer, jeter :<br><b>      1</b> <i>au pr</i>. ἀφ. ἔγχος, IL. <i>10, 372 ;</i> βέλος, HDT. <i>9, 18 ;</i> κεραυνόν, IL. <i>8, 133 ;</i> δίσκον, IL. <i>23, 432,</i> lancer une javeline, un trait, la foudre, un disque ; <i>p. anal. en parl. de pers</i>. πόντιον ἀφ. τινά, EUR. <i>Hec. 797,</i> lancer qqn dans la mer ; <i>en parl. d’armées, de troupes,</i> lancer une expédition, HDT. <i>4, 69, etc. ; au pass</i>. être lancé (contre l’ennemi), HDT. <i>6, 112 ; fig</i>. ἑαυτὸν ἐπί <i>ou</i> εἴς τι, PLAT. <i>Rsp. 373</i> d, <i>etc</i>. se lancer dans qqe entreprise, se livrer à qqe occupation ;<br><b>      2</b> <i>en parl. des organes,</i> laisser aller, laisser échapper, projeter, émettre : δάκρυα, ESCHN. <i>75, 23,</i> verser des larmes ; ἔπος, SOPH. <i>O.C. 731, ou</i> φθογγήν, EUR. <i>Hipp. 418,</i> prononcer une parole ; γόους, EUR. <i>El. 59,</i> laisser échapper des gémissements (<i>mais cf. ci-dessous</i>) ; τὸ ὑγρόν, ARSTT. <i>H.A. 1, 1, 13, etc</i>. laisser suinter <i>ou</i> couler un liquide ; παντοδαπὰ χρώματα, PLAT. <i>Lys. 222</i> b, revêtir (<i>litt</i>. produire au dehors) toutes sortes de couleurs ; <i>p. anal</i>. θυμόν, SOPH. <i>Ant. 1088, ou</i> ὀργήν, DÉM. <i>611, 3,</i> donner cours à sa colère ;<br><b>   II</b> lâcher, <i>d’où :</i><br><b>      1</b> rejeter, abandonner : τὰ ὅπλα, PLAT. jeter ses armes ; γυναῖκα, HDT. <i>5, 39,</i> répudier une femme ; υἱόν, ARSTT. <i>Nic. 8, 14, 4,</i> renier un fils ; ξυμμαχίαν, THC. <i>5, 78 ;</i> σπονδάς, THC. <i>5, 115,</i> renoncer à une alliance, à un traité ; γάμους, EUR. <i>Andr. 973,</i> rompre un mariage ;<br><b>      2</b> laisser aller, renvoyer, congédier : τινά, IL. <i>2, 263,</i> qqn ; ζωόν τινα ἀφ. IL. <i>20, 464,</i> renvoyer qqn avec la vie sauve ; ἀφ. ἐλεύθερον, PLAT. <i>Rsp. 591,</i> renvoyer qqn libre ; αὐτόνομον, THC. <i>1, 139,</i> laisser à qqn son indépendance ; ἐς οἴκους, SOPH. <i>O.R. 320,</i> renvoyer dans ses foyers ; <i>en parl. d’armées, de troupes,</i> licencier, congédier, HDT. <i>1, 77, etc. ; au pass</i>. HDT. <i>7, 122 ; part. à Athènes,</i> lever la séance, <i>en parl. du sénat ou des tribunaux (p. opp. à</i> λύειν, <i>en parl. de l’assemblée du peuple</i>) AR. <i>Ach. 173 ; Vesp. 595 ; Eccl. 377 ; avec double rég</i>. ἀφ. τινὰ ἐγκλήματος, φόνου, <i>etc</i>. DÉM. <i>983, 22,</i> décharger qqn d’une accusation, l’absoudre d’un meurtre ; <i>abs</i>. acquitter, absoudre, ANT. <i>115, 10 ; ou avec le dat. de pers. et l’acc. de chose,</i> ἀφ. τινὶ αἰτίην, HDT. <i>6, 30,</i> abandonner l’accusation contre qqn ; ἀφ. τινὶ χιλίας δραχμάς, DÉM. <i>1354, 26,</i> faire remise à qqn de mille drachmes ; <i>cf</i>. CIA. <i>2, 17, A, 25 (378 av. J.C.) ; 2, 811, c, 119 (323 av. J.C.) ; abs</i>. remettre, pardonner : τινί τι, SPT. <i>Gen. 18, 26 ; 50, 17 ; etc</i>. qqe ch. à qqn ;<br><b>      3</b> <i>part</i>. laisser libre, décharger de toute obligation de travail, <i>en parl. d’animaux consacrés</i> (<i>v</i>. ἄφετος) ; <i>d’où</i> consacrer (un animal, une personne, un temple), XÉN. <i>Cyn. 5, 14 ;</i> PLAT. <i>Criti. 116</i> c ;<br><b>      4</b> laisser aller, laisser se répandre <i>ou</i> se perdre : μένος, IL. <i>13, 444,</i> perdre sa force, <i>en parl. d’une javeline ;</i> ὀργήν, ESCHL. <i>Pr. 315,</i> laisser tomber sa colère (<i>cf. ci-dessus</i> A, I, 2) ;<br><b>      5</b> laisser, permettre : ἀφ. πλοῖον κατὰ τὸν ποταμὸν φέρεσθαι, HDT. <i>1, 194,</i> laisser une embarcation aller au courant du fleuve ; <i>fig. avec une prop. inf</i>. ἀφ. τι δημόσιον εἶναι, THC. <i>2, 13,</i> laisser qqe ch. devenir propriété publique ; <i>avec un rég. de pers</i>. ἀφ. τινά <i>et l’inf</i>. HDT. <i>3, 25, etc</i>. ATT. laisser qqn (faire, <i>etc</i>.), permettre à qqn de (faire, <i>etc.) ; postér. en ce sens l’impér. ao.2</i> ἄφες <i>ou</i> ἄφετε, <i>suivi de la 1<sup>e</sup> ou de la 3<sup>e</sup> pers. du. sbj. ao. équivaut à une sorte d’auxiliaire :</i> ἄφες ἐκϐάλω τὸ κάρφος ἀπὸ τοῦ ὀφθαλμοῦ σοῦ, NT. <i>Matth. 7, 6,</i> permets que j’ôte cette poussière de ton œil ; ἄφες ἴδωμεν, NT. <i>Matth. 27, 49,</i> ἄφετε ἴδωμεν, NT. <i>Marc. 15, 36,</i> allons ! voyons (<i>litt</i>. permets, permettez que nous voyions) ; ἄφετε δείξωμεν, ARR. <i>Epict. 1, 9, 15,</i> allons ! montrons (<i>litt</i>. permettez que nous montrions) ; <i>qqf. suivi de</i> ἵνα : ἄφες ἵνα κἀγὼ ταῦτα ὑπολάϐω, ARR. <i>Epict. 4, 13, 19,</i> permets que moi aussi je fasse ces suppositions ;<br><b>      6</b> laisser aller par négligence <i>ou</i> dédain, <i>d’où</i> négliger, HDT. <i>3, 95 ;</i> ATT. ; ἀφ. τὰ θεῖα, SOPH. <i>O.C. 1537,</i> négliger le culte des dieux ; τὸν καιρόν, DÉM. <i>11, 8,</i> laisser se perdre l’occasion ; ἄτιμόν τινα ἀφ. SOPH. <i>O.C. 1279,</i> renvoyer qqn sans égards, outrageusement ; ἔρημον ἀφ. τινά, SOPH. <i>Ant. 887,</i> laisser qqn dans l’isolement, l’abandonner solitaire ;<br><b>B</b> <i>intr. en apparence :</i><br><b>      1</b> partir, se mettre en route pour une expédition, <i>litt</i>. lancer <i>ou</i> mettre en mouvement (στρατόν, ναῦς, une armée, une flotte) HDT. <i>9, 193 ;</i> THC. <i>7, 19 ;</i><br><b>      2</b> négliger, omettre (<i>cf. ci-dessus,</i> A, II, 6) : περί τινος, ARSTT. <i>Metaph. 1, 4, 12,</i> être négligent pour qqe ch. ; <i>avec un inf</i>. ἀφ. ζητεῖν, ARSTT. <i>Metaph. 1, 6, 4,</i> négliger de rechercher ;<br><b><i>Moy</i>. ἀφίεμαι</b> <span>(<i>impf</i>. ἀφιέμην <i>ou</i> ἠφιέμην, <i>f</i>. ἀφήσομαι, <i>ao.2</i> ἀφείμην)</span> laisser aller (qqe ch. de soi) : δειρῆς ἀφ. πήχεε, OD. <i>23, 240,</i> détacher ses deux bras d’autour du cou (de qqn) ; <i>abs</i>. se détacher de ; <i>fig</i>. ἀφ. τοῦ κοινοῦ τῆς σωτηρίας, THC. <i>2, 60,</i> abandonner le salut de l’État ; <i>cf</i>. PLAT. <i>Theæt. 146</i> b, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Conjug. Act. prés. ind</i>. ἀφίημι, -ίης, -ίησι, -ίεμεν, <i>2 pl. inus.,</i> -ιᾶσι ; <i>duel inus. Impér. 2 sg</i>. ἀφίει, AR. <i>Vesp. 428 ; 2 pl</i>. ἀφίετε <span>[ῑ]</span> OD. <i>22, 251. Subj. 2 pl</i>. ἀφιῆτε, XÉN. <i>Hell. 2, 4, 16. Opt. 2 pl</i>. ἀφίοιτε, PLAT. <i>Ap. 29</i> d. <i>Part</i>. ἀφιέντες <span>[ῐ]</span> HH. <i>2, 56 ;</i> PLAT. <i>Leg. 761</i> c ; <i>fém</i>. ἀφιεῖσαι <span>[ῑ]</span> OD. <i>7, 126. — Impf</i>. ἀφίην, <i>d’où 2 pl</i>. ἀφίετε, DÉM. <i>683, 20 (var</i>. ἠφίετε) ; <i>3 pl</i>. ἀφίεσαν, THC. <i>2, 76 ; 3, 111 ; 4, 48 ; 5, 21 ;</i> EUR. <i>Her. 821 ;</i> XÉN. <i>An. 4, 5, 30 ; Cyr. 3, 3, 60 ; Hell. 7, 4, 39 ; etc. Impf. avec augment en</i> η : ἠφίην, PLAT. <i>Euthyd. 293</i> a (<i>vulg</i>. ἠφίειν) ; <i>3 sg</i>. ἠφίει, THC. <i>2, 49 ;</i> PLAT. <i>Lach. 222</i> b ; DÉM. <i>70, 27 ; 2 pl</i>. ἠφίετε, DÉM. (<i>v. ci-dessus) ; 3 pl</i>. ἠφίεσαν, XÉN. <i>Hell. 4, 6, 11 ;</i> DÉM. <i>540, 11 ; 3 pl</i>. ἠφίουν (<i>c</i>. de *ἀφιέω), IS. <i>60, 19, dout. Dans les inscr. att. seul. impf. en</i> ἀφ- (<i>non en</i> ἠφ-) : <i>3 sg</i>. ἀφίει, CIA. <i>2, 306, 15 (287 av. J.C.). — Fut</i>. ἀφήσω. — <i>Ao.1 seul. ind</i>. ἀφῆκα (<i>épq</i>. ἀφέηκα, IL. <i>23, 841</i>), -κας, -κε, -καμεν, -κατε, -καν. — <i>Ao.2 ind. seul. plur. et duel : plur</i>. ἀφεῖμεν, -εῖτε <i>ou</i> -έτε, -εῖσαν <i>ou</i> -έσαν ; <i>duel 3 épq. sans augm</i>. ἀφέτην, IL. <i>11, 642. Impér. 2 sg</i>. ἄφες, ESCHL. <i>Pr. 315 ;</i> AR. <i>Eq. 1159. Sbj</i>. ἀφῶ, -ῇς, -ῇ (<i>3 sg. épq</i>. ἀφέῃ, IL. <i>16, 590</i>), -ῶμεν, <i>2 pl. inus.,</i> -ῶσι ; <i>duel inus. Opt</i>. ἀφείην, IL. <i>3, 317,</i> ATT. ; <i>2 pl</i>. ἀφείητε <i>ou</i> ἀφεῖτε, THC. <i>1, 139 ; 3 pl</i>. ἀφεῖεν, XÉN. <i>Cyr. 1, 4, 11. Inf</i>. ἀφεῖναι, AR. <i>Vesp. 595,</i> PLAT. ANT. <i>Part</i>. ἀφείς, EUR. <i>Alc. 794 ;</i> THC. <i>8, 87. — Pf</i>. ἀφεῖκα, XÉN. <i>An. 2, 3, 13,</i> DÉM. — <i>Pass. f</i>. ἀφεθήσομαι. — <i>Ao</i>. ἀφείθην, EUR. <i>Ph. 1377 ;</i> XÉN. <i>Hell. 5, 4, 23 ;</i> PLAT. ; <i>épq. sans augm</i>. ἀφέθην, BATR. <i>84 ; postér. avec double augm</i>. ἠφείθην, PLUT. <i>Syll. 28 (var</i>. ἀφείθην) ; <i>inf</i>. ἀφεθῆναι, THC. <i>5, 65. — Pf</i>. ἀφεῖμαι ; <i>3 pl. réc. irrég</i>. ἀφέωνται (<i>p</i>. *ἀφεῖνται) NT. <i>Luc. 5, 23 ; 7, 48. Impér. 3 sg</i>. ἀφείσθω, THC. <i>5, 91 ;</i> PLAT. <i>Leg. 764. Inf</i>. ἀφεῖσθαι, PLAT. <i>Leg. 945 ;</i> DÉM. <i>Part</i>. ἀφειμένος, THC. <i>8, 33 ;</i> PLAT. ESCHN. — <i>Pl.q.pf. 3 sg</i>. ἀφεῖτο, PLAT. <i>Criti. 116</i> c. — <i>Moy. prés</i>. ἀφίεμαι, THC. <i>2, 60 ;</i> PLAT. <i>Lach. 184. Opt. 3 pl</i>. ἀφίοιντο, ANT. <i>2, δ, 5. — Impf. 3 sg</i>. ἀφίετο <span>[ῑ]</span> OD. <i>23, 240, ou</i> ἠφίετο, DÉM. <i>25, 47. — Fut</i>. ἀφήσομαι, EUR. <i>Hel. 1629. — Ao.2</i> ἀφείμην, XÉN. <i>Hier. 7, 11. Impér. 2 sg</i>. ἀφοῦ, SOPH. <i>O.R. 1521 ; 2 pl</i>. ἄφεσθε, AR. <i>Eccl. 509. Inf</i>. ἀφέσθαι, ISOCR. <i>Part</i>. ἀφέμενος, PLAT. <i>Rsp. 354 ;</i> ISOCR. — <i>Conjug. ion. en</i> ἀπ- <i>au lieu de</i> ἀφ- : <i>Act. prés. ind. 3 sg</i>. ἀπίει, HDT. <i>2, 96 ; 2 pl</i>. ἀπίεμεν, HDT. <i>2, 17. Impf. 3 sg</i>. ἀπίει, HDT. <i>4, 157 ; 3 pl</i>. ἀπίεσαν, HDT. <i>5, 42 ; 8, 52. Fut</i>. ἀπήσω, HDT. <i>9, 18 ; 7, 193 (var</i>. ἀφήσω). <i>Ao.1</i> ἀπῆκα, HDT. <i>3, 25 et 75 ; 6, 30, etc. Pass. ao.1</i> ἀπείθην, HDT. <i>6, 112 ; 7, 122. Ao.2 part</i>. ἀπείς, HDT. <i>1, 77. — Par except. dans Hom</i>. <span>[ῑ]</span>, <i>comme chez les Att., dans</i> ἀφίετε, <i>v. ci-dessus</i>.<br><span><b>Étym</b>. ἀπό, ἵημι. <i>Cf</i>. ἀφέω <i>et</i> ἀφιέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφιημι - ἀφίημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n147 fois dans 133 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (48)</li>\n<li>Marc (37)</li>\n<li>Luc (33)</li>\n<li>Jean (15)</li>\n<li>Actes (2)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (3)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (1)</li>\n<li>1 Jean (2)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G864":"<h1>aphikneomai</h1>\n<p>Strong n° 864 <i>Prononciation [af-ik-neh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>venir d'un lieu, arriver jusqu'à, parvenir</li>\n<li>venir, arriver</li>\n<li>venir aux oreilles : connu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφ·ικνέομαι-οῦμαι</b> <span>(<i>impf</i>. ἀφικνούμην, <i>f</i>. ἀφίξομαι, <i>ao.2</i> ἀφικόμην <span>[ῑ]</span>, <i>pf</i>. ἀφῖγμαι, <i>pl.q.pf</i>. ἀφίγμην)</span><br><b>   I</b> arriver, <i>d’où :</i><br><b>      1</b> arriver, parvenir, <i>d’où</i> venir, <i>avec l’acc. de lieu,</i> HOM. HÉS. PD. : κλισίην, IL. <i>11, 618 ;</i> νῆας, IL. <i>17, 454,</i> à la tente, aux vaisseaux ; <i>de même avec un acc. de pers</i>. μνηστῆρας, OD. <i>1, 332,</i> arriver parmi les prétendants ; <i>rar. avec</i> εἰς, IL. <i>24, 431 ;</i> OD. <i>4, 255 ; avec</i> ἐπί, IL. <i>10, 281 ; 22, 208 ; avec</i> ποτί, OD. <i>6, 297 ; avec</i> κατά, IL. <i>13, 329 ; avec</i> ὑπό, OD. <i>20, 81 ; avec le rég. du lieu d’où l’on vient :</i> ἀφ. παρά τινος, SOPH. <i>O.R. 935,</i> arriver d’auprès de qqn ; <i>avec double rég. :</i> ἀφ. τινι ἐς λόγους, HDT. <i>2, 28,</i> entrer en conversation avec qqn ; διὰ λόγων ἑαυτῷ ἀφ. EUR. <i>Med. 872,</i> converser avec soi-même, <i>càd</i>. réfléchir en soi-même ; διὰ μάχης ἀφ. τινι, HDT. <i>1, 169,</i> engager un combat avec qqn ; <i>avec un suj. de chose</i> (navire, cargaison, <i>etc</i>.) XÉN. PLAT. ; <i>fig</i>. μ' ἄλγος ἀφίκετο, IL. <i>18, 395,</i> une douleur est venue m’atteindre ;<br><b>      2</b> parvenir à, en venir à, <i>en parl. d’une condition, d’un état de l’esprit, d’une disposition de l’âme, etc. ;</i> ἀφ. εἰς τὸ ἴσον τινί, XÉN. <i>Cyr. 1, 4, 5,</i> parvenir à égaler qqn ; εἰς ἀπορίαν, PLAT. ; ἐς ἀπορίην, HDT. <i>1, 79,</i> en arriver à être sans ressources ; ἐς τοσοῦτον τύχης, HDT. <i>1, 124 ;</i> ἐς τοῦτο δυστυχίας, THC. <i>7, 86,</i> en venir à ce degré de fortune, d’infortune, <i>etc. ;</i> εἰς ἀθυμίαν, EUR. en arriver au découragement ; <i>avec double rég</i>. ἐς ἔχθος ἀπικέσθαι τινί, HDT. <i>ou</i> δι' ἔχθρας ἀφ. τινί, EUR. <i>Hipp. 1164,</i> en venir à des sentiments d’hostilité pour qqn ; <i>avec un inf</i>. ἐς ὀλίγον ἀφίκετο τὸ στράτευμα νικηθῆναι, THC. <i>4, 129,</i> il s’en fallut de peu que l’armée ne finît par être vaincue ;<br><b>   II</b> revenir, retourner, OD. <i>10, 420 ;</i> EUR. <i>El. 6 ;</i> PLAT. <i>Charm. 153</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. 2 sg. épq</i>. ἀφίξεαι, OD. <i>12, 39. ao.2</i> ἀφικόμην, <i>p. except. avec</i> <span>[ῐ]</span>, PD. <i>O. 9, 67 ; impér. 2 sg</i>. ἀφίκεο, OD. <i>1, 171 ; impér. dor</i>. ἀφίκευσο, THCR. <i>Idyl. 11, 42 (vulg</i>. ἀφίκευ τύ). — <i>Conjug. ion. prés</i>. ἀπικνέομαι, HDT. <i>2, 41, etc. Impf. 3 pl</i>. ἀπικνέοντο, HDT. <i>4, 125. Fut</i>. ἀπίξομαι, HDT. <i>2, 29 (cf. éol. 3 sg</i>. ἀπίξεται, THCR. <i>Idyl. 29, 13). Ao.2</i> ἀπικόμην, HDT. <i>2, 44 ; 8, 8 ; 2 sg</i>. ἀπίκευ, HDT. <i>1, 124 ; 3 pl</i>. ἀπικέατο, HDT. <i>1, 15, 169. Pf. 3 sg</i>. ἀπῖκται, HDT. <i>1, 193. Pl.q.pf. 3 pl</i>. ἀπίκατο, HDT. <i>8, 6, et</i> ἀπιγμένοι ἦσαν, HDT. <i>9, 118</i>.<br><span><b>Étym</b>. ἀπό, ἱκνέομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφ-ικνεομαι - ἀφικνέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G865":"<h1>aphilagathos</h1>\n<p>Strong n° 865 <i>Prononciation [af-il-ag'-ath-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>opposé à la bonté et aux hommes bons, qui n'aime pas le bien</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀ·φιλάγαθος, ος, ον</b> <span>[ῐᾰᾰ]</span> qui n’aime pas le bien <i>ou</i> les gens de bien, NT. <i>2Tim. 3, 3</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-φιλ-αγαθος - ἀφιλάγαθος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G866":"<h1>aphilarguros</h1>\n<p>Strong n° 866 <i>Prononciation [af-il-ar'-goo-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>non attiré par l'argent, sans avarice</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀ·φιλάργυρος, ος, ον</b> <span>[ῐῠ]</span> qui n’aime pas l’argent, exempt d’avarice <i>ou</i> de cupidité, NT. <i>1Tim. 3, 3 ; Hebr. 13, 5</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-φιλ-αργυρος - ἀφιλάργυρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G867":"<h1>aphixis</h1>\n<p>Strong n° 867 <i>Prononciation [af'-ix-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>arrivée</li>\n<li>départ</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄφιξις, εως (ἡ) :<br>      1</b> arrivée, HDT. <i>1, 69 ; 3, 145 ;</i> LYS. <i>193, 9, etc. ; part</i>. retour (chez soi) DÉM. <i>1463, 6 ; 1484, 7 ;</i><br><b>      2</b> action d’aller ; παρά τινα, HDT. <i>3, 69 ou</i> εἴς τινα, DÉM. <i>58 fin,</i> auprès de qqn ; ἐς τόπον, HDT. <i>9, 17 ou</i> ἐπὶ τόπον, HDT. <i>7, 58,</i> dans un lieu ; <i>d’où abs</i>. départ, NT. <i>Ap. 20, 29 ;</i><br><b>      3</b> supplication, <i>c</i>. ἱκεσία, ESCHL. <i>Suppl. 483</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἄπιξις, HDT. <i>ll. cc. ; gén</i>. ἀπίξιος, HDT. <i>3, 69</i>.<br><span><b>Étym</b>. ἀφικνέομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφ-ιξις - ἄφιξις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G868":"<h1>aphistemi</h1>\n<p>Strong n° 868 <i>Prononciation [af-is'-tay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se retirer, enlever\n<ol type=\"a\">\n<li>exciter à la révolte</li>\n</ol>\n</li>\n<li>s'éloigner\n<ol type=\"a\">\n<li>partir, quitter</li>\n<li>déserter</li>\n<li>chuter, devenir infidèle</li>\n<li>fuir, s'enfuir</li>\n<li>cesser des vexations</li>\n<li>s'absenter</li>\n<li>abandonner, succomber</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφ·ίστημι :<br>   I</b> <i>tr. aux temps suiv. (prés., impf</i>. ἀφίστην, <i>f</i>. ἀποστήσω, <i>ao.1</i> ἀπέστησα) placer hors de, <i>d’où :</i><br><b>      1</b> éloigner, écarter : τινά, XÉN. <i>Hell. 7, 5, 23,</i> qqn ; ἀπ. ἀλλήλων, PLAT. <i>Pol. 282</i> b, éloigner les uns des autres ;<br><b>      2</b> séparer, détacher : ἀφ. τῆς ἐλάας τὸν φλοιόν, TH. <i>C.P. 3, 3, 2,</i> enlever l’écorce de l’olivier ; <i>fig</i>. détacher (d’une alliance, d’un parti) : ἀφ. τοὺς ξυμμάχους, THC. ; τὴν Ἰωνίαν, THC. pousser les alliés, l’Ionie à la défection, à la révolte ; τινὰ ἀπό τινος, HDT. <i>1, 76, etc. ;</i> τινά τινος, AND. <i>26, 16,</i> chercher à détacher qqn d’un parti ;<br><b>      3</b> écarter, éloigner, <i>d’où</i> faire disparaître : ἄχος, ESCHL. <i>Ch. 416,</i> éloigner une douleur ; νόσον, CALL. DIOSC. guérir une maladie ; ἐπιϐουλάς, THC. déjouer des complots <i>ou</i> des desseins hostiles ; <i>en parl. de pers</i>. ἄρχοντα, XÉN. <i>Hell. 7, 1, 45,</i> déposer un magistrat, <i>litt</i>. l’écarter de sa charge ; <i>abs</i>. supprimer une dette, <i>càd</i>. l’acquitter, XÉN. <i>Conv. 2, 20 ;</i><br><b>   II</b> <i>intr. aux temps suiv. (ao.2</i> ἀπέστην, <i>pf</i>. ἀφέστηκα <i>au sens d’un prés., pl.q.pf</i>. ἀφεστήκη <i>ou</i> -κειν <i>au sens d’un impf</i>.) être éloigné : δοῦλος ἀφεστώς, LYS. <i>167, 12,</i> esclave fugitif ; <i>fig. :</i><br><b>      1</b> être séparé, <i>d’où</i> être privé de : ἀφ. φρενῶν, SOPH. <i>Ph. 865,</i> avoir perdu la raison ;<br><b>      2</b> être différent de : τῶν τοιούτων ἐθῶν, DÉM. être éloigné de pareilles coutumes ; πόρρω ἀφέστηκε βασιλεὺς τυράννου, PLAT. un roi est fort différent d’un tyran ;<br><b>   III</b> s’éloigner, se retirer (de crainte, d’horreur, <i>etc</i>.) IL. <i>4, 340, etc</i>. PLAT. <i>Theæt. 169</i> b ; DÉM. <i>355, 20, etc. ; fig. :</i><br><b>      1</b> s’abstenir de, renoncer à, <i>avec le gén</i>. ἀφ. τοῦ ποιεῖν, POL. <i>ou avec l’inf</i>. EUR. <i>Hel. 536,</i> renoncer à faire, <i>etc. ;</i><br><b>      2</b> se dérober à, se soustraire à, <i>gén. :</i> πόνων καὶ κινδύνων, ISOCR. <i>57</i> c, se soustraire aux fatigues et aux dangers ;<br><b>      3</b> se détacher de, faire défection : ἀπό τινος, HDT. <i>1, 95, etc. (cf</i>. CIA. <i>4, 27, a, 21, de 445 av. J.C</i>.) ; τινός, HDT. <i>2, 113 (cf</i>. CIA. <i>1, 9, 22, de 464/457 av. J.C</i>.), se détacher du parti de qqn ; ἀφ. πρός <i>ou</i> εἴς τινα, HDT. <i>2, 30 ;</i> XÉN. <i>An. 1, 6, 7,</i> faire défection pour se rallier à qqn ; <i>abs</i>. faire défection, se révolter, HDT. <i>1, 102 ;</i> ἀφ. ὑπό τινος, THC. <i>8, 35,</i> faire défection à l’instigation de qqn ;<br><b><i>Moy</i>. ἀφίσταμαι</b> <span>(<i>f</i>. ἀποστήσομαι, <i>ao</i>. ἀπεστησάμην)</span><br><b>   I</b> <i>tr. (seul. ao</i>.) :<br><b>      1</b> éloigner, écarter de soi : Ἀργείων δόρυ πυλῶν ἀφ. EUR. <i>Ph. 1087,</i> écarter de ses portes la lance des Argiens ;<br><b>      2</b> se dégager de, s’acquitter de : χρεῖος, IL. <i>13, 745,</i> s’acquitter d’une dette, <i>càd</i>. rendre le mal pour le mal ; τὸν χαλκόν, DÉM. <i>1199, 14,</i> payer la solde <i>ou</i> le salaire ;<br><b>   II <i>intr</i>.<br>      1</b> être éloigné <i>ou</i> distant de, <i>gén</i>. IL. <i>23, 517 ;</i> OD. <i>23, 101, etc. ;</i><br><b>      2</b> s’écarter de, s’éloigner de : ἐκ Σικελίας, THC. <i>7, 28,</i> s’éloigner de la Sicile ; <i>rar. avec l’acc. :</i> ἀφ. τὸν ἥλιον ὑπὸ τῆς σκιᾶς, XÉN. <i>Cyn. 3, 3,</i> se retirer du soleil pour s’abriter à l’ombre ; <i>part</i>. faire défection : πρός τινα, XÉN. pour passer dans le parti d’un autre ;<br><b>      3</b> <i>t. de méd</i>. s’écarter, se désagréger : ἀφίσταται ὀστέον, HPC. <i>Aph. 1258,</i> l’os est carié ; σάρκες ἀφιστάμεναι, DIOSC. chairs qui se dissolvent ; τὸ ἀφιστάμενον, GAL. abcès en formation ; τὰ ἀφεστεῶτα, GAL. abcès formés.<br><span><b><span class=\"arrow\"></span></b> <i>ao.2 impér</i>. ἀπόστηθι, AR. <i>Th. 627 ; ou</i> ἀπόστα, MÉN. <i>4, 182 Meineke. Pf</i>. ἀφέστηκα, ας, ε ; <i>plur</i>. ἀφέσταμεν <span>[τᾰ]</span>, -στατε <span>[τᾰ]</span>, -στᾶσι ; <i>opt. poét. 3 sg</i>. ἀφεσταίη, OD. <i>23, 101, 169 ; inf</i>. ἀφεστηκέναι, ARSTT. <i>Aud. 20, ou</i> ἀφεστάναι ; <i>part</i>. ἀφεστώς, -ῶσα, -ός <i>ou</i> -ώς ; <i>part. épq. plur</i>. ἀφεσταότες, IL. <i>17, 375. Pl.q.pf. 1 sg</i>. ἀφεστήκη, PLAT. <i>Theæt. 208</i> e ; <i>3 sg</i>. ἀφεστήκει, OD. <i>11, 544 ; 3 pl</i>. ἀφέστασαν <span>[τᾰ]</span> (<i>cf. le plur. du pf</i>. ἀφέστηκα) IL. <i>15, 672 ; 21, 391. Fut</i>. ἀφεστήξω <i>formé du pf</i>. ἀφέστηκα (<i>cf</i>. τεθνήξω) XÉN. <i>An. 2, 4, 5 ;</i> PLAT. <i>Rsp. 587</i> b. — <i>Conjug. ion. et dor. en</i> ἀπ- <i>au lieu de</i> ἀφ- : <i>ao.1 dor</i>. ἀπέστασα <span>[τᾱ]</span> ESCHL. <i>Ch. 416 (chœur) ; ao.2, 3 pl. sbj. ion</i>. ἀποστέωσι, HDT. <i>3, 15 ; pl.q.pf. 3 sg. ion</i>. ἀπεστήκεε, HDT. <i>5, 37</i>.<br><span><b>Étym</b>. ἀπό, ἵστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφ-ιστημι - ἀφίστημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 6 livres bibliques (NT)\n<ul>\n<li>Luc (4)</li>\n<li>Actes (6)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G869":"<h1>aphno</h1>\n<p>Strong n° 869 <i>Prononciation [af'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>soudainement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄφνω</b>, <i>adv</i>., soudain, tout à coup, ESCHL. <i>fr. 195 ;</i> EUR. <i>Med. 1205 ;</i> ALC. <i>420, etc. ; en prose,</i> THC. <i>4, 104 ;</i> DÉM. <i>527, 16</i>.<br><span><b>Étym</b>. <i>cf</i>. αἴφνης <i>et</i> ἄφνως.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφνω - ἄφνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G870":"<h1>aphobos</h1>\n<p>Strong n° 870 <i>Prononciation [af-ob'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans crainte, hardiment, avec audace, impudemment, sans peur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφόϐως</b>, <i>adv</i>., sans crainte, XÉN. <i>Hier. 7, 10 ;</i> PLAT. <i>Leg. 682</i> c, <i>etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-φοβως - ἀφόβως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G871":"<h1>aphomoioo</h1>\n<p>Strong n° 871 <i>Prononciation [af-om-oy-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire qu'un modèle se retrouve dans une image ou une forme semblable, comparable, être assimilé</li>\n<li>copier</li>\n<li>produire un fac-similé</li>\n<li>être rendu semblable, rendre similaire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφομοιόω-ῶ</b> <span>(<i>impf</i>. ἀφωμοίουν ; <i>pass. ao</i>. ἀφωμοιώθην, <i>pf</i>. ἀφωμοίωμαι)</span><br><b>      1</b> rendre semblable <i>ou</i> conforme : τινί τι, XÉN. <i>Eq. 9, 9 ;</i> PLAT. <i>Crat. 427</i> c ; ARSTT. <i>Pol. 1, 2, 7,</i> une chose à une autre ; τινί τινα, PLAT. <i>Rsp. 396</i> a, une personne à une autre ; <i>d’où au pass</i>. être rendu <i>ou</i> devenir semblable : τινι, PLAT. <i>Rsp. 396</i> b ; <i>500</i> c, <i>etc. ou</i> πρός τι, PLAT. <i>Soph. 240</i> a, à qqe ch. ;<br><b>      2</b> faire à l’imitation de, reproduire, copier (un portrait, <i>etc</i>.) XÉN. <i>Mem. 3, 10, 2 ;</i> PLAT. <i>Crat. 424</i> d ;<br><b>      3</b> assimiler, comparer : τινί τι, PLAT. <i>Rsp. 517</i> b ; <i>564</i> a, une chose à une autre.<br><span><b>Étym</b>. ἀπό, ὁμοιόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφ-ομοιοω - ἀφομοιόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G872":"<h1>aphorao</h1>\n<p>Strong n° 872 <i>Prononciation [af-or-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tourner les yeux vers quelque chose, fixer les yeux sur quelque chose, voir nettement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφ·οράω-ῶ</b> <span>(<i>impf</i>. ἀφεώρων, <i>f</i>. ἀπόψομαι, <i>ao.2</i> ἀπεῖδον, <i>pf</i>. ἀφεώρακα)</span><br><b>      1</b> regarder de loin, HDT. <i>4, 22 ;</i> TIMOCL. (ATH. <i>407</i> e) ; TH. <i>H.P. 4, 4, 8, etc. ;</i><br><b>      2</b> fixer les yeux de différents points sur une même chose, <i>d’où</i> avoir en plein sous les yeux, <i>acc</i>. HDT. <i>8, 37 ; p. suite,</i> fixer les yeux sur, contempler, regarder : τι, DÉM. <i>1472, 15 ;</i> πρός τι, THC. <i>7, 71 ;</i> PLAT. <i>Phil. 17</i> c ; <i>Rsp. 585</i> a ; PLUT. <i>M. 116</i> d, <i>227</i> f ; εἴς τι, PLUT. <i>Lyc. 7,</i> qqe ch. ; πρός τινα, PLUT. <i>M. 119</i> c, <i>181</i> e ; <i>etc. ;</i> εἴς τινα, LUC. <i>Philops. 30 ;</i> ἐπί τινα, PLUT. <i>Cato mi. 50,</i> fixer les yeux sur qqn ;<br><b>      3</b> détourner les yeux, <i>p. suite,</i> se détourner, <i>d’où</i> avoir le dos tourné, XÉN. <i>Cyr. 7, 1, 36 ;</i><br><b><i>Moy.</i></b> regarder <i>ou</i> observer de loin, <i>acc</i>. AR. <i>Nub. 281</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἀπορέω, <i>d’où impf</i>. ἀπώρεον, HDT. <i>8, 37</i>.<br><span><b>Étym</b>. ἀπό, ὁράω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφ-οραω - ἀφοράω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Philippiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G873":"<h1>aphorizo</h1>\n<p>Strong n° 873 <i>Prononciation [af-or-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se démarquer des autres par des frontières, limiter, séparer\n<ol type=\"a\">\n<li>mauvais sens : exclure comme déshonorant</li>\n<li>bon sens : désigner, mettre à part pour un but</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφ·ορίζω</b> <span>(<i>f</i>. ιῶ, <i>ao</i>. ἀφώρισα ; <i>pass. ao</i>. ἀφωρίσθην, <i>pf</i>. ἀφώρισμαι)</span><br><b>   I</b> séparer par une limite, <i>d’où :</i><br><b>      1</b> délimiter : χώραν, PLAT. ISOCR. <i>etc</i>. un pays ; οὐσία ἀφωρισμένη, DÉM. <i>1202, 21,</i> propriété limitée par des bornes, <i>càd</i>. grevée d’hypothèques ;<br><b>      2</b> border, <i>d’où</i> avoir pour limite : τὸν Ἀσωπόν, PLAT. <i>Criti. 110</i> e, l’Asôpos ;<br><b>      3</b> assigner une limite, <i>d’où</i> délimiter, circonscrire, marquer avec précision : ἐπιστήμη ἀφωρισμένη, ARSTT. <i>Rhet. 1, 1, 1,</i> science exactement délimitée ; ἀφωρισμένα, ARSTT. <i>Rhet. 1, 1, 7,</i> cas déterminés ; χρόνος ἀφωρισμένος, PLAT. <i>Leg. 785</i> b, temps déterminé, limite de temps marquée avec précision ; <i>abs</i>. déterminer rigoureusement une proposition, <i>d’où</i> exprimer sous une forme concise, <i>part</i>. sous forme d’un aphorisme, SYN. <i>255</i> b ;<br><b>      4</b> <i>p. suite,</i> définir, déterminer : τέχνην, PLAT. <i>Soph. 240</i> c, définir un art ; τί ἐστιν ἡ σωφροσύνη, ARSTT. définir ce qu’est la tempérance ;<br><b>      5</b> mener à terme (un ouvrage) POL. <i>2, 71, 10 ;</i><br><b>   II</b> <i>p. suite,</i> séparer, <i>d’où :</i><br><b>      1</b> séparer, distinguer, PLAT. <i>Rsp. 501</i> d, <i>etc. ;</i> ἀφ. χωρίς, ARSTT. <i>Pol. 7, 12, 2,</i> mettre à part ; ἀφ. τί τινος, PLAT. <i>Hipp. ma. 298</i> d, <i>ou</i> τὶ ἀπό τινος, DC. <i>36, 25,</i> séparer <i>ou</i> distinguer une chose d’une autre ;<br><b>      2</b> mettre à part, <i>d’où</i> désigner spécialement, NT. <i>Ap. 13, 2, Rom. 1, 1, etc. ;</i> πρός τι, ARSTT. <i>Pol. 6, 8, 20,</i> pour qqe office ;<br><b>      3</b> exclure, chasser : τινὰ ἀπὸ γᾶς, EUR. <i>Hec. 940,</i> bannir qqn ; <i>part</i>. excommunier, NT. <i>Luc. 6, 22 ;</i> ECCL. ;<br><b><i>Moy.</i></b> <span>(<i>ao</i>. ἀφωρισάμην)</span><br><b>   I</b> délimiter :<br><b>      1</b> délimiter (pour soi) : χώραν, ISOCR. <i>106</i> d, un pays, <i>càd</i>. se l’approprier ;<br><b>      2</b> définir, donner une définition : τι, PLAT. <i>Parm. 133</i> d, <i>ou</i> περί τινος, PLAT. <i>Charm. 173</i> e, <i>etc</i>. de qqe ch. ;<br><b>      3</b> mener à terme, terminer : λόγον, ISOCR. son discours ;<br><b>   II</b> <i>p. suite :</i><br><b>      1</b> écarter de soi : τέχνην ἐριστικήν, PLAT. <i>Soph. 231</i> e, l’art de la controverse, <i>càd</i>. y demeurer étranger ;<br><b>      2</b> écarter : τιμάς τινος, EUR. <i>Alc. 31,</i> refuser à qqn des honneurs.<br><span><b>Étym</b>. ἀπό, ὁρίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφ-οριζω - ἀφορίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 9 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (1)</li>\n<li>Actes (3)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (2)</li>\n</ul>\n</td></tr>\n</table>","G874":"<h1>aphorme</h1>\n<p>Strong n° 874 <i>Prononciation [af-or-may']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>lieu d'où un mouvement d'attaque se produit, base d'opérations</li>\n<li>métaph : ce que nous mettons en avant pour réaliser ou non quelque chose</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφορμή, ῆς (ἡ)</b> point d’où l’on s’élance, point de départ, <i>d’où :</i><br><b>   I</b> base d’opérations militaires, THC. <i>1, 90 ;</i> POL. <i>1, 41, 6 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> origine, principe (d’une maladie) HPC. <i>1009</i> h ;<br><b>      2</b> cause, occasion, prétexte : ἀφορμὴν ἔχειν πρός <i>ou</i> εἴς τι, POL. avoir une occasion <i>ou</i> un prétexte pour qqe ch. ; λαϐεῖν ἀφ. τινα, ISOCR. <i>53</i> a, saisir une occasion <i>ou</i> un prétexte ; ἀφορμὴν παρέχειν, DÉM. <i>270, 27 ; 279, 26 ; ou</i> διδόναι, DÉM. <i>546, 19,</i> fournir <i>ou</i> donner une occasion <i>ou</i> un prétexte ; <i>joint à</i> πρόφασις, POL. <i>2, 52, 3 ; 2, 59, 9 ; 5, 41, 5 ;</i><br><b>      3</b> moyen d’entreprendre qqe ch., <i>d’où</i> ressources : αἱ ἀφορμαὶ ἐκ τῶν τόπων, POL. les ressources qu’offre un terrain (pour une opération de guerre) ; <i>part</i>. ressources de guerre (en hommes, en vaisseaux, en argent) : ἀφορμὴ εἰς ξένους χίλιους, XÉN. <i>Hell. 4, 8, 33,</i> contingent auxiliaire de 1 000 étrangers ; ressources pour vivre (argent, fonds, capital), XÉN. <i>Mem. 2, 7, 12 ; 3, 12, 4 ; etc. ;</i> LYS. <i>170, 27 (au plur</i>.) ; DÉM. <i>48, 7 ; 477, 20 ; au plur. 305, 7 ; etc. ;</i> ἀφορμῆς δίκη, DÉM. procès en restitution de capital ;<br><b>   III</b> <i>t. stoïc</i>. répugnance, aversion, <i>p. opp. à</i> ὁρμή, PLUT. <i>M. 1037</i> f ; DL. <i>7, 104</i>.<br><span><b>Étym</b>. ἀπό, ὁρμή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφ-ορμη - ἀφορμή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G875":"<h1>aphrizo</h1>\n<p>Strong n° 875 <i>Prononciation [af-rid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>écumer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφρίζω</b> <span>(<i>f</i>. ίσω)</span> écumer, SOPH. <i>El. 719 ;</i> HPC. <i>645, 2 ; en parl. d’une coupe de vin,</i> ANTIPH. <i>et</i> ALEX. (ATH. <i>471</i> c <i>et 472</i> a) ; TH. DS.<br><span><b>Étym</b>. ἀφρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφριζω - ἀφρίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Marc (2)</li>\n</ul>\n</td></tr>\n</table>","G876":"<h1>aphros</h1>\n<p>Strong n° 876 <i>Prononciation [af-ros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>écume</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφρός, οῦ (ὁ) :<br>      1</b> écume, <i>en parl. de la mer,</i> IL. <i>18, 403 ; d’une rivière,</i> IL. <i>5, 599 ; du vin,</i> TIMOTH. <i>et</i> ANTIPH. (ATH. <i>465</i> c ; <i>781</i> e) ; <i>du sang,</i> ESCHL. <i>Eum. 183 ; de l’écume de la bouche chez un lion,</i> IL. <i>20, 168 ; chez l’homme,</i> HPC. <i>250, 54 ; 303, 13 ;</i> EUR. <i>Med. 1174 ;</i> LUC. <i>Alex. 12, etc. ;</i><br><b>      2</b> ἀφρὸς νίτρου, TH. <i>fr. 20, 21 ;</i> GAL. <i>10, 191, c</i>. ἀφρόνιτρον ;<br><b>      3</b> <i>sorte de</i> loche de mer, <i>c</i>. ἀφύη, ARCHESTR. (ATH. <i>285</i> d ; <i>325</i> b) ; ARSTT. <i>H.A. 6, 15, 4, etc</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφρος - ἀφρός</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G877":"<h1>aphrosune</h1>\n<p>Strong n° 877 <i>Prononciation [af-ros-oo'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sottise, folie, insensé, stupide, dépourvu d'intelligence</li>\n<li>insouciance, témérité</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφροσύνη, ης (ἡ)</b> <span>[αῠ]</span> démence, folie, IL. <i>7, 110 ;</i> HDT. <i>3, 146 ;</i> THC. <i>1, 122 ;</i> XÉN. <i>etc. ; p. opp. à</i> σωφροσύνη <i>ou à</i> σοφία, PLAT. <i>Prot. 332</i> e ; <i>au pl</i>. actes de folie, paroles <i>ou</i> actions déraisonnables, OD. <i>16, 278 ; 24, 457 (gén. épq</i>. ἀφροσυνάων) ; SOPH. <i>O.C. 1230</i>.<br><span><b>Étym</b>. ἄφρων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-φροσυνη - ἀφροσύνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>2 Corinthiens (3)</li>\n</ul>\n</td></tr>\n</table>","G878":"<h1>aphron</h1>\n<p>Strong n° 878 <i>Prononciation [af'-rone]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sans raison</li>\n<li>insensé, sot, stupide</li>\n<li>sans réflexion ou intelligence, agissant d'une façon téméraire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄ·φρων, ων, ον</b>, <i>gén</i>. <b>ονος :<br>   I</b> privé de sentiment, <i>en parl. d’une statue,</i> XÉN. <i>Mem. 1, 4, 4 ;</i><br><b>   II</b> qui a perdu la raison, <i>d’où :</i><br><b>      1</b> furieux, fou, IL. <i>5, 875 ;</i> ESCHL. <i>Eum. 377 ;</i> SOPH. <i>El. 941 ;</i><br><b>      2</b> insensé, déraisonnable, IL. <i>3, 220 ;</i> HÉS. <i>O. 208 ; p. opp. à</i> σώφρων, XÉN. <i>Cyr. 3, 1, 17, ou à</i> ἐπίφρων, OD. <i>23, 12 ;</i> τὸ ἄφρον, THC. <i>5, 105 ;</i> XÉN. <i>Mem. 1, 2, 55,</i> démence, folie.<br><span>•<i> Cp</i>. ἀφρονέστερος, PLAT. <i>Crat. 392</i> c ; PHIL. <i>47</i> b, <i>etc.</i> <i>• Sup</i>. ἀφρονέστατος, XÉN. <i>Mem. 2, 1, 5 ;</i> PLAT. <i>Leg. 630</i> b ; <i>etc</i>.<br><span><b>Étym</b>. ἀ, φρήν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφρων - ἄφρων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 10 versets de 6 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (5)</li>\n<li>Ephésiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G879":"<h1>aphupnoo</h1>\n<p>Strong n° 879 <i>Prononciation [af-oop-no'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se réveiller d'un sommeil</li>\n<li>tomber de sommeil, s'endormir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀφ·υπνόω-ῶ</b>, <i>f</i>. ώσω :<br><b>      1</b> s’éveiller, ANTH. <i>9, 517 ;</i><br><b>      2</b> s’endormir, NT. <i>Luc. 8, 23 ;</i> A. DIOG. <i>9 ;</i><br><b><i>Moy.</i></b> s’endormir, HLD. <i>9, 12 (var</i>. ὑφυπν.).<br><span><b>Étym</b>. ἀπό, ὑπνόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αφυπνοω - ἀφυπνόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G880":"<h1>aphonos</h1>\n<p>Strong n° 880 <i>Prononciation [af'-o-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sans voix, muet</li>\n<li>sans la faculté de la parole\n<ol type=\"a\">\n<li>les idoles</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄ·φωνος, ος, ον :<br>   I</b> sans voix, <i>càd. :</i><br><b>      1</b> impuissant à parler, atteint d’aphonie, HPC. <i>Epid. 3, 1098 ;</i><br><b>      2</b> muet, silencieux, THGN. <i>669 ;</i> HDT. <i>1, 85 ;</i> DÉM. <i>292, 6 ;</i> ἄφ. ἀρᾶς, SOPH. <i>O.C. 865,</i> incapable de prononcer une imprécation ; <i>adv</i>., ἄφωνα, ESCHL. <i>Pers. 819,</i> sans parler ;<br><b>   II</b> <i>subst</i>. τὰ ἄφωνα :<br><b>      1</b> les sons muets, <i>càd</i>. les consonnes, <i>p. opp. aux voyelles</i> (φωνοῦντα <i>ou</i> φωνήεντα) EUR. <i>fr. 582 ;</i> PLAT. <i>Crat. 393</i> b ;<br><b>      2</b> <i>p.-ê</i>. les sons demi-muets, <i>càd</i>. les semi-voyelles, <i>p. opp. à</i> ἄφθογγα, PLAT. <i>Phil. 18</i> c ;<br><b>      3</b> <i>part</i>. les consonnes muettes (gutturales, dentales, labiales), D. THR. DH. DL. <i>etc</i>.<br><span><b>Étym</b>. ἀ, φωνή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-φωνος - ἄφωνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G881":"<h1>Achaz</h1>\n<p>Strong n° 881 <i>Prononciation [akh-adz']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Achaz (Angl. Ahaz) = « possesseur », « il tient »\n<ol><li>le onzième roi de Juda, fils de Jotham</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αχαζ</font> &lt; אחז - <font face=\"Georgia\">Ἀχάζ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G882":"<h1>Achaia</h1>\n<p>Strong n° 882 <i>Prononciation [ach-ah-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Achaïe (Angl. Achaia) = « trouble »\n<ol>\n<li>sens restrictif : la région maritime du nord du Péloponèse</li>\n<li>sens plus large : province Romaine incluant toute la Grèce sauf la Thessalie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀχαΐα, ας</b>, <i>contract. de</i> <b>Ἀχαιΐα, ας (ἡ)</b> <span>[ᾰᾱι]</span> l’Achaïe :<br><b>      1</b> <i>contrée du Péloponnèse,</i> THC. <i>1, 115, etc. ;</i> XÉN. <i>Hell. 6, 2, 3, etc. ; d’où</i> le Péloponnèse entier, DH. <i>1, 25 ;</i><br><b>      2</b> <i>partie de la Thessalie, appelée aussi Phthiotide,</i> HDT. <i>7, 173 ;</i> DS. DH. STR. ;<br><b>      3</b> <i>la province romaine d’Achaïe, càd. la Grèce sans la Macédoine,</i> STR. PLUT. JOS. DC. ;<br><b>      4</b> <i>régions ou villes diverses (du Pont, de Syrie, etc</i>.) STR. ARR. APP. <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. Ἀχαΐη, ANACR. <i>32</i>. Ἀχαιΐα, PAUS. <i>5, 8, 9 ;</i> E. BYZ. ; CIA. <i>2, 966, 48, 50, 54 (peu après 191 av. J.C.) ; ion</i>. Ἀχαιΐη, HDT. <i>8, 36</i>.<br><span><b>Étym</b>. Ἀχαιός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αχαια - Ἀχαΐα</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 5 livres bibliques (NT)\n<ul>\n<li>Actes (3)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (3)</li>\n<li>1 Thessaloniciens (2)</li>\n</ul>\n</td></tr>\n</table>","G883":"<h1>Achaikos</h1>\n<p>Strong n° 883 <i>Prononciation [ach-ah-ee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Achaïcus (Angl. Achaicus) = « originaire de l'Achaïe »\n<ol><li>nom d'un chrétien de Corinthe</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀχαϊκός, ή, όν</b> <span>[ᾰᾱ]</span> d’Achaïe, achéen, <i>càd</i>. thessalien, péloponnésien <i>ou</i> grec, IL. <i>13, 349 ; 15, 218 ;</i> HDT. <i>8, 73 ;</i> ESCHL. EUR. XÉN. PLUT. <i>etc. ; en parl. d’Argos,</i> IL. <i>9, 141 ; 19, 115 ;</i> OD. <i>3, 251 ;</i> ὁ Ἀχ., PLUT. <i>Mar. 1,</i> Achaicus, <i>surn. du général rom</i>. Mummius.<br><span>•<i> Cp</i>. ἀχαϊκώτερος, POL. <i>26, 2, 4,</i> plus conforme aux intérêts des Achéens.<br><span><b><span class=\"arrow\"></span></b> <i>Épq. et ion</i>. Ἀχαιϊκός, EUR. <i>Her. 193, mais</i> Ἀχαϊκός, <i>Hec. 521 ; Tr. 657, etc. Dans les inscr. att</i>. Ἀχαιϊκά, CIA. <i>2, 716, A, 7 (330 av. J.C.), à côté de</i> Ἀχαϊκά, <i>ibid. 723, 3 (319 av. J.C</i>.).<br><span><b>Étym</b>. Ἀχαΐα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αχαικος - Ἀχαϊκός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens</li>\n</ul>\n</td></tr>\n</table>","G884":"<h1>acharistos</h1>\n<p>Strong n° 884 <i>Prononciation [ach-ar'-is-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>non gracieux, non miséricordieux\n<ol type=\"a\">\n<li>déplaisant</li>\n<li>ingrat, sans reconnaissance</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀ·χάριστος, ος, ον</b> <span>[χᾰ]</span><br><b>   I</b> (χάρις, grâce) :<br><b>      1</b> sans grâce, sans charme, XÉN. <i>An. 2, 1, 13 (ou mieux</i> ἀχάριτος) ;<br><b>      2</b> <i>p. suite,</i> déplaisant, désagréable, OD. <i>8, 236 ;</i><br><b>      3</b> disgracieux, malveillant, THGN. <i>839 ;</i><br><b>   II</b> (χάρις, reconnaissance) :<br><b>      1</b> <i>act</i>. qui ne témoigne pas de reconnaissance, ingrat, HDT. <i>1, 90, etc. ;</i> EUR. <i>Ion 880 ;</i> τινι, EUR. <i>Hec. 140, ou</i> πρός τινα, XÉN. <i>Mem. 2, 2, 14,</i> ingrat à l’égard de qqn ;<br><b>      2</b> <i>pass</i>. pour qui <i>ou</i> pour quoi l’on ne témoigne pas de reconnaissance, XÉN. <i>An. 1, 9, 18</i>.<br><span>•<i> Cp</i>. ἀχαριστότερος, XÉN. <i>Cyr. 8, 3, 19 ; Œc. 7, 37 ; Sup</i>. ἀχαριστότατος, PLUT. <i>M. 716</i> f.<br><span><b>Étym</b>. ἀ, χαρίζομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αχαριστος - ἀχάριστος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G885":"<h1>Acheim</h1>\n<p>Strong n° 885 <i>Prononciation [akh-ime']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Achim = « Yahvé affermira »\n<ol><li>un des ancêtres de Christ, son nom n'est pas mentionné dans l'Ancien Testament. Vécut après l'exil</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αχιμ</font> &lt; יכין - <font face=\"Georgia\">Ἀχείμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G886":"<h1>acheiropoietos</h1>\n<p>Strong n° 886 <i>Prononciation [akh-i-rop-oy'-ay-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>non fait avec les mains</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀ·χειροποίητος, ος, ον</b>, non fait de main d’homme, NT. <i>Marc. 14, 58 ; 2Cor. 5, 1 ; etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-χειρο-ποιητος - ἀχειροποίητος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G887":"<h1>achlus</h1>\n<p>Strong n° 887 <i>Prononciation [akh-looce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>brume, obscurité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀχλύς, ύος (ἡ)</b> <span>[ᾱ ; ῡ <i>nom. et acc., mais v. ci-dessous ;</i> ῠ <i>gén. et dat</i>.]</span><br><b>   I</b> obscurité, ténèbres, IL. <i>5, 127, etc. ; en parl. du ciel couvert, de l’obscurité causée par les nuages,</i> IL. <i>15, 668 ;</i> OD. <i>20, 357 ;</i> ARSTT. <i>Meteor. 2, 8, 26, etc. ;</i> POL. <i>34, 11, 15 ;</i> STR. <i>274 ;</i><br><b>   II</b> <i>part. :</i><br><b>      1</b> brouillard qui se répand sur les yeux, qui trouble la vue, IL. <i>5, 696 ; 16, 344, etc. ;</i> OD. <i>22, 88 ;</i> HPC. <i>etc. ; c. signe d’un chagrin violent,</i> IL. <i>20, 421 ;</i> CRITI. (ATH. <i>432</i> e) ; <i>en ce sens, personnifié,</i> HÉS. <i>Sc. 264 ; fig</i>. trouble, souci, DC. <i>38, 19 ;</i><br><b>      2</b> <i>au propre,</i> la cataracte (sur les yeux), DIOSC. <i>2, 96</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Acc</i>. ἀχλύν, <i>mais</i> ἀχλύα, ORPH. <i>Arg. 339. — Acc</i>. <span>[ῠν]</span> PROCL. <i>H. Sol. 41</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αχλυς - ἀχλύς</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G888":"<h1>achreios</h1>\n<p>Strong n° 888 <i>Prononciation [akh-ri'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>inutile, bon à rien, sans profit</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀ·χρεῖος, ος, ον :<br>      1</b> qui ne sert à rien, inutile, <i>en parl. de pers</i>. SOPH. <i>O.C. 627 ;</i> EUR. <i>Med. 300 ;</i> THC. <i>1, 74 ; 2, 40 ; etc. ; en parl. de choses,</i> HÉS. <i>O. 401 ;</i> ESCHL. <i>Pr. 363 ;</i> EUR. <i>H.f. 1303 ; El. 883, etc. ; avec un dat. de pers. ou de chose,</i> ἄ. τινι, inutile à qqn, HPC. <i>553, 11 ; ou</i> à qqe ch. AGATHARCH. (ATH. <i>550</i> e) ; <i>avec une prép</i>. ἀ. πρός τι, TH. (ATH. <i>261</i> d) <i>m. sign. ; avec un inf</i>. impropre à, PLAT. <i>Rsp. 371</i> c ; <i>part</i>. impropre à la guerre : τὸ ἀχρήϊον (<i>ion</i>.) στρατοῦ, HDT. <i>1, 191,</i> la partie d’une armée impropre à combattre (services accessoires, invalides, <i>etc.), p. opp. à</i> τὸ καθαρόν ; <i>adv</i>., ἀχρεῖον γελᾶν, OD. <i>18, 163,</i> rire sans motif, <i>càd</i>. faire semblant de rire ;<br><b>      2</b> qui n’est bon à rien, sot, HÉS. <i>O. 295 ; adv</i>. ἀχρεῖον ἰδών, IL. <i>2, 269,</i> regardant d’un air stupide.<br><span>•<i> Cp</i>. ἀχρειότερος, CHRYSIPP. (ATH. <i>285</i> d) ; POLÉM. <i>Physiogn. 1, 5</i>. <i>• Sup</i>. ἀχρειότατος, THC. <i>2, 6 ;</i> PLAT. <i>1 Alc. 122</i> b.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. ἀχρεία, TH. <i>H.P. 4, 8, 3 (var</i>. ἀχρεῖος) ; DIOSC. <i>2, 57 ; 4, 5 ;</i> POLÉM. <i>Physiogn. 2, 14. Épq. et ion</i>. ἀχρήϊος, HÉS. <i>l. c. ;</i> HDT. <i>1, 191 et 211 ; 3, 81 ;</i> HPC. <i>800</i> d, <i>823</i> a.<br><span><b>Étym</b>. ἀ, χρεία.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-χρειος - ἀχρεῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G889":"<h1>achreioo</h1>\n<p>Strong n° 889 <i>Prononciation [akh-ri-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendu inutile, rendre inutilisable\n<ol type=\"a\">\n<li>du caractère</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀχρειόω-ῶ</b> <span>(<i>f</i>. ώσω, <i>ao</i>. ἠχρείωσα, <i>pf</i>. ἠχρείωκα ; <i>pass. ao</i>. ἠχρειώθην, <i>pf</i>. ἠχρείωμαι)</span><br><b>      1</b> rendre inutile, POL. <i>3, 64, 8 ;</i> BAS. <i>2, 48</i> c ; <i>au pass</i>. devenir inutile, POL. <i>1, 14, 6 ; 1, 30, 9 ; 1, 48, 9 ;</i> SPT. <i>Ps. 52, 4 ;</i><br><b>      2</b> mésuser de, <i>d’où</i> corrompre, SPT. <i>Ps. 13, 3</i>.<br><span><b>Étym</b>. ἀχρεῖος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-χρειοω - ἀχρειόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G890":"<h1>achrestos</h1>\n<p>Strong n° 890 <i>Prononciation [akh'-race-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>inutile, sans profit, sans valeur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n① <b>ἄ·χρηστος, ος, ον :<br>A</b> <i>pass. :</i><br><b>   I</b> dont on ne peut pas se servir, <i>càd. :</i><br><b>      1</b> inutile, BATR. <i>70 ;</i> HDT. <i>1, 166, etc. ;</i> HPC. <i>102</i> e, <i>etc. ;</i> ATT. ; ἄ. ἔς τι, HDT. <i>8, 142 ;</i> εἴς τι, LYCURG. <i>154, 33 ;</i> πρός τι, ARSTT. <i>H.A. 6, 2 ;</i> τινος, ARSTT. <i>Œc. 1, 6, 9,</i> qui ne peut être d’aucun usage pour qqe ch. ; ἄ. τινι, HDT. <i>1, 80 ;</i> XÉN. <i>Œc. 8, 4, etc</i>. qui ne peut être d’aucun usage pour qqn ; οὐκ ἄχρηστόν ἐστι, <i>avec l’inf</i>. ARSTT. <i>Categ. 7, fin,</i> il n’est pas inutile de, <i>etc. ; part. en parl. de pers</i>. inutile, oisif, qui n’est bon à rien, LYS. <i>212, 11 ;</i> IS. <i>67, 15 ;</i><br><b>      2</b> <i>p. suite,</i> nuisible, mauvais, funeste, <i>en parl. de divinités,</i> HDT. <i>8, 111 ; ou de choses,</i> HDT. <i>9, 111 ;</i><br><b>   II</b> dont on ne se sert pas, <i>d’où :</i><br><b>      1</b> non employé, inusité, GRAMM. ;<br><b>      2</b> non réalisé, sans effet (oracle), EUR. <i>I.T. 121 ;</i><br><b>      3</b> dont on ne s’est pas encore servi, neuf (vêtement, <i>etc</i>.) LUC. <i>Lex. 9 ;</i> ATH. <i>97</i> e ;<br><b>B</b> <i>act</i>. qui ne se sert pas de, <i>dat</i>. EUR. <i>Tr. 667</i>.<br><span>•<i> Cp</i>. ἀχρηστότερος, DÉM. <i>382 fin</i>. <i>• Sup</i>. ἀχρηστότατος, XÉN. <i>Œc. 8, 4 ;</i> PLAT. <i>Rsp. 398</i> e, <i>487</i> d ; ESCHN. <i>75, 16</i>.<br><span><b>Étym</b>. ἀ, χράομαι.</span><br>\n② <b>ἄ·χρηστος, ος, ον</b>, qui n’a pas reçu de réponse de l’oracle, ATH. <i>98</i> c (<i>avec jeu de mots sur le sens</i> « inutile », <i>v</i>. ἄχρηστος).<br><span><b>Étym</b>. ἀ, χράομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-χρηστος - ἄχρηστος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philémon (1)\n<ul type=\"square\">\n<li>Philémon 1.11</li>\n</ul>\n</li>\n</ul>\n</td></tr>\n</table>","G891":"<h1>achri</h1>\n<p>Strong n° 891 <i>Prononciation [akh'-ree]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>jusqu'à, jusqu'en, depuis</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄχρι</b>, <i>non att</i>. <b>ἄχρις :<br>   I</b> <i>adv</i>., à l’extrémité, <i>d’où :</i><br><b>      1</b> à la surface, IL. <i>17, 590 (sel. d’autres,</i> en pénétrant à l’intérieur) ;<br><b>      2</b> jusqu’au fond, profondément, IL. <i>4, 522 ; 16, 324 ;</i><br><b>   II</b> <i>prép</i>. jusque :<br><b>      1</b> (<i>avec idée de lieu) avec un gén</i>. ἄχρι τῆς ἐσόδου, HDT. <i>2, 138,</i> jusqu’à l’entrée ; ἄχρι τῆς πόλεως, DH. <i>2, 43,</i> jusqu’à la ville (<i>cf</i>. CIA. <i>4, b, 521 a, 500/450 av J.C. ; etc.) ; avec une prép</i>. ἄχρι εἰς, XÉN. <i>An. 5, 5, 4 ;</i> ἄ. πρός, LUC. <i>Herm. 24, etc.,</i> jusque dans, jusque vers ; <i>avec un adv</i>. ἄ. δεῦρο, PLUT. <i>Ant. 34,</i> jusqu’ici ;<br><b>      2</b> (<i>avec idée de temps) avec le gén</i>. ἄ. μάλα κνέφαος, OD. <i>18, 370,</i> jusque profondément dans la nuit ; ἄ. τῆς τήμερον ἡμέρας, DÉM. <i>118, 12,</i> jusqu’au jour d’aujourd’hui ; <i>rar. après le gén</i>. NONN. <i>D. 4, 447 ; 5, 239 ;</i> OPP. <i>H. 1, 83 ; 2, 216 ; avec une prép</i>. ἄ. ἐς ἠῶ, Q. SM. <i>6, 177,</i> jusqu’à l’aurore ; <i>avec un adv</i>. ἄ. νῦν, LUC. <i>Tim. 39 ;</i> SPT. <i>Gen. 44, 28,</i> jusqu’à présent ;<br><b>      3</b> (<i>avec idée de mesure ou de degré</i>) : ἄ. τούτου, DÉM. <i>660,</i> fin, jusqu’à ce point ; ἄ. τοῦ μὴ πεινᾶν, XÉN. <i>Conv. 4, 37,</i> jusqu’à ce qu’on n’éprouve plus la faim ;<br><b>   III</b> <i>conj. :</i><br><b>      1</b> (<i>avec idée de lieu</i>) aussi loin que : διώξας ἄχρι οὗ ἀσφαλὲς ᾤετο εἶναι, XÉN. <i>Cyr. 5, 4, 16,</i> (l’)ayant poursuivi aussi loin qu’il croyait pouvoir le faire sans danger ; <i>cf</i>. TH. <i>H.P. 5, 1, 8 ; etc. ;</i><br><b>      2</b> (<i>avec idée de temps</i>) jusqu’à ce que, tant que, aussi longtemps que, <i>dans les locut</i>. ἄχρι οὗ, <i>avec l’ind</i>. XÉN. <i>Hell. 6, 4, 37 ;</i> ἄχρι οὗ ἄν, <i>avec le sbj</i>. HPC. <i>884</i> f, <i>ou</i> ἄχρι ἄν <i>avec le sbj</i>. HPC. <i>553, fin ;</i> XÉN. <i>An. 2, 3, 2 ;</i> INSCR. <i>att</i>. KE. <i>48, 5 (3<sup>e</sup> s. av. J.C.) ; ou simpl</i>. ἄχρι <i>avec le sbj</i>. HDT. <i>1, 117 (var. avec l’ind.), ou avec le sbj</i>. BION <i>1, 47 ; postér</i>. ἄχρις ὅτε, <i>c</i>. ἄχρι οὗ, <i>avec l’ind. ou l’opt</i>. ZOS. <i>11, 19 ; 113, 12 ; 117, 20</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Chez les poètes épq</i>. ἄχρι <i>et</i> ἄχρις (<i>sel. les besoins du vers). Les deux mots inus. chez les Trag. En prose att. seul</i>. ἄχρι ; <i>postér</i>. ἄχρις <i>plus que</i> ἄχρι.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *me-ǵ<sup>h</sup>sri-, jusqu’à ; <i>degré zéro de</i> μέχρι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αχρι - ἄχρι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n49 fois dans 49 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (4)</li>\n<li>Actes (16)</li>\n<li>Romains (4)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (3)</li>\n<li>Philippiens (2)</li>\n<li>Hébreux (3)</li>\n<li>Apocalypse (10)</li>\n</ul>\n</td></tr>\n</table>","G892":"<h1>achuron</h1>\n<p>Strong n° 892 <i>Prononciation [akh'-oo-ron]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tige de blé dont le grain a été retiré par battage</li>\n<li>paille brisée par la machine à battre, menue paille</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄχυρον, ου (τὸ)</b> <span>[ᾰῠ]</span> paille, chaume, <i>d’ord. au plur</i>. HDT. <i>4, 72 ;</i> XÉN. <i>Œc. 18, 7 ; etc. ; au sg</i>. TH. <i>H.P. 8, 4, 1 ;</i> ANTH. <i>11, 106, 2</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αχυρον - ἄχυρον</font>\n<br><br>vient peut-être de cheo (verser)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G893":"<h1>apseudes</h1>\n<p>Strong n° 893 <i>Prononciation [aps-yoo-dace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans mensonge, sincère, véridique</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀ·ψευδής, ής, ές :<br>      1</b> <i>tr</i>. qui ne ment pas, véridique, vrai, PD. <i>P. 1, 86,</i> ESCHL. <i>Suppl. 246, etc. ; part. en parl. des oracles,</i> HÉS. <i>Th. 233 ;</i> ESCHL. <i>Ch. 559 ;</i> EUR. <i>Or. 364 ;</i> HDT. <i>2, 174, etc. ;</i> ἀ. τέχνη, ESCHL. <i>Sept. 26,</i> la science qui ne trompe pas, <i>càd</i>. la science des devins ;<br><b>      2</b> <i>intr</i>. qui ne se trompe pas, PLAT. <i>Theæt. 160</i> d.<br><span>•<i> Cp</i>. ἀψευδέστερος, EUR. <i>I.T. 571 ;</i> <i>• Sup</i>. ἀψευδέστατος, EUR. <i>H.f. 59</i>.<br><span><b>Étym</b>. ἀ, ψεῦδος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-ψευδης - ἀψευδής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G894":"<h1>apsinthos</h1>\n<p>Strong n° 894 <i>Prononciation [ap'-sin-thos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>absinthe</li>\n<li>le nom d'une étoile qui tomba dans les eaux et les rendit amères</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀψίνθιον, ου (τὸ)</b> absinthe (<i>artemisia absinthium</i> L.) <i>herbe amère,</i> HPC. <i>491, 1, etc</i>. XÉN. <i>An. 1, 5, 1 ;</i> TH. NIC. <i>etc</i>.<br><span><b>Étym</b>. ἄψινθος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αψινθος - ἀψίνθιον</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G895":"<h1>apsuchos</h1>\n<p>Strong n° 895 <i>Prononciation [ap'-soo-khos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans âme, sans vie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄ·ψυχος, ος, ον</b> <span>[ῡ]</span><br><b>      1</b> sans souffle, sans vie, ARCHIL. (STOB. <i>Fl. 64, 12</i>) ; SIM. (ANTH. <i>7, 443</i>) ; EUR. <i>Tr. 619 ;</i> PLAT. <i>Leg. 873</i> e, <i>etc. ;</i> ARSTT. <i>etc. ;</i> ἄ. βορά, EUR. <i>Hipp. 952,</i> nourriture non animale, <i>càd</i>. végétale ;<br><b>      2</b> <i>fig</i>. sans cœur, lâche, ESCHL. <i>Sept. 192 ;</i> XÉN. <i>Cyn. 3, 2, 3, etc. ; en parl. du style,</i> DH. <i>Dem. 20</i>.<br><span>•<i> Cp</i>. ἀψυχότερος, ARSTT. <i>H.A. 9, 1, 30</i>.<br><span><b>Étym</b>. ἀ, ψυχή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-ψυχος - ἄψυχος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G896":"<h1>Baal</h1>\n<p>Strong n° 896 <i>Prononciation [bah'-al]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Baal = « possesseur », « seigneur »\n<ol><li>la suprême divinité mâle des nations Phénicienne et Cananéenne, comme Astarté était la suprême divinité féminine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βαάλ</b>, Baal :<br><b>   I (ὁ) :<br>      1</b> <i>dieu tyrien,</i> JOS. <i>A.J. 9, 6, 6 ;</i><br><b>      2</b> <i>roi tyrien,</i> JOS. <i>A.J. 10, 9, 2 ;</i><br><b>      3</b> <i>n. d’un mois tyrien,</i> SPT. <i>3Reg. 6, 38 ;</i><br><b>   II (ἡ)</b> <i>déesse tyrienne,</i> NT. <i>Rom. 11, 4</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βααλ</font> &lt; בעל - <font face=\"Georgia\">Βάαλ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G897":"<h1>Babulon</h1>\n<p>Strong n° 897 <i>Prononciation [bab-oo-lone']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Babylone (Angl. Babylon) = « confusion »\n<ol>\n<li>très grande et fameuse cité, la résidence des rois Babyloniens, située sur les deux rives de l'Euphrate. Darius Hystaspès, vers 520 av. J.-C. la vainquit et la démantela. Seleucus Nicator conquit la cité en 312 av. J.-C. et finalement hâta sa décadence, en déportant sa population à Séleucie, sa nouvelle capitale, construite avec les matériaux pris à Babylone</li>\n<li>le territoire de Babylonie</li>\n<li>allégoriquement, Rome comme le siège corrompu de l'idolâtrie et l'ennemi du Christianisme</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Βαϐυλών, ῶνος (ἡ)</b> <span>[ᾰῠ]</span><br><b>      1</b> Babylone, <i>capitale de l’Assyrie,</i> HDT. XÉN. <i>etc. ; p. ext</i>. toute ville grande et magnifique, <i>au plur</i>. Βαϐυλῶνες, des Babylones, HDT. <i>3, 160 ;</i> PLUT. LUC. ;<br><b>      2</b> le territoire de Babylone, <i>d’où</i> la Babylonie (<i>cf</i>. Βαϐυλωνία), XÉN. <i>An. 5, 5, 4 ; 7, 8, 25 ;</i> TH. <i>H.P. 2, 6, 2, etc. ;</i> DH. PLUT. <i>etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Βαβυλων</font> &lt; בבל - <font face=\"Georgia\">Βαβυλών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 11 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Actes (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G898":"<h1>bathmos</h1>\n<p>Strong n° 898 <i>Prononciation [bath-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>seuil, marche, rang\n<ol type=\"a\">\n<li>mesure de la qualité, dignité et saine influence dans l'église</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βαθμός, οῦ (ὁ) :<br>   I</b> degré, <i>d’où :</i><br><b>      1</b> degré, marche, SPT. <i>1Reg. 20, 9 ; etc. ;</i><br><b>      2</b> degré d’une échelle, échelon, APD. POL. <i>34, 11 ;</i> ARTÉM. <i>2, 42 ;</i><br><b>      3</b> <i>p. ext</i>. seuil d’une porte, SPT. <i>1Reg. 5, 5 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> degré (d’honneur), <i>càd</i>. grade, dignité, NT. <i>1Tim. 3, 13 ;</i><br><b>      2</b> degré (de généalogie), D. CHR. <i>2, 181 ;</i><br><b>      3</b> degré (d’audace, <i>etc</i>.) JOS. <i>B.J. 4, 3, 10</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *g<sup>w</sup>em-, *g<sup>w</sup>eh₂, aller, <i>v</i>. βαίνω ; <i>avec suff</i>. -θμος, <i>cf</i>. πορθμός, ἰσθμός ; <i>cf</i>. βασμός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαθμος - βαθμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – dénote généralement un mouvement ou une marche, et de toute sorte, aussi bien « venir » et arriver à, que « aller »\n<br><br> – signifie d'une façon primaire « se promener », « marcher », indiquant le moyen de déplacement; « partir »\n<br><br> – exprime le mouvement en général, souvent confiné dans certaines limites, ou donnant la prééminence à la conduite; c'est le mot utilisé pour la marche d'une armée\n<br><br> – accentue toujours l'idée de séparation, de changement de lieu, et n'indique pas, comme le , le mouvement externe et perceptible</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G899":"<h1>bathos</h1>\n<p>Strong n° 899 <i>Prononciation [bath'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>profondeur, hauteur\n<ol type=\"a\">\n<li>de la mer « profonde »</li>\n<li>métaph.\n<ol>\n<li>profond, extrême, pauvreté</li>\n<li>les choses profondes de Dieu</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>βάθος, εος-ους (τὸ)</b> <span>[ᾰ]</span><br><b>      1</b> profondeur : Ταρτάρου, ESCHL. <i>Pr. 1029,</i> du Tartare ; <i>en parl. d’un fleuve,</i> XÉN. <i>Cyr. 7, 5, 5 ; part</i>. profondeur <i>d’une troupe rangée en bataille,</i> XÉN. <i>Hell. 3, 4, 13, etc. ;</i> ἐπὶ βάθος, THC. <i>5, 68, ou</i> ἐς βάθος, ARR. <i>An. 1, 2,</i> en profondeur, en colonne ; τὸ βάθος, NT. <i>Luc. 5, 14,</i> eau profonde, haute mer, <i>p. opp. aux bas-fonds du rivage ; ou</i> profondeur des terres, intérieur d’un pays, <i>p. opp. à la côte,</i> STR. <i>210 ;</i> PTOL. <i>6, 14 ; t. de math</i>. profondeur, <i>p. opp. à</i> longueur <i>ou à</i> largeur : βάθους μετέχειν, PLAT. <i>Rsp. 528</i> b, avoir de la profondeur, <i>càd</i>. être un corps solide, ayant profondeur (comme longueur et largeur) ; ἐκ βάθεος, HDT. <i>1, 186 ;</i> ἐν βάθει, ARSTT. <i>Sens. 3, 14, etc. ;</i> εἰς βάθος, ARSTT. <i>Meteor. 4, 9, 18 ;</i> κατὰ βάθους, ARSTT. <i>Meteor. 1, 3, 5,</i> en profondeur ; <i>au plur</i>. τὰ βάθη, PLAT. <i>Tim. 44</i> d, <i>etc. ;</i> ARSTT. <i>H.A. 8, 15, 3,</i> les profondeurs ; <i>fig</i>. κακῶν βάθος, ESCHL. <i>Pers. 465 (var</i>. βάρος), abîme de maux ; πλούτου β. SOPH. <i>Aj. 130,</i> abondance (<i>litt</i>. profondeur) de richesses ; <i>en parl. de l’esprit,</i> profondeur d’intelligence, PLAT. <i>Theæt. 183</i> e ; profondeur du style, LGN <i>2, 1 ;</i><br><b>      2</b> <i>p. anal. en mesurant de bas en haut,</i> hauteur : αἰθέρος βάθος, EUR. <i>Med. 1297 ;</i> AR. <i>Av. 1715,</i> hauteur des airs ;<br><b>      3</b> <i>p. ext</i>. longueur : τριχῶν, HDT. <i>5, 9,</i> longueur des poils (des chevaux).<br><span><b>Étym</b>. <i>cf</i>. βαθύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">βαθος - βάθος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>"};
